window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s5-584","number":584,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة ابتداء جواب عيسى عليه السلام بقوله: ﴿سبحانك﴾؟","answer":"بدأ بتنزيه الله عن الشريك قبل الدفاع عن نفسه؛ لأن مقالة التأليه اعتداء على توحيد الله أولًا، فقدم حق ربه وأعلن براءته العقدية ثم نفى صدور القول عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص128–129، تحت عنوان «فائدة التعبير بلفظ ﴿سبحانك﴾»","url":""}]},{"id":"s5-585","number":585,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما نكتة التعبير بالمضارع ﴿يكون﴾ في قول عيسى: ﴿ما يكون لي أن أقول ما ليس لي بحق﴾؟","answer":"يفيد المضارع استمرار نفي الصلاحية والملابسة؛ فهذا القول لا يليق بعيسى في زمن من الأزمنة، لا أنه واقعة ماضية نفاها فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص129–130، تحت عنوان «نكتة التعبير بالمضارع ﴿يكون﴾»","url":""}]},{"id":"s5-756","number":756,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"لماذا قال عيسى عليه السلام: ﴿أن أقول﴾ دون «لم أقله»؟","answer":"ليبالغ في التبرؤ؛ فنفى أن يكون له أصلًا حق أو إباحة في أن يقول ذلك، وهذا أبلغ من مجرد نفي وقوع القول في الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص131، تحت عنوان «سر التعبير بقوله: ﴿أن أقول﴾ دون عبارة: «لم أقله»»","url":""}]},{"id":"s5-586","number":586,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"كيف ساق عيسى عليه السلام تعليلات براءته في قوله: ﴿إن كنت قلته فقد علمته﴾؟","answer":"علّق القول بالشرط، ثم رد علمه إلى الله الذي يعلم ما في نفسه؛ فإذا كان الله محيطًا بالباطن فعلمه بالقول الظاهر أولى، فانتظمت الحجة في تفويض العلم إليه وإحكام البراءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص132–133، تحت عنوان «وجه سوق صور تعليلات عيسى»","url":""}]},{"id":"s5-587","number":587,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة التعبير بلفظ النفس في قوله تعالى: ﴿تعلم ما في نفسي ولا أعلم ما في نفسك﴾؟","answer":"المراد بما في نفس عيسى ما استقر في باطنه وخفي من أمره، وبما عند الله ما استأثر بعلمه؛ فدل اللفظ على إحاطة علم الله بعبده وقصور علم العبد عما غاب عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص132، تحت عنوان «دلالة التعبير بلفظ النفس»","url":""}]},{"id":"s5-757","number":757,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة الطباق في قوله تعالى: ﴿تعلم ما في نفسي ولا أعلم ما في نفسك﴾؟","answer":"قابل بين الإثبات في ﴿تعلم﴾ والنفي في ﴿لا أعلم﴾، فبرز التفاوت الكامل بين علم الخالق المحيط وعلم المخلوق المحدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص132–133، تحت عنوان «دلالة الطباق»","url":""}]},{"id":"s5-588","number":588,"surah":5,"verses":[109,116],"references":[{"surah":5,"verses":[109,116]}],"verseLabel":"المائدة: 109، 116","question":"ما وجه المبالغة في قوله تعالى: ﴿علام الغيوب﴾ بدل «عالم الغيوب»؟","answer":"جاءت صيغة المبالغة ﴿علام﴾ ملائمة لجمع ﴿الغيوب﴾ وكثرة المعلومات، فدلت بأقصى ما تتسع له اللغة على سعة علم الله وإحاطته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص134، تحت عنوان «وجه المبالغة في ﴿علام﴾ بدلًا من «عالم»»","url":""}]},{"id":"s5-589","number":589,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]},{"surah":25,"verses":[17]}],"verseLabel":"المائدة: 116؛ الفرقان: 17","question":"ما علة تقديم المسند إليه ﴿أنت﴾ على الخبر الفعلي في قوله تعالى: ﴿أأنت قلت للناس﴾؟","answer":"جُعل الضمير في صدر السؤال لتوجيه الإنكار والتقرير إلى نسبة القول لعيسى نفسه، فتتعلق العناية بتعيين القائل قبل بيان المقولة، وتظهر براءته في جوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص123–124، تحت عنوان «علة تقديم المسند إليه على الخبر الفعلي»","url":""}]},{"id":"s5-590","number":590,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة القصر في قوله تعالى على لسان عيسى: ﴿ما قلت لهم إلا ما أمرتني به﴾؟","answer":"هذا قصر قلب يرد دعوى أنه أمرهم بتأليهه: فقد قال ما أمره الله به وبلّغ رسالة ربه، ولم يقل شيئًا من عنده، مع نفي الزيادة على ما أُمر به؛ فدعوى الألوهية لا تجتمع مع اعترافه بالوحدانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص140–141، تحت عنوان «دلالة قصر القلب»","url":""}]},{"id":"s5-591","number":591,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة ﴿أن﴾ في قوله تعالى: ﴿ما أمرتني به أن اعبدوا الله﴾؟","answer":"تحتمل أن تكون تفسيرية لما في الأمر من معنى القول، وتحتمل أن تكون مصدرية؛ أي ما أمرتني به من عبادتكم لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص141، تحت عنوان «دلالة ﴿أن﴾»","url":""}]},{"id":"s5-758","number":758,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما نكتة البدل في قوله تعالى: ﴿أن اعبدوا الله ربي وربكم﴾؟","answer":"جاءت الجملة بدلًا أو بيانًا من ﴿ما أمرتني به﴾، فكشفت مضمون الأمر الإلهي وحددته بعبادة الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص142، تحت عنوان «نكتة البدل»","url":""}]},{"id":"s5-759","number":759,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"لماذا قدّم عيسى إثبات ربوبية الله له على إثبات ربوبيته لقومه في قوله: ﴿ربي وربكم﴾؟","answer":"بدأ بنفسه ليعلن عبوديته وأنه مربوب لله قبل أن يدعو قومه إلى العبادة، فيبطل من أصل الكلام ادعاء ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص142–143، تحت عنوان «نكتة تقديم إثبات ربوبية الله له على إثبات ربوبيته لهم»","url":""}]},{"id":"s5-592","number":592,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة وصف عيسى نفسه بقوله: ﴿وكنت عليهم شهيدًا ما دمت فيهم﴾ دون: شاهدًا؟","answer":"﴿شهيد﴾ أبلغ في ثبوت الشهادة والمراقبة واستحضار ما وقع، وقيّدها بمدة وجوده بينهم ليحدد نطاق علمه ومسؤوليته البشرية؛ فهو يشهد بما عاينه لا بما استتر بعد رفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص143، تحت عنوان «سر التعبير بلفظ ﴿شهيدًا﴾»","url":""}]},{"id":"s5-593","number":593,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة التعبير عن انتهاء مقام عيسى بين قومه بقوله تعالى: ﴿فلما توفيتني﴾؟","answer":"التوفي في أصل اللغة أخذ الشيء وافيًا، والسياق هنا يدل على انتهاء مدة إقامة عيسى بين قومه وشهادته عليهم. واللفظ يأتي للموت والنوم والرفع، وقد رجحت الموسوعة في شرح الموضع أن المراد وفاة الرفع إلى السماء؛ فلا يدل أصل اللفظ وحده على تفاصيل الكيفية دون قرائن السياق وبقية الأدلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145، تحت عنوان «دلالة التعبير بلفظ ﴿توفيتني﴾»","url":""}]},{"id":"s5-594","number":594,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما سر العدول من ﴿شهيدًا﴾ إلى ﴿الرقيب﴾ في قول عيسى عليه السلام؟","answer":"شهادة عيسى مقيدة بمدة وجوده في قومه، أما رقابة الله فدائمة محيطة بهم قبل ذلك وبعده؛ فناسب العدول اختلاف المقامين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص144، تحت عنوان «سر العدول من لفظ ﴿الشهيد﴾ إلى لفظ ﴿الرقيب﴾»","url":""}]},{"id":"s5-760","number":760,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما فائدة ضمير الفصل ﴿أنت﴾ في قوله تعالى: ﴿كنت أنت الرقيب عليهم﴾؟","answer":"أكد الضمير اختصاص الله بالرقابة التامة المستمرة بعد توفي عيسى، وقصر هذا الإحاطة عليه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145، تحت عنوان «فائدة التعبير بضمير الفصل ﴿أنت﴾»","url":""}]},{"id":"s5-761","number":761,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما سر دخول «أل» على ﴿الرقيب﴾ في قوله تعالى: ﴿كنت أنت الرقيب عليهم﴾؟","answer":"أفاد التعريف كمال هذا الوصف وتحققه في الله؛ فهو الرقيب المحيط الذي لا يغيب عنه شيء من أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145–146، تحت عنوان «سر دخول «أل» على كلمة ﴿الرقيب﴾»","url":""}]},{"id":"s5-595","number":595,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة تقديم الجار والمجرور في قوله تعالى: ﴿وأنت على كل شيء شهيد﴾؟","answer":"قدم ﴿على كل شيء﴾ للاهتمام بعموم متعلَّق الشهادة وإبراز إحاطة علم الله بكل ظاهر وباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص147، تحت عنوان «دلالة تقديم الجار والمجرور»","url":""}]},{"id":"s5-762","number":762,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما براعة رد العجز على الصدر في قوله تعالى: ﴿وأنت على كل شيء شهيد﴾؟","answer":"عاد ختام الكلام إلى لفظ الشهادة الذي ورد في قول عيسى: ﴿وكنت عليهم شهيدًا﴾، فانتظم طرفا المعنى مع بيان الفرق بين شهادته المحدودة وشهادة الله العامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص147–148، تحت عنوان «براعة رد العجز على الصدر»","url":""}]},{"id":"s5-763","number":763,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة الاعتراض التذييلي في قوله تعالى: ﴿وأنت على كل شيء شهيد﴾؟","answer":"جاءت الجملة تذييلًا يعمم الحكم بعد خصوص الرقابة على قوم عيسى، ويقرر إحاطة شهادة الله بكل شيء في كل وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص148، تحت عنوان «دلالة الاعتراض التذييلي»","url":""}]},{"id":"s5-596","number":596,"surah":5,"verses":[117],"references":[{"surah":3,"verses":[55]},{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117؛ آل عمران: 55","question":"ما الفرق بين قول عيسى عليه السلام: ﴿فلما توفيتني﴾، وقول الله له: ﴿إني متوفيك ورافعك إلي﴾؟","answer":"في آل عمران يرد التوفي والرفع في وعد الله لعيسى، ويستشهد المصدر بهذه الآية عند تفسير قوله في المائدة «فلما توفيتني». أما في المائدة فالتعبير يحدد انتهاء مدة إقامته في قومه وشهادته عليهم، ويرجح المصدر أن المراد توفي الرفع إلى السماء. فالأول وعد بالقبض والرفع، والثاني حكاية انتهاء مقامه بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145، تحت «دلالة التعبير بلفظ توفيتني»","url":""}]},{"id":"s5-597","number":597,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"لماذا فُصل قوله تعالى: ﴿إن تعذبهم فإنهم عبادك﴾ عما قبله؟","answer":"جاء استئنافًا بيانيًا يجيب عما قد يثيره المقام: هل يشفع عيسى لقومه؟ ففوض أمرهم كله إلى الله في التعذيب والمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص152، تحت عنوان «علة فصل قوله تعالى: ﴿إن تعذبهم فإنهم عبادك﴾ عما قبله»","url":""}]},{"id":"s5-764","number":764,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما سر إيثار قوله تعالى: ﴿فإنهم عبادك﴾ في مقام التعذيب؟","answer":"العبودية تثبت تمام ملك الله لهم وانفراده بالتصرف والحكم، فليس لأحد أن يعترض على ما يقضي به فيهم وفق عدله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص153، تحت عنوان «سر إيثار التعبير بقوله تعالى: ﴿فإنهم عبادك﴾»","url":""}]},{"id":"s5-765","number":765,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما دلالة الفاء والتأكيد في قوله تعالى: ﴿فإنهم عبادك﴾؟","answer":"ربطت الفاء جواب الشرط بالتعليل، وأكدت ﴿إن﴾ ثبوت عبوديتهم واستسلام الأمر لله، فاشتد معنى التفويض إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص153–154، تحت عنوان «دلالة الفاء ودلالة التأكيد»","url":""}]},{"id":"s5-598","number":598,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما وجه التناسب في قوله تعالى: ﴿وإن تغفر لهم فإنك أنت العزيز الحكيم﴾؟","answer":"ناسب ذكر العزة أن المغفرة تصدر عن قدرة لا عن عجز عن العقوبة، وناسبت الحكمة أن المغفرة توضع في موضعها لمن تقتضي الحكمة مغفرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص155، تحت عنوان «فن التخيير والتناسب»","url":""}]},{"id":"s5-766","number":766,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما أهمية قصر صفتي العزة والحكمة على الله في قوله: ﴿فإنك أنت العزيز الحكيم﴾؟","answer":"اجتمع التوكيد وضمير الفصل وتعريف الوصفين لإثبات كمال العزة والحكمة لله وحده، وأن حكمه لا يرده أحد ولا يخرج عن موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص156، تحت عنوان «أهمية قصر صفتي العزة والحكمة على الله دون سواه»","url":""}]},{"id":"s5-767","number":767,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما الكناية في وصف الله تعالى بـ﴿العزيز﴾ في مقام المغفرة؟","answer":"الوصف كناية عن أن مغفرته صادرة عن تمام القدرة والغلبة؛ فهو يغفر مع القدرة على العقوبة، لا عن ضعف أو عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص156–157، تحت عنوان «براعة الكناية في قوله تعالى: ﴿فإنك أنت العزيز الحكيم﴾»","url":""}]},{"id":"s5-599","number":599,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما سرّ تقديم احتمال العذاب على المغفرة في قول عيسى عليه السلام؟","answer":"قُدّم العذاب لأن الآية جاءت بعد الوعيد الشديد لمن يكفر بعد نزول المائدة، ولأنها في سياق تبرؤ عيسى من مقالة طائفة من النصارى نسبت إليه دعوة الناس إلى اتخاذه وأمه إلهين؛ فناسب البدء بما يوافق سياق الوعيد والتبرؤ، ثم فُوض أمر المغفرة إلى مشيئة الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص154–155، تحت «دلالة تقديم لفظ التعذيب على لفظ المغفرة»","url":""}]},{"id":"s5-600","number":600,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿فإنك أنت العزيز الحكيم﴾؟","answer":"يفيد ﴿أنت﴾ توكيد اختصاص الله بكمال العزة والحكمة؛ فهو وحده القادر على إنفاذ العذاب أو المغفرة، العالم بموضع كل منهما، وليس لعيسى إلا التسليم لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص156، تحت «أهمية قصر صفتي العزة والحكمة على الله دون سواه»","url":""}]},{"id":"s5-601","number":601,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"لماذا قيل: ﴿هذا يوم ينفع الصادقين صدقهم﴾ دون «صدقت»؟","answer":"عدل إلى الاسم ليكون الحكم عامًا في الصدق، وليشهد لعيسى الذي برأ نفسه بصدق كامل، ويدخل فيه كل صادق في إيمانه وقوله وعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص164، تحت عنوان «سر التعبير بقوله تعالى: ﴿ينفع الصادقين صدقهم﴾ دون: «صدقت»»","url":""}]},{"id":"s5-768","number":768,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة التعريف في لفظ ﴿الصادقين﴾؟","answer":"أفاد استغراق جنس الصادقين الكاملين في صدقهم، فشمل أهل الإيمان الذين وافق ظاهرهم باطنهم واستقام قولهم وعملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص164–165، تحت عنوان «دلالة اللام في ﴿الصادقين﴾»","url":""}]},{"id":"s5-602","number":602,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة الإشارة في قوله تعالى: ﴿هذا يوم ينفع الصادقين صدقهم﴾ كأن اليوم حاضر؟","answer":"استحضرت الإشارة يوم القيامة حتى صار كالمشاهد القريب، ولا سيما بعد الحوار المعروض بين الله وعيسى؛ فيقوى اليقين بالجزاء ويشعر السامع أن الحكم يعلن أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص163، تحت «سر التعبير باسم الإشارة هذا ودلالة المشاكلة»","url":""}]},{"id":"s5-604","number":604,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة التعطف في قوله تعالى: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"صور رضا الله عن عباده وما قابلوه به من رضا عن جزائه وفضله، فاجتمع الإكرام الإلهي وطمأنينة العباد بما أعطاهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص170، تحت عنوان «دلالة التعطف»","url":""}]},{"id":"s5-769","number":769,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما براعة الترقي في الانتقال من الجنات إلى قوله تعالى: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"ترقى السياق من نعيم الجنات الحسي إلى نعيم الرضوان الأعلى؛ فرضا الله أعظم من كل ما في الجنة من نعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص169–170، تحت عنوان «براعة الترقي في الآية الكريمة»","url":""}]},{"id":"s5-605","number":605,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما سر التعبير باسم الإشارة البعيد ﴿ذلك﴾ في قوله تعالى: ﴿ذلك الفوز العظيم﴾؟","answer":"استعمل اسم البعيد لتعظيم المشار إليه ورفع منزلته، وهو مجموع الخلود في الجنات ورضا الله عن الصادقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص170، تحت عنوان «سر التعبير باسم الإشارة ﴿ذلك﴾»","url":""}]},{"id":"s5-770","number":770,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة التعريف في لفظ ﴿الفوز﴾؟","answer":"يفيد أن هذا هو الفوز المعروف الكامل الذي يجمع حصول أعظم المطلوب والنجاة من أعظم المرهوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص170–171، تحت عنوان «دلالة اللام في ﴿الفوز﴾»","url":""}]},{"id":"s5-771","number":771,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة وصف الفوز بـ﴿العظيم﴾؟","answer":"عظمه لأنه يضم الخلود في النعيم ورضا الله، فلا يساويه نجاح مؤقت ولا نعيم زائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص171، تحت عنوان «دلالة وصف الفوز بالعظمة»","url":""}]},{"id":"s5-606","number":606,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]}],"verseLabel":"المائدة: 120","question":"ما مناسبة ختم السورة بملك الله للسماوات والأرض؟","answer":"بعد محاجة من ألّه المسيح وأمه، وخضوع الرسل للحساب، ختمت السورة بأن الملك كله لله؛ فكل من في السماوات والأرض مملوك له، وبذلك يعود ختام السورة إلى أصل التوحيد الذي حسم حوارها الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص181، تحت عنوان «بلاغة حسن ختام السورة»","url":""}]},{"id":"s5-607","number":607,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]},{"surah":42,"verses":[49]}],"verseLabel":"المائدة: 120؛ الشورى: 49","question":"ما دلالة زيادة ﴿وما فيهن﴾ في خاتمة المائدة: ﴿لله ملك السماوات والأرض وما فيهن﴾، وعدم ذكرها في موضع الشورى؟","answer":"صرحت المائدة بـ﴿وما فيهن﴾ لأنها جاءت في ختام الرد على من اتخذ عيسى وأمه إلهين، فناسب المبالغة في بيان سعة ملك الله ودحض شبهة مشاركته فيه. أما الشورى فلم يسبق آية الملك فيها ذكر شرك أو منازعة في الملك، فناسب عدم ذكر العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص181–182، تحت «دلالة ذكر عبارة وما فيهن في آية سورة المائدة دون آية سورة الشورى»","url":""}]},{"id":"s5-608","number":608,"surah":5,"verses":[17,18,120],"references":[{"surah":5,"verses":[17,18,120]}],"verseLabel":"المائدة: 17–18، 120","question":"ما سر تذييل قوله تعالى: ﴿إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعًا﴾ بذكر ملك السماوات والأرض؟","answer":"جاء ذكر الملك والخلق بعد الشرط ونفي المانع ليقرر أن المسيح وأمه وسائر الخلق مملوكون لله، وأن قدرته نافذة فيهم ولا يملك أحد رد إرادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص734–735، تحت عنوان «سر التذييل بذكر الملك والخلق بعد الشرط ونفي المانع»","url":""}]},{"id":"s5-609","number":609,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]}],"verseLabel":"المائدة: 120","question":"لماذا قيل ﴿وما فيهن﴾ ولم يقل: ومن فيهن؟","answer":"«ما» أعم في هذا المقام؛ فتتناول العاقل وغير العاقل، بخلاف «من» المختصة في أصل وضعها بالعقلاء. وفيها تقرير شمول ملك الله لكل ما في السماوات والأرض، والتنبيه إلى افتقار المخلوقات جميعًا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص179، تحت عنوان «سر التعبير بقوله تعالى: ﴿وما فيهن﴾ عوضًا عن «ومن فيهن»»","url":""}]},{"id":"s5-610","number":610,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]}],"verseLabel":"المائدة: 120","question":"لماذا ختمت آية المائدة بـ﴿قدير﴾، وجاء في الأنعام ﴿وكيل﴾، وفي سبأ ﴿شهيد﴾؟","answer":"ناسب ﴿قدير﴾ في المائدة ذكر الملك الشامل، فالملك لا يقوم إلا بتمام القدرة. وناسب ﴿وكيل﴾ في الأنعام مقام الخلق والرزق والقيام بأمر العباد، وناسب ﴿شهيد﴾ في سبأ مقام تبليغ الرسول وشهادة الله على صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص182–183، تحت عنوان «تغير الأسماء الحسنى بين ﴿قدير﴾ و﴿وكيل﴾ و﴿شهيد﴾ في مواقعها من سورها»","url":""}]},{"id":"s5-772","number":772,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة التعبير بلفظ «الفِسْق» في ﴿ذَٰلِكُمْ فِسْقٌ﴾ دون «الفُسوق»؟","answer":"ورد «الفسق» في القرآن في سياق الأطعمة وبخاصة الذبائح، كآية المائدة هذه وآيتي الأنعام 145 و121. أما «الفسوق» فورد للخروج عن طاعة الله عامة، كقوله: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ﴾. فاستعمل الفسوق لما هو أعم، وكأنه لما زاد في المعنى زاد في البناء.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص20.","url":""}]},{"id":"s5-773","number":773,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سر عطف ﴿وَأَرْجُلَكُمْ﴾ على الوجوه في الغسل مع الفصل بينهما بالمسح بالرؤوس؟","answer":"هذا العطف صحيح كثير في القرآن وغيره، كعطف ﴿وَحِينَ تُظْهِرُونَ﴾ على ﴿حِينَ تُمْسُونَ﴾ في الروم مع ما بينهما، وكآية الكرسي وآية البر. والغرض منه في آية الوضوء إرادة الترتيب، فيجب أن تكون أعمال الوضوء مرتبة بحسب ما ذكره القرآن الكريم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص51–53.","url":""}]},{"id":"s5-774","number":774,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما سر النداء بـ﴿يَا قَوْمِ﴾ في قول موسى في المائدة، وخلوّ آية إبراهيم منه؟","answer":"عدّد عليهم في المائدة نعمًا جسامًا: جعل فيهم أنبياء وجعلهم ملوكًا، والإنسان يحب أن ينتسب إلى قوم ذوي رفعة، بخلاف آية إبراهيم التي ذكّرتهم بأيام ذلّهم. ثم طلب منهم دخول الأرض المقدسة، فناداهم بـ«يا قوم» عطفًا لقلوبهم حين كلّفهم هذا الأمر الشاق. وزاد ذلك حسنًا طولُ القصة في المائدة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص120–121؛ وفاضل السامرائي، على طريق التفسير البياني، ج1، ص211. الآيات 26 – 54","url":""}]},{"id":"s5-775","number":775,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما سر تقديم «الخزي» على «الدنيا» في ﴿ذَٰلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا﴾، وتأخيره في آيتي البقرة والحج ﴿لَهُمْ فِي الدُّنْيَا خِزْيٌ﴾؟","answer":"الخزي المذكور في آية المائدة أظهر للعيان وأثبت، فهو التقتيل والتصليب وقطع الأيدي والأرجل من خلاف والنفي من الأرض. أما في البقرة فهو خوف مقارن للدخول، والخوف أمر قلبي غير ظاهر، وفي الحج لم يذكر نوع الخزي. فناسب تقديم الخزي الأظهر والأشد في آية المائدة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص15–16.","url":""}]},{"id":"s5-776","number":776,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما سر التعبير بـ﴿بَهِيمَةُ الْأَنْعَامِ﴾ في المائدة، وبـ﴿الْأَنْعَامُ﴾ مجردةً في سورة الحج؟","answer":"البهيمة اسم لكل ذي أربع من دواب البر والبحر، وإضافتها إلى الأنعام من إضافة العام إلى الخاص للبيان، كـ«يوم الخميس» و«مدينة بغداد». وقد ورد التركيب «بهيمة الأنعام» في ثلاثة مواضع كلها في سياق المناسك والإحرام والحج. أما «الأنعام» فوردت في سياقات كثيرة كالأكل وشرب الألبان والركوب والتشبيه. فلما كانت الإضافة للتخصيص استعملها فيما هو أخصّ، وهو المناسك والحج.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص36–38.","url":""}]},{"id":"s5-777","number":777,"surah":5,"verses":[26,68],"references":[{"surah":5,"verses":[26,68]}],"verseLabel":"المائدة: 26، 68","question":"ما سر الختم بـ﴿فَلَا تَأْسَ عَلَى الْقَوْمِ الْفَاسِقِينَ﴾ في الآية 26، وبـ﴿الْكَافِرِينَ﴾ في الآية 68 من السورة نفسها؟","answer":"الآية الأولى في قوم موسى الذين نكلوا عن قتال الجبارين، وهم ليسوا كافرين بل فاسقون لمخالفتهم أمر الله في القتال. والوصف مجانس لقول موسى: ﴿فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِقِينَ﴾. أما الثانية فخطاب للرسول ﷺ في أهل الكتاب الذين لم يؤمنوا به، وقد ذكر أن ما أُنزل إليه يزيدهم ﴿طُغْيَانًا وَكُفْرًا﴾، فوصفهم بالكفر.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص53–54.","url":""}]},{"id":"s5-778","number":778,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"ما دلالة تعدية الفعل «تقبّل» بـ«مِن» في ﴿فَتُقُبِّلَ مِنْ أَحَدِهِمَا﴾، وتعديته بـ«عَن» في الأحقاف ﴿نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا﴾؟","answer":"تعديته بـ«مِن» تدل على العناية بالذات أو الجهة التي يُتقبَّل منها، وتعديته بـ«عَن» تدل على العناية بالعمل الصادر عنها. ولذلك حيث عدّاه بـ«مِن» لم يذكر له مفعولًا أو بناه للمجهول كما في قصة ابنَي آدم، وحيث عدّاه بـ«عَن» ذكر العمل، وهي الآية الوحيدة في القرآن.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص54–55.","url":""}]},{"id":"s5-779","number":779,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما سر إضافة الرسل إلى ضميره سبحانه في ﴿وَلَقَدْ جَاءَتْهُمْ رُسُلُنَا بِالْبَيِّنَاتِ﴾، وإضافتهم إلى القوم في الأعراف ﴿رُسُلُهُم﴾؟","answer":"آية المائدة فيما شرع الله من الأحكام التي جاءت بها الرسل من عنده، كحكم القتل وحدّ الحرابة المذكور بعدها، فأضاف الرسل إليه. أما آية الأعراف فالكلام فيها على أهل القرى وموقفهم من رسلهم الذين جاؤوهم بما ينفعهم، فأضافهم إليهم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص40–41.","url":""}]},{"id":"s5-780","number":780,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما سر وصف التوراة بأن فيها ﴿نُورٌ﴾ في المائدة، ووصفها بـ﴿ضِيَاءً﴾ في سورة الأنبياء؟","answer":"النور أعمّ من الضياء، والضياء الساطع من النور أو التام منه. وآية الأنبياء خُصّت بالمتقين الذين يخشون ربهم بالغيب، أما آية المائدة ففي حكم النبيين بها ﴿لِلَّذِينَ هَادُوا﴾ عامة. فناسب العمومُ العمومَ، والخصوصُ الخصوصَ، فالمتقون من عموم المؤمنين كالضياء من النور.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص133–134.","url":""}]},{"id":"s5-781","number":781,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"ما دلالة زيادة ﴿عَلَىٰ آثَارِهِم﴾ في ﴿وَقَفَّيْنَا عَلَىٰ آثَارِهِم بِعِيسَى ابْنِ مَرْيَمَ﴾، وخلوّ آية الحديد منها؟","answer":"آية الحديد في تقفية الرسل، وآية المائدة في تقفية الربانيين والأحبار الذين ذُكروا قبلها. والربانيون والأحبار لم ينقطعوا، فقفّى على آثارهم بعيسى أي ليس بينهم وبينه مدة فاصلة، بخلاف ما بينه وبين الرسل فإن بينهم مدة ليست بالقليلة. ونقل عن «التحرير والتنوير» أن أصل «قفّى على أثره» يدل على قرب ما بين الماشيَين.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص294–295.","url":""}]},{"id":"s5-782","number":782,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما سر تعدية ﴿أَذِلَّةٍ﴾ بـ«على» في ﴿أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ﴾، والأصل أن يُعدّى باللام؟","answer":"لو عدّاه باللام لكان ذمًّا، لأن قولك «هو ذليل له» يفيد الذم، والمقام مقام مدح. فجاء بـ«على» للإشعار بالذلّة المستعلية، أي أنهم يخفضون جناحهم للمؤمنين مع علوّ جانبهم وارتفاع مكانتهم. ونقل عن «الكشاف» أيضًا تضمينَ الذلّ معنى الحنوّ والعطف.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص206–207.","url":""}]},{"id":"s5-783","number":783,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"ما دلالة التعبير بـ﴿أَكْثَرَكُمْ فَاسِقُونَ﴾ بلفظ «أكثر»، وقد جاء في مواضع أخرى بلفظ «كثير منهم»؟","answer":"يعبّر القرآن بـ«أكثر» إذا كان السياق في تعداد أسوأ صفاتهم والإطالة في ذكرها، بخلاف «كثير» الذي لا يبلغ هذا المبلغ. وسياق المائدة يذكر اتخاذهم الدين والصلاة هزوًا ولعبًا، ولعنهم والغضب عليهم ومسخ بعضهم قردة وخنازير، ومسارعتهم في الإثم وأكل السحت، ويستمر في تعداد مساوئهم إلى الآية 65، فناسب قوله ﴿أَكْثَرَكُمْ﴾.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص269–270.","url":""}]},{"id":"s5-784","number":784,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما سر الاستفهام بـ«هل» في ﴿قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ اللَّهِ﴾، وبالهمزة في سورة الحج ﴿أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ﴾؟","answer":"يستعمل القرآن «هل» لما هو أقوى وآكد في الاستفهام. وفي سياق المائدة قوة وتبكيت لا تجدهما في آية الحج: ذكر أنهم اتخذوا الدين والنداء إلى الصلاة هزوًا ولعبًا، ووصفهم بالفسق وعدم العقل، وأن الله لعنهم وغضب عليهم ومسخ منهم، ثم قال ﴿أُولَٰئِكَ شَرٌّ مَّكَانًا﴾. فجاء بـ«هل» الآكد في المقام الأشد.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص151–152.","url":""}]},{"id":"s5-785","number":785,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما الفرق بين «الإثم» و«العدوان» في ﴿وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَارِعُونَ فِي الْإِثْمِ وَالْعُدْوَانِ﴾؟","answer":"العدوان معناه الظلم والإخلال بالمعاملة، وهو يتعلق بالغير. أما الإثم فعامّ، قد يكون تعديًا على حقوق الغير وقد لا يكون، فهو عموم الذنب. وكثيرًا ما يقترن الإثم بالعدوان في القرآن، كما تقترن البغضاء بالعداوة في الآية 64.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص17–18.","url":""}]},{"id":"s5-786","number":786,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما دلالة لفظ «واحد» في ﴿وَمَا مِنْ إِلَٰهٍ إِلَّا إِلَٰهٌ وَاحِدٌ﴾، وفي سورة الإخلاص ﴿أَحَدٌ﴾؟","answer":"يستعمل القرآن «واحد» في وصف الله تعالى لما يقابل الاثنين والثلاثة وعموم التعدد، فناسب الردّ على الذين قالوا ﴿إِنَّ اللَّهَ ثَالِثُ ثَلَاثَةٍ﴾. أما «أحد» فلا يقع إلا لأولي العلم والعقل، وهو أنسب في سورة الإخلاص. فكان استعمال كل لفظة في مكانها أنسب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص61.","url":""}]},{"id":"s5-787","number":787,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما سر مجيء ﴿وَاللَّهُ غَفُورٌ رَّحِيمٌ﴾ بغير توكيد بـ«إنّ»، وقد جاء في آيات أخرى ﴿إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ﴾؟","answer":"الآية في سياق تهديد الذين قالوا إن الله ثالث ثلاثة، وقد توعدهم بأنهم إن لم ينتهوا ليمسّنهم عذاب أليم، ثم دعاهم إلى التوبة. فالمقام مقام تهديد وتوعد لا مقام توكيد المغفرة، بخلاف آية البقرة في سياق الحج التي أكّدت فيها المغفرة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص138–139.","url":""}]},{"id":"s5-788","number":788,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما سر تقديم ﴿غَفُورٌ﴾ على ﴿رَّحِيمٌ﴾ في ختام هذه الآية؟","answer":"المغفرة تخصّ المكلفين، والرحمة أمر عام تشمل المكلفين والبهائم وسائر الأحياء. وجميع المواطن التي تقدّم فيها «الغفور» على «الرحيم» تقدّم فيها ذكر المكلفين، ومنها هذه الآية: ﴿أَفَلَا يَتُوبُونَ إِلَى اللَّهِ وَيَسْتَغْفِرُونَهُ﴾، فقدّم ما يخصّهم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص139.","url":""}]},{"id":"s5-789","number":789,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"ما سر التعبير بـ﴿غَيْرَ الْحَقِّ﴾ في ﴿لَا تَغْلُوا فِي دِينِكُمْ غَيْرَ الْحَقِّ﴾، وفي النساء ﴿وَلَا تَقُولُوا عَلَى اللَّهِ إِلَّا الْحَقَّ﴾؟","answer":"لا يصحّ أن يُقال «لا تغلوا في دينكم إلا الحق»، لأن المعنى يصير أن من الغلو حقًّا، والغلو في الدين لا يكون حقًّا بحال. أما القول على الله فقد يكون حقًّا وقد يكون باطلًا، فصحّ الاستثناء في النساء. و«غير» في المائدة صفة مؤكدة لمصدر محذوف أي «غلوًّا غيرَ الحق»، أو حال أي مجاوزين الحد.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص36.","url":""}]},{"id":"s5-790","number":790,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما سر فتح العين في ﴿أَوْ عَدْلُ ذَٰلِكَ صِيَامًا﴾؟","answer":"«العَدْل» بالفتح هو المساواة في الأحكام وما لا يُبصَر، و«العِدْل» بالكسر فيما يُدرك بالحاسة كالموزونات والمعدودات والمكيلات. فقال ﴿عَدْلُ ذَٰلِكَ صِيَامًا﴾ بالفتح لأن الصيام لا يُبصَر بالحاسة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص132–133.","url":""}]},{"id":"s5-791","number":791,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما سر تعريف «الكذب» في ﴿وَلَٰكِنَّ الَّذِينَ كَفَرُوا يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ﴾، وتنكيره في مثل ﴿مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا﴾؟","answer":"عرّف الكذب لأنه مخصّص بمسألة معينة هي مسألة الأنعام: البحيرة والسائبة والوصيلة والحام. أما حيث جاء منكّرًا، كآية الأنعام ﴿وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا﴾، فالكذب عام لم يُخصَّص بمسألة معينة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص195.","url":""}]},{"id":"s5-792","number":792,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما سر التعبير بـ﴿إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ﴾ بلفظ «الحضور» لا «المجيء»؟","answer":"يستعمل القرآن حضور الموت مع الوصايا والأحكام، أما مجيء الموت فيستعمله لذكر ما يتعلق بالموت نفسه وأحوال الناس فيه وفيما بعده. وآية المائدة في الوصية والإشهاد عليها، لا في أمر يتعلق بالموت، فكأن الموت يكون شاهدًا مع من يشهد.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص193–194.","url":""}]},{"id":"s5-793","number":793,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"ما سر مجيء ﴿وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ﴾ بغير توكيد، وفي سورة المنافقون ﴿إِنَّ اللَّهَ لَا يَهْدِي﴾؟","answer":"آيات سورة المنافقون أشد الآيات تبكيتًا وذمًّا، فقد فصّلت سوءاتهم من الكذب والصدّ عن سبيل الله والاستكبار، فناسب ذلك التوكيد. أما آية المائدة ففي المسلمين في سياق الشهادة على الوصية، فلا تحتاج إلى مثل هذا التوكيد.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص81–82.","url":""}]},{"id":"s5-794","number":794,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة القصر وذكر المبتدأ في ﴿إِنْ هَٰذَا إِلَّا سِحْرٌ مُّبِينٌ﴾، وحذفه في سورة القمر ﴿وَيَقُولُوا سِحْرٌ مُّسْتَمِرٌّ﴾؟","answer":"يقتضي السياق الحذف إذا كان الكلام موجزًا والمعنى واضحًا، ويقتضي الذكر في مقام التفصيل أو التوكيد. وآية المائدة فصّلت الآيات التي أُوتيها عيسى: النفخ في الطين وإبراء الأكمه والأبرص وإخراج الموتى، فاقتضى ذلك الذكر والقصر. بخلاف آية القمر التي لم تذكر آية مفصّلة وإنما ذكرت إعراضهم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص234–235.","url":""}]},{"id":"s5-795","number":795,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما سر إثبات النون في ﴿وَاشْهَدْ بِأَنَّنَا مُسْلِمُونَ﴾، وحذفها في آل عمران ﴿وَاشْهَدْ بِأَنَّا مُسْلِمُونَ﴾؟","answer":"آية المائدة فصّلت فيما يجب الإيمان به: ﴿أَنْ آمِنُوا بِي وَبِرَسُولِي﴾، فناسب ذلك أن تأتي «أننا» على أوفى الحالين وهو الأصل. وفي آل عمران لم يقع هذا التفصيل ﴿آمَنَّا بِاللَّهِ﴾، فناسب الإيجازُ الإيجازَ. ويضاف إلى ذلك أن الله هو الذي أوحى إلى الحواريين في المائدة وثبّتهم، فناسب زيادة النون تأكيدًا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص78.","url":""}]},{"id":"s6-1","number":1,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما مناسبة افتتاح سورة الأنعام بقوله تعالى: ﴿الحمد لله﴾؟","answer":"افتتحت السورة بالحمد براعة استهلال؛ لأن مقصدها تقرير التوحيد بإظهار نعمتي الإيجاد والإمداد، ومن دلائلهما خلق السماوات والأرض وجعل الظلمات والنور.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص202، تحت عنوان «براعة الاستهلال في افتتاح السورة»","url":""}]},{"id":"s6-1036","number":1036,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما بلاغة مجيء ﴿الحمد لله﴾ في افتتاح الأنعام خبرًا لفظًا ومعنى؟","answer":"قرر الخبر ثبوت الحمد واستحقاق الله له قبل أن يحمده الخلق؛ فالجملة تثبت حقيقة دائمة، وتناسب مقام الاستدلال بآثار الخلق والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص204، تحت عنوان «بلاغة القول بخبرية الحمد لله لفظًا ومعنى»","url":""}]},{"id":"s6-2","number":2,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما الفرق بين التعبير بالخلق في ﴿خلق السماوات والأرض﴾، وبالجعل في ﴿وجعل الظلمات والنور﴾؟","answer":"الخلق أنسب بإيجاد الذوات، وفيه معنى التقدير والإبداع؛ فاقترن بالسماوات والأرض. أما الجعل فأنسب بإيجاد أعراض الذوات وأحوالها ونظامها، ويتضمن الإنشاء من شيء أو التصيير والتحويل؛ فناسب الظلمات والنور. وبهذا جاء كل فعل ملائمًا لما اقترن به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص207، تحت «سر التعبير بالخلق والجعل، واختصاص كل في الآية الكريمة»","url":""}]},{"id":"s6-3","number":3,"surah":6,"verses":[1,3],"references":[{"surah":6,"verses":[1,3]}],"verseLabel":"الأنعام: 1، 3","question":"ما سرّ جمع ﴿السماوات﴾ وإفراد ﴿الأرض﴾ في سورة الأنعام؟","answer":"جُمعت السماوات للدلالة على تعددها، وأُفردت الأرض لأن لفظها يجري مجرى اسم الجنس، ولأن جموعها أثقل في النظم. ومن الوجوه المذكورة أن إفرادها يشير إلى وحدتها بالنسبة إلى عالم السماوات؛ فالاختيار يراعي المعنى وفصاحة اللفظ والسياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص208–209، تحت «سر جمع السماوات وإفراد الأرض»","url":""}]},{"id":"s6-5","number":5,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما سرّ تقديم الظلمات على النور؟","answer":"قُدمت الظلمات لأن الظلمة عدم النور، والعدم متقدم على وجود المحدثات في التقدير والتحقق؛ ولأن الظلمات كثيرة والنور واحد. وفي الجانب المعنوي تسبق ظلمات الجهل والأهواء نور العلم والهداية المكتسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص212، تحت «سر تقديم لفظ الظلمات على لفظ النور في سياق الآية»","url":""}]},{"id":"s6-6","number":6,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم الذين كفروا بربهم يعدلون﴾ بعد دلائل الخلق؟","answer":"﴿ثم﴾ للتراخي الرتبي والتعجيب: بعد وضوح انفراد الله بخلق السماوات والأرض والظلمات والنور يبلغ التناقض غايته حين يجعل الكافر بربه عدلًا وشبيهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص213–214، تحت «دلالة ثم على جملة من المعاني في قوله: ﴿ثم الذين كفروا﴾»","url":""}]},{"id":"s6-7","number":7,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما دلالة تقديم ﴿بربهم﴾ في قوله تعالى: ﴿بربهم يعدلون﴾؟","answer":"قدم الجار والمجرور لإبراز موضع الجريمة والتعجيب منه: بربهم، الذي خلق وأنعم وربّاهم، يسوّون غيره! فالتقديم يركز الإنكار على المقابلة بين الرب المنعم والشريك المزعوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص214–215، تحت «دلالة تقديم المتعلق ﴿بربهم﴾ على ﴿يعدلون﴾»","url":""}]},{"id":"s6-8","number":8,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما دلالة اختيار فعل ﴿يعدلون﴾ للتعبير عن الشرك؟","answer":"العدل هنا جعل الشيء عدلًا ونظيرًا لغيره، فيصور المشركين يسوّون المخلوق بالخالق، ويتضمن أيضًا ميلهم وعدولهم عن الحق؛ فجمع اللفظ التسوية الجائرة والانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص216، تحت «إيثار التعبير بالفعل ﴿يعدلون﴾»","url":""}]},{"id":"s6-9","number":9,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما دلالة قوله تعالى: ﴿هو الذي خلقكم من طين﴾ مع أن أفراد البشر يُخلقون من نطفة؟","answer":"أُسند خلق المخاطبين من طين لأن ابتداء خلق النوع الإنساني كان من آدم أبي البشر الذي خُلق من طين؛ فذُكر الأصل الأول للنوع، مع أن الذرية بعده تُخلق من نطفة الذكر وبويضة الأنثى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص220–221، تحت «إعجاز مبين في قوله: ﴿خلقكم من طين﴾».","url":""}]},{"id":"s6-10","number":10,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما دلالة الظرف ﴿عنده﴾ في قوله تعالى: ﴿وأجل مسمى عنده﴾؟","answer":"يفيد اختصاص علم ذلك الأجل بالله؛ فهو مثبت مقدر في علمه، ولا يطلع على حقيقته ووقته أحد سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص224–225، تحت عنوان «دلالة التعبير بالظرف ﴿عنده﴾»","url":""}]},{"id":"s6-11","number":11,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما سر تنكير ﴿أجلًا﴾ وتخصيص الأجل الثاني بقوله: ﴿وأجل مسمى﴾؟","answer":"جاء الأول نكرة لأنه أجل الجنس المعروف بانتهاء الحياة، وخصص الثاني بوصف ﴿مسمى﴾ ليدل على أجل معين مقدر لا يتقدم ولا يتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص224، تحت عنوان «دلالة تنكير ﴿أجلًا﴾ وتخصيص ﴿وأجل مسمى﴾»","url":""}]},{"id":"s6-1037","number":1037,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما دلالة تقديم ﴿أجل مسمى﴾ على الظرف ﴿عنده﴾؟","answer":"قُدِّم الأجل المسمى للاهتمام به وتعظيم شأنه، ثم جاء ﴿عنده﴾ لبيان أن تعيينه والعلم بوقته مختصان بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص224–225، تحت عنوان «دلالة تقديم النكرة المخصصة ﴿وأجل مسمى﴾ على الظرف ﴿عنده﴾»","url":""}]},{"id":"s6-12","number":12,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما سرّ تقديم ﴿أجلًا﴾ على ﴿أجل مسمى عنده﴾؟","answer":"جاء الترتيب على ما يلقاه الإنسان: أجله القريب بالموت أولًا، ثم الأجل الجامع للبعث والجزاء؛ فانتقل من نهاية الفرد المشاهدة إلى النهاية الكبرى المغيبة عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص223–224، تحت «تقديم ﴿أجلًا﴾ على ﴿وأجل مسمى﴾»","url":""}]},{"id":"s6-13","number":13,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما المعاني التي أفادها العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم أنتم تمترون﴾؟","answer":"أفاد استبعاد امترائهم والتعجيب منه والتراخي الرتبي؛ إذ وقع الشك بعد قيام دلائل الخلق وتقدير الآجال، فكان أبعد عن مقتضى العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص225–226، تحت عنوان «إفادة ﴿ثم﴾ جملة من المعاني»","url":""}]},{"id":"s6-1038","number":1038,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما نكتة ذكر المسند إليه ﴿أنتم﴾ في قوله تعالى: ﴿ثم أنتم تمترون﴾؟","answer":"أبرز الضمير المخاطبين وواجههم بفعلهم لزيادة التوبيخ: أنتم أنفسكم تمترون بعد مشاهدة دليل الخلق وسماع خبر الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص226، تحت عنوان «نكتة ذكر المسند إليه ﴿أنتم﴾»","url":""}]},{"id":"s6-1039","number":1039,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما سر تقديم ﴿أنتم﴾ على المسند الفعلي ﴿تمترون﴾؟","answer":"جعل التقديم موضع العناية ذوات المخاطبين، فقوّى الإنكار والتعجيب من صدور الامتراء منهم خاصة بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص226–227، تحت عنوان «سر تقديم المسند إليه على المسند الفعلي»","url":""}]},{"id":"s6-14","number":14,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما الفرق بين ﴿تمترون﴾ و«تشكّون»؟","answer":"الامتراء في السياق يجمع الشك والمماراة والجدال؛ فهو تردد واضطراب يظهر في خصومة المشركين في قدرة الله على البعث بعد قيام دلائل الخلق، وليس مجرد ذكر شك عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص217–219، تحت «شرح المفردات: ﴿تمترون﴾»","url":""}]},{"id":"s6-15","number":15,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"كيف يُفهم قوله تعالى: ﴿وهو الله في السماوات وفي الأرض﴾ مع تنزهه سبحانه عن المكان؟","answer":"المعنى أنه المعبود المسمى الله في السماوات وفي الأرض، أو أن ألوهيته وعلمه وسلطانه نافذة فيهما؛ وليس المراد حلول ذاته في مكان، تعالى الله عن ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص232–233، تحت «دلالة الظرفية بالحرف «في» وتعلقها باسم الجلالة»","url":""}]},{"id":"s6-16","number":16,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة مجيء الاسم الظاهر ﴿الله﴾ بعد الضمير في قوله تعالى: ﴿وهو الله في السماوات وفي الأرض﴾؟","answer":"يتقدم الضمير فيتشوف السامع إلى ما يخبر به عنه، ثم يأتي اسم الجلالة ليقرر انفراده سبحانه بالألوهية؛ فهو المعروف بهذا الاسم، لا يلتبس بغيره ولا يشاركه أحد في صفات الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص232، تحت «سر تأخير الاسم الظاهر عن الضمير في ﴿وهو الله﴾»","url":""}]},{"id":"s6-17","number":17,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة إضافة السر والجهر إلى المخاطبين في قوله تعالى: ﴿يعلم سركم وجهركم﴾؟","answer":"الإضافة تحملهم مسؤولية ما يخفون وما يعلنون، وتخص الحجة بأحوالهم التي قد يظنون أن بعضها مستور؛ فعلمه محيط بسر كل واحد وجهره، لا بالمفهوم المجرد وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235، تحت «نكتة إضافة السر والجهر إلى ضمير المخاطبين»","url":""}]},{"id":"s6-18","number":18,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما سرّ تقديم السر على الجهر؟","answer":"قُدّم السر لأن المراد به صفات القلب الداعية إلى الفعل أو الصارفة عنه، وهي المؤثرة في أعمال الجوارح المسماة بالجهر؛ فكان تقديم العلة على معلولها أولى في البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235، تحت «سبب تقديم السر على الجهر في ﴿سركم وجهركم﴾»","url":""}]},{"id":"s6-19","number":19,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة عطف قوله تعالى: ﴿ويعلم ما تكسبون﴾ بعد علمه بسرهم وجهرهم؟","answer":"عُطف ﴿ويعلم ما تكسبون﴾ مع أن الكسب داخل في عموم السر والجهر لإظهار كمال الاعتناء به؛ لأنه مدار الجزاء، ولذلك أعيد فعل ﴿يعلم﴾، والكسب يشمل أعمال القلوب والجوارح سرًا وعلانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235–236، تحت «السر في تكرار ﴿يعلم﴾ وبلاغة التعبير بالفعل ﴿تكسبون﴾»","url":""}]},{"id":"s6-20","number":20,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما بلاغة التعبير عن الأعمال بالفعل ﴿تكسبون﴾؟","answer":"الكسب ما يتعمده الإنسان لجلب نفع أو دفع ضر، فعبّر به عن الأعمال والاعتقادات لإبراز تعلق الجزاء بما يختاره المرء ويسعى فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235–236، تحت عنوان «بلاغة التعبير بالفعل ﴿تكسبون﴾»","url":""}]},{"id":"s6-1040","number":1040,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ويعلم ما تكسبون﴾؟","answer":"جاءت موصولة عامة فشملت كل ما يكتسبه الإنسان من خير وشر، وظاهر وباطن، من غير أن يخرج شيء عن علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص236، تحت عنوان «دلالة ﴿ما﴾ في قوله تعالى: ﴿ويعلم ما تكسبون﴾»","url":""}]},{"id":"s6-21","number":21,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة تكرار ﴿من﴾ في قوله تعالى: ﴿وما تأتيهم من آية من آيات ربهم﴾؟","answer":"الأولى زائدة من جهة الصناعة النحوية، وفائدتها التوكيد واستغراق جنس الآيات في سياق النفي؛ أما الثانية فللتبعيض، أي: ما يظهر لهم دليل من جملة آيات ربهم إلا أعرضوا عنه، فتكرر الحرف لاختلاف وظيفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص239–240، تحت «دلالة حرف الجر «من» في قوله: ﴿من آية من آيات ربهم﴾»","url":""}]},{"id":"s6-22","number":22,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما الصورة في قوله تعالى: ﴿تأتيهم من آية﴾؟","answer":"شُبه بلوغ الآيات إليهم بمجيء الجائي، فحذف المشبه وصرح بالمشبه به في استعارة تصريحية تبعية؛ للمبالغة في ظهور الآيات وقوتها حتى صارت بمنزلة المحسوسات، ومع ذلك أعرضوا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص239، تحت «بلاغة الاستعارة في قول الله تعالى: ﴿وما تأتيهم﴾»","url":""}]},{"id":"s6-23","number":23,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما نكتة التعبير بالمضارع ﴿تأتيهم﴾ في قوله تعالى: ﴿وما تأتيهم من آية﴾؟","answer":"يستحضر المضارع تجدد مجيء الآيات وتتابعها، فيقابل كثرة الحجج بتجدد إعراضهم عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص240، تحت عنوان «نكتة التعبير بالفعل المضارع في قوله: ﴿تأتيهم﴾»","url":""}]},{"id":"s6-1041","number":1041,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة فعل الكون ﴿كانوا﴾ في قوله تعالى: ﴿كانوا عنها معرضين﴾؟","answer":"دل على أن الإعراض صار شأنًا ثابتًا متكررًا لهم كلما جاءتهم آية، لا موقفًا عارضًا وقع مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص242، تحت عنوان «دلالة التعبير بفعل الكون ﴿كانوا﴾»","url":""}]},{"id":"s6-1042","number":1042,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة التعبير بالاسم ﴿معرضين﴾؟","answer":"دل اسم الفاعل على ثبوت الإعراض ورسوخه فيهم، فناسب استمرار صدهم عن الآيات مع تجدد ورودها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص242–243، تحت عنوان «دلالة التعبير بالاسم في قوله: ﴿معرضين﴾»","url":""}]},{"id":"s6-24","number":24,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة تقديم ﴿عنها﴾ في قوله تعالى: ﴿إلا كانوا عنها معرضين﴾؟","answer":"قدم الجار والمجرور لإبراز أن إعراضهم واقع عن الآية نفسها مع كونها من آيات ربهم، ولتوجيه الذم إلى موقفهم منها قبل وصفهم الراسخ بالإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص241–242، تحت «سر تقديم الجار والمجرور على المسند» في قوله تعالى: ﴿إلا كانوا عنها معرضين﴾.","url":""}]},{"id":"s6-25","number":25,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة وصفهم بقوله تعالى: ﴿معرضين﴾ بالاسم دون: يعرضون؟","answer":"اسم الفاعل يثبت الإعراض صفة راسخة فيهم، لا فعلًا عابرًا يقع ثم يزول؛ ولذلك ناسب تكرر مجيء الآيات مع ثبات موقفهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص242–243، تحت «دلالة التعبير بالاسم في قوله: ﴿معرضين﴾»","url":""}]},{"id":"s6-26","number":26,"surah":6,"verses":[4,5],"references":[{"surah":6,"verses":[4,5]}],"verseLabel":"الأنعام: 4–5","question":"كيف يتصاعد وصف موقفهم من ﴿معرضين﴾ إلى ﴿كذبوا بالحق﴾ ثم ﴿يستهزئون﴾؟","answer":"رتب السياق أحوالهم من الأقل إلى الأشد: بدأ بالإعراض عن النظر في الدلائل، ثم ذكر تكذيبهم بها، ثم استهزاءهم؛ فالاستهزاء أغلظ من مجرد التكذيب، وباجتماع هذه المراتب يبلغ رفضهم للحق غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص247، تحت «الترقي وتصعيد المعاني»","url":""}]},{"id":"s6-27","number":27,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]}],"verseLabel":"الأنعام: 5","question":"ما دلالة تقييد التكذيب بقوله تعالى: ﴿لما جاءهم﴾؟","answer":"يبين أنهم بادروا إلى التكذيب وقت مجيء الحق من غير نظر ولا مهلة تدبر؛ فالجملة تشدد لومهم لأن ردهم لم ينشأ من غياب الحجة بل وقع عند حضورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص248، تحت «نكتة تعليق التكذيب على مطلق مجيء الحق».","url":""}]},{"id":"s6-28","number":28,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]}],"verseLabel":"الأنعام: 5","question":"ما دلالة تسمية ما سيأتيهم ﴿أنباء ما كانوا به يستهزئون﴾؟","answer":"الأنباء هنا ليست مجرد أخبار، بل ما سيأتيهم من العذاب الذي أنبأ الله به، أو تحقق مضمون الخبر ومصداق ما استهزؤوا به؛ واختيار لفظ النبأ يهول شأن الوعيد لأنه خبر خطير عظيم الوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص248–249، تحت «سر التعبير بلفظ ﴿أنباء﴾ في مقام الوعيد»","url":""}]},{"id":"s6-29","number":29,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]}],"verseLabel":"الأنعام: 5","question":"ما دلالة ﴿سوف﴾ في قوله تعالى: ﴿فسوف يأتيهم أنباء ما كانوا به يستهزئون﴾؟","answer":"ينقل حرف التسويف الوعيد إلى المستقبل مع تأكيد حصوله: فما أخبر الله به من جزاء استهزائهم سيصيبهم. فعدم وقوع العقاب في الحال لا يعني سقوط الوعيد أو النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص248، تحت «وجه دخول حرف التسويف ﴿فسوف﴾ في الجزاء»","url":""}]},{"id":"s6-30","number":30,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]},{"surah":15,"verses":[11]}],"verseLabel":"الأنعام: 5؛ الحجر: 11","question":"ما دلالة تقديم ﴿به﴾ في قوله تعالى: ﴿ما كانوا به يستهزئون﴾ في سورة الأنعام؟","answer":"قدم الجار والمجرور للاهتمام بالحق الذي اتخذوه موضع استهزاء، وفي التقديم زيادة تهديد؛ إذ يبرز التباين بين سخريتهم منه وبين ما سيحيق بهم بسببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص249–250، تحت عنوان «فائدة تقديم الجار والمجرور في قوله: ﴿به يستهزئون﴾»","url":""}]},{"id":"s6-31","number":31,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"لماذا فُصل قوله تعالى: ﴿ألم يروا كم أهلكنا من قبلهم من قرن﴾ عما قبله؟","answer":"جاء استئنافًا يبين صدق الوعيد السابق بدليل تاريخي معلوم؛ فإهلاك القرون الماضية شاهد مستقل على أن ما وُعدوا به واقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص255، تحت عنوان «علة فصل قول الله تعالى: ﴿ألم يروا كم أهلكنا﴾ عما قبله»","url":""}]},{"id":"s6-1043","number":1043,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ألم يروا كم أهلكنا من قبلهم من قرن﴾؟","answer":"هو استفهام إنكاري توبيخي؛ ينكر عليهم ترك الاعتبار بما علموه من مصارع الأمم، وينبههم إلى أن آثار الهلاك بمنزلة المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص255، تحت عنوان «دلالة الاستفهام الإنكاري التوبيخي»","url":""}]},{"id":"s6-32","number":32,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة تسمية الأمم الماضية ﴿قرنًا﴾؟","answer":"القرن جماعة من الناس اقترنت في زمن واحد أو تعاقبت فيه، فالتعبير يصور كل أمة وحدة تاريخية لها تمكينها ثم تنقضي ويأتي بعدها غيرها؛ وهو أنسب بسياق تعاقب الهلاك والإنشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–253، تحت «شرح المفردات: ﴿قرن﴾»","url":""}]},{"id":"s6-33","number":33,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما الفرق بين قوله تعالى: ﴿مكناهم في الأرض﴾ وقوله: ﴿ما لم نمكن لكم﴾؟","answer":"عُدّي الأول بنفسه لإبراز قوة تمكين الأمم السابقة ورسوخه، وجاء الثاني باللام لبيان ما جعل للمخاطبين من أسباب الانتفاع؛ والمقابلة تهددهم بأن من هلك كان أشد تمكينًا منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص258–259، تحت عنوان «الفرق بين (مكّنه) و(مكّن له)، وأثر ذلك في السياق»","url":""}]},{"id":"s6-34","number":34,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة تقديم السماء في قوله تعالى: ﴿وأرسلنا السماء عليهم مدرارًا﴾؟","answer":"قُدّم إرسال السماء على جعل الأنهار تجري لأن تتابع المطر سبب لجريانها، وفيه اتساع الرزق وخصب الأرض؛ فالجملة الأولى سبب للثانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263، تحت «بلاغة تقديم إرسال السماء على جعل الأنهار تجري»","url":""}]},{"id":"s6-35","number":35,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة قوله تعالى: ﴿وأرسلنا السماء﴾ مع أن المنزل هو المطر؟","answer":"أطلق المحل وأريد ما ينزل منه، أي المطر، حتى صارت السماء نفسها كأنها مرسلة عليهم بكثرة مائها؛ وفي ذلك مبالغة في وفرة النعمة واتصالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص260–261، تحت «بلاغة المجاز المرسل في قوله: ﴿وأرسلنا السماء﴾»","url":""}]},{"id":"s6-36","number":36,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة وصف السماء بقوله تعالى: ﴿مدرارًا﴾؟","answer":"﴿مدرارًا﴾ صيغة مبالغة من الدر، تدل على مطر كثير متتابع غزير لا دفعة عابرة؛ فتلائم تعداد قوة تمكين تلك الأمم وسعة رزقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص261، تحت «وجه صيغة المبالغة على زنة «مفعال» في قوله: ﴿مدرارًا﴾»","url":""}]},{"id":"s6-37","number":37,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿وجعلنا الأنهار تجري من تحتهم﴾؟","answer":"تفيد ابتداء جريان الأنهار من تحتهم، فتصف قرب منابعها. وهذا أبلغ في بيان النعمة من مجرد مرور ماء يأتي من مكان بعيد؛ إذ يدل على سهولة وصولهم إلى مطلعها وانتفاعهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263، تحت «دلالة دخول ﴿من﴾ على الظرف ﴿تحتهم﴾»","url":""}]},{"id":"s6-38","number":38,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة عطف الإهلاك على جريان الأنهار في قوله تعالى: ﴿تجري من تحتهم الأنهار فأهلكناهم﴾؟","answer":"أفادت الفاء حصول الإهلاك عقب التمكين والإنعام، مع تقدير ما دل عليه السياق: فكفروا وعصوا؛ فظهر أن سبب الهلاك ذنوبهم لا النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263، تحت عنوان «دلالة عطف الإهلاك على جعل الأنهار تجري»","url":""}]},{"id":"s6-1044","number":1044,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما سر التعبير عن الكفر بالذنوب في قوله تعالى: ﴿فأهلكناهم بذنوبهم﴾؟","answer":"أدخل كفرهم وتكذيبهم في جنس الذنوب ليقرر أن الجناية هي سبب الهلاك، وليحذر من الذنوب كلها لأنها طريق العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263–264، تحت عنوان «سر التعبير عن الكفر بالذنب في ﴿فأهلكناهم بذنوبهم﴾»","url":""}]},{"id":"s6-39","number":39,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما الذي تضيفه كلمة ﴿آخرين﴾ في قوله تعالى: ﴿وأنشأنا من بعدهم قرنًا آخرين﴾؟","answer":"تؤكد أن الذين أنشأهم الله بعد المهلكين جماعة أخرى غيرهم؛ فلا يلتبس القرن الجديد بالقرن السابق، وفي ذلك بيان قدرته على إهلاك قوم وإقامة غيرهم مقامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص265، تحت «نكتة وصف ﴿قرنًا﴾ بـ﴿آخرين﴾»","url":""}]},{"id":"s6-40","number":40,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة تقييد الكتاب بقوله تعالى: ﴿في قرطاس﴾؟","answer":"ذُكر القرطاس ليبلغ الدليل غاية الحس: كتاب في صحيفة ثابتة مكتوبة يرونه عيانًا ويلمسونه بأيديهم؛ ومع ذلك يخبر الله أنهم لا يؤمنون به، بل يصفونه بالسحر والتمويه والخيال، فينكشف أن المانع عنادهم لا خفاء الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص268–269، تحت عنوان «شرح المفردات: ﴿قرطاس﴾»","url":""}]},{"id":"s6-41","number":41,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة التصريح بالأيدي في قوله تعالى: ﴿فلمسوه بأيديهم﴾ مع أن اللمس يكون بها غالبًا؟","answer":"ذكر الأيدي توكيدًا للمباشرة الحسية وقطعًا لاحتمال أن يكون المراد نظرًا متخيلًا أو لمسًا مجازيًا؛ فقد جمع الفرض رؤية القرطاس ولمسه بأداة اللمس نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص272–273، تحت «فائدة ذكر الأيدي بعد اللمس»","url":""}]},{"id":"s6-42","number":42,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة افتراض لمس الكتاب وعدم الاكتفاء بمشاهدته؟","answer":"لأنهم قد يزعمون أن المرئي تخييل أو سحر للأبصار، فبلغ بهم البرهان إلى مباشرة القرطاس باليد؛ ليقرر أن عنادهم سيبقى ولو اجتمعت حاستا البصر واللمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص272، تحت «دلالة التعبير باللمس دون المعاينة»","url":""}]},{"id":"s6-43","number":43,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة القصر في قولهم: ﴿إن هذا إلا سحر مبين﴾؟","answer":"حصروا الكتاب المحسوس في السحر توكيدًا لحكمهم الباطل، ففضح الأسلوب غاية عنادهم؛ إذ جعلوا الدليل المشاهد عين السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص273، تحت عنوان «دلالة القصر في قول الله تعالى: ﴿إن هذا إلا سحر مبين﴾»","url":""}]},{"id":"s6-1045","number":1045,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة وصف السحر بكونه ﴿مبينًا﴾؟","answer":"زعموا أنه ظاهر واضح في السحر، فبلغت مكابرتهم أن قلبوا وضوح الآية إلى وضوح في تهمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص273–274، تحت عنوان «دلالة وصف السحر بكونه مبينًا في الآية الكريمة»","url":""}]},{"id":"s6-44","number":44,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما دلالة تقديم ﴿عليه﴾ في قولهم: ﴿لولا أنزل عليه ملك﴾؟","answer":"قدموا ﴿عليه﴾ لإفادة الاختصاص؛ فهم يطلبون أن ينزل الملك على الرسول ﷺ خاصة ليشهد له بالرسالة. ويتوجه اقتراحهم إلى نزول الملك عليه الذي لم يشاهدوه، مع أن الغرض منه محاولة تعجيزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص277، تحت «بلاغة تقديم المتعلق على نائب الفاعل»","url":""}]},{"id":"s6-45","number":45,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما وجه مجاز الحذف في قوله تعالى: ﴿ولو أنزلنا ملكًا لقضي الأمر﴾؟","answer":"حذف ما دل عليه السياق، أي: ولو أنزلنا ملكًا فكذبوا به لقضي أمر إهلاكهم؛ فالإيجاز يسرع إلى النتيجة المخيفة لمقترحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص278، تحت عنوان «وجه مجاز الحذف في قوله تعالى: ﴿ولو أنزلنا ملكًا لقضي الأمر﴾»","url":""}]},{"id":"s6-1046","number":1046,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما فائدة ﴿ثم﴾ في قوله تعالى: ﴿ثم لا ينظرون﴾؟","answer":"تفيد التراخي الرتبي؛ فعدم الإمهال بعد قضاء الأمر نتيجة شديدة، وتقرر أنهم إذا عاينوا الملك ثم كذبوا لم يؤخر عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص278–279، تحت عنوان «فائدة التعبير بـ«ثم» في قوله: ﴿ثم لا ينظرون﴾»","url":""}]},{"id":"s6-46","number":46,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما دلالة حذف الأمر المقضي في قوله تعالى: ﴿لقضي الأمر﴾؟","answer":"الحذف هنا في تفصيل ما يترتب على إنزال الملك: فإما أن يصدقوا فينجوا، وإما أن يكذبوا فيقضى عليهم بعذابهم وهلاكهم؛ و﴿الأمر﴾ هو أمر عذابهم، حُذف مضافه إليه وعُوّضت عنه اللام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص278–279، تحت «وجه مجاز الحذف في قوله تعالى: ﴿ولو أنزلنا ملكًا لقضي الأمر﴾».","url":""}]},{"id":"s6-47","number":47,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم لا ينظرون﴾ دون الفاء؟","answer":"تفيد ﴿ثم﴾ الترتيب مع التراخي الرتبي: فنفي الإمهال أشد من قضاء أمر العذاب؛ لأن مفاجأة الشدة وعدم منحهم مهلة أشد وقعًا من نفس وقوع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص279، تحت «فائدة التعبير بـ«ثم» في قوله: ﴿ثم لا ينظرون﴾»","url":""}]},{"id":"s6-48","number":48,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"كيف يُفهم قوله تعالى: ﴿ولو جعلناه ملكًا لجعلناه رجلًا﴾؟","answer":"لا يطيق البشر عادة رؤية الملك على صورته، فلو كان الرسول ملكًا لجعله الله في صورة رجل ليتمكنوا من رؤيته والتلقي عنه؛ وعندئذ يعود الاشتباه نفسه الذي اتخذوه حجة على الرسول البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص282–283، تحت عنوان «نكتة تفصيل الحكمة في جعل المرسل بالوحي رجلًا لا ملكًا»","url":""}]},{"id":"s6-49","number":49,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما دلالة تكرار ﴿جعلناه﴾ في قوله تعالى: ﴿ولو جعلناه ملكًا لجعلناه رجلًا﴾؟","answer":"تعلق الجعل الأول باختيار جنس الرسول المفترض، أي ملكًا، وتعلق الثاني بالصورة التي لا بد أن يظهر بها للناس، أي رجلًا؛ فكل فعل ينشئ مرحلة مختلفة من الفرض والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص284، تحت «سر ترتيب الضميرين وتكرير ﴿جعلناه﴾ في سياق الآية الكريمة»","url":""}]},{"id":"s6-50","number":50,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما التشبيه الضمني في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾؟","answer":"شُبّه ما ينشأ عن تمثل الملك رجلًا من التباس بما يصنعونه هم من خلط الحق بالباطل؛ فدل التركيب على أن مقترحهم يعيد العلة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص284–285، تحت عنوان «بلاغة التعبير بالتشبيه الضمني في قوله تعالى: ﴿وللبسنا عليهم﴾»","url":""}]},{"id":"s6-1047","number":1047,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما بلاغة الاحتباك في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾؟","answer":"ذُكر في الأول من يقع عليه اللبس، وحذف متعلقه، وذُكر في الثاني ما يلبسونه وحذف من يلبسون عليه؛ فدل كل طرف على محذوف الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص285–286، تحت عنوان «بلاغة الاحتباك في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾»","url":""}]},{"id":"s6-51","number":51,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾؟","answer":"تحتمل المصدرية، أي: مثل لبسهم، وتحتمل الموصولية، أي: الأمر الذي يلبسونه؛ فتتسع لما يخلطونه من الحق وبما يوقعونه من التباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص286–287، تحت عنوان «معنى ﴿ما﴾ في قوله: ﴿ما يلبسون﴾»","url":""}]},{"id":"s6-52","number":52,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة البناء للمجهول في قوله تعالى: ﴿ولقد استهزئ برسل من قبلك﴾؟","answer":"وجه البناء العناية إلى وقوع الاستهزاء بالرسل بوصفه سنة متكررة، لا إلى أسماء المستهزئين؛ وفيه تسلية للنبي ﷺ بأن ما لقيه قد لقيه رسل قبله ثم كانت العاقبة للمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص291–292، تحت «سر بناء الفعل للمفعول في قوله تعالى: ﴿استهزئ﴾»","url":""}]},{"id":"s6-53","number":53,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة تنكير ﴿رسل﴾ في قوله تعالى: ﴿برسل من قبلك﴾؟","answer":"يفيد تنكير ﴿رسل﴾ أن كثيرًا من الرسل من قبلك قد استهزأت بهم أقوامهم، فيتسع بذلك معنى التسلية ويظهر أن الاستهزاء سنة متكررة؛ ولم يُعرّف اللفظ لأن بعض الرسل لم يتعرض لهذا الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص292، تحت «بلاغة التنكير في قوله تعالى: ﴿برسل﴾»","url":""}]},{"id":"s6-54","number":54,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما الفرق الدلالي بين ﴿حاق﴾ و﴿أحاط﴾ في تصوير الجزاء؟","answer":"الحَيْق نزول المكروه بصاحبه ولزومه إياه، أما الإحاطة فأعم في تطويق الشيء من جوانبه؛ فاختيار ﴿حاق﴾ يصور حلول العذاب بالساخرين والتصاقه بهم جزاء استهزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص296–297، تحت عنوان ««حاق» و«أحاط»»","url":""}]},{"id":"s6-55","number":55,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة التنويع بين ﴿استهزئ﴾ و﴿سخروا﴾ و﴿يستهزئون﴾؟","answer":"الاستـهزاء أخف ويكون أولًا، ثم تأتي السخرية مرحلةً أشد فيها مبالغة وتسخير للجهد؛ لذلك بدأ بـ﴿استهزئ﴾ ثم قال ﴿سخروا﴾، وعاد إلى ﴿يستهزئون﴾ لأنه أخف ولأن تركيب «يسخرون منه» أثقل في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص297–299، تحت «(سخروا) و(استهزؤوا)».","url":""}]},{"id":"s6-56","number":56,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة قوله تعالى: ﴿فحاق بالذين سخروا منهم ما كانوا به يستهزئون﴾، فكأن المستهزأ به هو الذي حاق بهم؟","answer":"أُسند الحيق إلى ما كانوا يستهزئون به لأن استهزاءهم بما أنذرت به الرسل هو السبب المؤدي إلى العقاب، فصُوّر السبب كأنه المعاقِب؛ ويصح أن يكون المراد أن العذاب الذي استهزؤوا به قد أحاط بهم حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص295، تحت «بلاغة المجاز العقلي في سياق الآية الكريمة»","url":""}]},{"id":"s6-57","number":57,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما المقصود بالسير في قوله تعالى: ﴿قل سيروا في الأرض﴾، وما صلته بالاعتبار؟","answer":"السير هو الانتقال من مكان إلى مكان، والمقصود أن ينتقلوا في الأرض، ولا سيما فيما قرب من ديار المهلكين، ليعاينوا آثارهم ويتخذوا منها العظة؛ فالأمر ليس انتقالًا مجردًا، بل سير اعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص300، تحت «معنى قوله تعالى: ﴿سيروا﴾ وقوله: ﴿انظروا﴾ في الآية الكريمة»","url":""}]},{"id":"s6-58","number":58,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم انظروا﴾ دون الفاء؟","answer":"تفيد ﴿ثم﴾ التباعد الرتبي: فالسير في ذاته مباح، أما النظر للتدبر والاعتبار فواجب، ورتبة التأمل والنظر أعلى من رتبة مجرد السير؛ لذلك لم يعطفه بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص303–304، تحت «التشابه اللفظي ووجه العطف بالحرف ﴿ثم﴾»","url":""}]},{"id":"s6-59","number":59,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما دلالة قوله تعالى: ﴿كيف كان عاقبة المكذبين﴾ دون: ماذا كانت عاقبتهم؟","answer":"﴿كيف﴾ تسأل عن هيئة النهاية وفظاعتها، لا عن اسمها أو مجرد وقوعها؛ فتدعو إلى تأمل صور الهلاك وآثاره وتفاصيله التي يشاهدها السائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص302–303، تحت «سر تعليق ﴿كيف﴾ بفعل النظر».","url":""}]},{"id":"s6-60","number":60,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما سرّ وصف الهالكين بـ﴿المكذبين﴾ بعد ذكر الاستهزاء؟","answer":"وصفهم بالمكذبين لأن التكذيب أعم: يجمع المستهزئين والساخرين ويشمل كل من كذب ولو لم يسخر أو يستهزئ؛ وفي السياق دلالة على أن كلًا من التكذيب والاستهزاء كاف في استحقاق تلك العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص305، تحت «التكذيب والاستهزاء»","url":""}]},{"id":"s6-61","number":61,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة أن يسأل النبي ﷺ: ﴿قل لمن ما في السماوات والأرض﴾ ثم يتولى الجواب: ﴿قل لله﴾؟","answer":"لأن الخصم لا يملك جوابًا صحيحًا إلا الإقرار بملك الله أو المكابرة بما تعرف الفطرة بطلانه، فتولى الوحي الجواب ليقرر الحجة سريعًا ولا يترك للمراوغة مجالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص309، تحت «سر المبادرة بالجواب عن السؤال دون انتظار جوابهم في ﴿قل لله﴾»","url":""}]},{"id":"s6-62","number":62,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة تقديم ﴿لله﴾ في جواب قوله تعالى: ﴿قل لله﴾؟","answer":"تقديم الجار والمجرور يفيد قصر ملك ما في السماوات والأرض على الله وحده، وهو المقصود من السؤال والحجة على بطلان ولاية غيره وعبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص308–309، تحت «إفادة الحصر في قوله تعالى: ﴿قل لله﴾»","url":""}]},{"id":"s6-63","number":63,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة الفعل ﴿كتب﴾ بين الحقيقة والمجاز في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"الكتابة استعارة للعهد المؤكد الثابت الذي تفضل الله به، فصورت الرحمة حكمًا محققًا من غير أن يوجب عليه ذلك مخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص309–310، تحت عنوان «دلائل الفعل ﴿كتب﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s6-1048","number":1048,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما وجه التعميم في ذكر الرحمة في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"أطلق الرحمة لتشمل أنواعها وآثارها في الدنيا والآخرة، فدل اللفظ العام على سعة فضل الله بخلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص310، تحت عنوان «وجه التعميم في ذكر الرحمة»","url":""}]},{"id":"s6-1049","number":1049,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما بلاغة اعتراض قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"جاءت الجملة معترضة لتطمئن السامع إلى سعة الرحمة بين تقرير الملك والوعيد بالجمع، فجمعت الترغيب بالترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص310–311، تحت عنوان «بلاغة الاعتراض بقوله تعالى: ﴿كتب على نفسه الرحمة﴾»","url":""}]},{"id":"s6-64","number":64,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما سر تقديم الجار والمجرور في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"قدم ﴿على نفسه﴾ للاهتمام بتفضله سبحانه بإلزام ذاته بالرحمة، ولبيان اختصاصه بهذا الوعد المؤكد من غير إيجاب أحد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص309–310، تحت عنوان «سر تقديم الجار والمجرور في الآية الكريمة»","url":""}]},{"id":"s6-65","number":65,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما مناسبة الانتقال من كتابة الرحمة إلى التهديد بالجمع يوم القيامة؟","answer":"بعد بيان أن رحمته تقتضي عدم تعجيل العقوبة وقبول الإنابة والتوبة، قابل ذلك بالجمع ليوم القيامة الذي يقتضي المحاسبة والعقاب؛ فجمعت الآية الوعد والوعيد، وقدمت الوعد بالرحمة قبل التهديد بالجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص311، تحت «بلاغة الاعتراض بقوله تعالى: ﴿كتب على نفسه الرحمة﴾»","url":""}]},{"id":"s6-66","number":66,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة اجتماع اللام والنون في قوله تعالى: ﴿ليجمعنكم﴾؟","answer":"اللام موطئة لقسم مقدر، ونون التوكيد الثقيلة تثبت وقوع الجمع تثبيتًا قويًا؛ فاجتمعتا لمواجهة إنكار البعث وإزالة كل ريب في مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص311–312، تحت «تحقيق الوعيد باللام والنون في قوله تعالى: ﴿ليجمعنكم﴾».","url":""}]},{"id":"s6-67","number":67,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة قوله تعالى: ﴿إلى يوم القيامة﴾ دون: في يوم القيامة؟","answer":"تحتمل ﴿إلى﴾ أن تكون بمعنى ﴿في﴾، أي: ليجمعنكم في يوم القيامة؛ وتحتمل بقاءها على انتهاء الغاية، أي يجمعكم في الدنيا بموتكم ويستمر هذا الجمع إلى يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص312، تحت «معنى ﴿إلى﴾ في قوله تعالى: ﴿إلى يوم القيامة﴾»","url":""}]},{"id":"s6-68","number":68,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما الاستعارة في قوله تعالى: ﴿الذين خسروا أنفسهم﴾؟","answer":"شُبه تفويتهم الإيمان وما يترتب عليه من النجاة بخسارة التاجر رأس ماله؛ بل خسروا ذواتهم كلها بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص313–314، تحت عنوان «دلالة الاستعارة في قوله تعالى: ﴿خسروا أنفسهم﴾»","url":""}]},{"id":"s6-1050","number":1050,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة التعبير عن الذات بالنفس في قوله تعالى: ﴿خسروا أنفسهم﴾؟","answer":"يقرر أن الخسارة أصابت أعز ما يملكون، وهي ذواتهم، لا مالًا أو منفعة خارجة عنهم؛ فاشتد الترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص314، تحت عنوان «وجه التعبير عن الذات بالنفس»","url":""}]},{"id":"s6-1051","number":1051,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما سر الفصاحة بذكر السبب بعد المسبب في قوله: ﴿الذين خسروا أنفسهم فهم لا يؤمنون﴾؟","answer":"قدّم خسران النفس لأنه النتيجة الأشد والأجدر بالتخويف، ثم ذكر عدم الإيمان سببًا له؛ فلفت أولًا إلى العاقبة ثم كشف منشأها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص314–315، تحت عنوان «سر الفصاحة بذكر السبب بعد المسبب»","url":""}]},{"id":"s6-69","number":69,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة قوله تعالى: ﴿وله ما سكن في الليل والنهار﴾ بعد تقرير ملك ما في السماوات والأرض؟","answer":"انتقل من استيعاب المكان إلى استيعاب الزمان؛ فما في السماوات والأرض ملكه أينما كان، وما حل في الليل والنهار ملكه في كل وقت، فتتكامل إحاطة الملك بالمكان والزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص320–321، تحت «بلاغة تقديم المكان على الزمان في السياق»","url":""}]},{"id":"s6-70","number":70,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة الفعل الماضي ﴿سكن﴾ وسر البدء به في قوله تعالى: ﴿وله ما سكن في الليل والنهار﴾؟","answer":"يفيد تحقق استقرار الموجودات في سلطان الله، وبدأ بالسكون لأنه أغلب أحوالها ولأنه أدل على خضوعها وقرارها في ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص319–320، تحت عنوان «دلالة الفعل الماضي ﴿سكن﴾ وسر البدء به»","url":""}]},{"id":"s6-1052","number":1052,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما بلاغة الاكتفاء بـ﴿سكن﴾ وحذف المقدر؟","answer":"اكتفى بذكر الساكن لأن المتحرك مفهوم بالمقابلة وبطريق الأولى، أو لأن السكون بمعنى الحلول والاستقرار فيشمل ما يحتويه الليل والنهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص321، تحت عنوان «بلاغة الاكتفاء بـ﴿سكن﴾ وحذف المقدر في الآية»","url":""}]},{"id":"s6-71","number":71,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"كيف يدل الجمع بين ﴿الليل والنهار﴾ على شمول ملك الله لكل وقت؟","answer":"يشمل الليل والنهار جميع الأوقات، فكل كائن يوجد أو يسكن في وقت من أوقاتهما؛ وبالجمع بينهما يقرر التعبير إحاطة ملك الله بالمخلوقات على اختلاف أزمنتها وأحوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص321، تحت «دلالة الطباق في لفظي ﴿الليل والنهار﴾»","url":""}]},{"id":"s6-72","number":72,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة تقديم ﴿له﴾ في قوله تعالى: ﴿وله ما سكن﴾؟","answer":"يفيد التقديم اختصاص الملك الحقيقي بالله لكل ما يحتويه الليل والنهار؛ فلا يخرج موجود في أي وقت عن سلطانه، وهو استمرار لقصر الملك في الآية السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص319، تحت «وجه تقديم الجار والمجرور على المسند إليه».","url":""}]},{"id":"s6-73","number":73,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما بلاغة ختم قوله تعالى: ﴿وله ما سكن في الليل والنهار﴾ بقوله: ﴿وهو السميع العليم﴾؟","answer":"ربطت الخاتمة ملكه للموجودات بإحاطته بها؛ فهو يسمع أقوالها ويعلم ظاهرها وخفيها، وفي ذلك وعيد لمن يخالفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص322، تحت عنوان «بلاغة ختم الآية بما يناسب الوعيد والتهديد»","url":""}]},{"id":"s6-1053","number":1053,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة وجهي السمع في وصف الله تعالى بـ﴿السميع﴾؟","answer":"يدل على إحاطة الله بكل مسموع، كما يدل على إجابة من دعاه؛ فاجتمع كمال العلم بأصوات الخلق وكمال القرب ممن يسأله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص322–323، تحت عنوان «دلالة وجهي السمع في الآية الكريمة»","url":""}]},{"id":"s6-1054","number":1054,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما وجه المبالغة في صفتي ﴿السميع العليم﴾؟","answer":"جاء الوصفان على صيغتي مبالغة للدلالة على كمال الإحاطة بالمسموعات والمعلومات، فلا يخفى عليه صوت ولا حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص323، تحت عنوان «وجه المبالغة في صفتي ﴿السميع العليم﴾»","url":""}]},{"id":"s6-74","number":74,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما سرّ تقديم ﴿السميع﴾ على ﴿العليم﴾؟","answer":"قُدّم ﴿السميع﴾ لمناسبة ذكر الليل أولًا، فالسمع حاسة تعمل في الظلام؛ ثم جاء ﴿العليم﴾ لمناسبة ذكر النهار، إذ يكون فيه نشاط المخلوقات وحركتها واكتساب العلم والخبرة، فحُفظ ترتيب ألفاظ الآية في خاتمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص322، تحت «بلاغة اللف والنشر في الآية الكريمة»","url":""}]},{"id":"s6-75","number":75,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة تقديم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله أتخذ وليًا﴾؟","answer":"قدم المفعول لأن إنكار اتخاذ غير الله هو محور السؤال، ويفيد السياق القصر: لا أتخذ وليًا مستحقًا للعبادة والنصرة من دون الله؛ فالمرفوض ذات البديل قبل فعل الاتخاذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص326–327، تحت «بلاغة التقديم في قوله تعالى: ﴿أغير الله أتخذ وليًا﴾»","url":""}]},{"id":"s6-76","number":76,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة وصف الله بأنه ﴿فاطر السماوات والأرض﴾ دون: خالق السماوات والأرض؟","answer":"الفاطر هو المبتدئ للخلق؛ فالوصف يذكر بأنه سبحانه أصل وجود السماوات والأرض. وناسب ذلك إنكار اتخاذ ولي غيره: فالذي أوجد الخلق ويدبر أمرهم هو المستحق للولاية والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص324–325، تحت عنوان «شرح المفردات: ﴿فاطر﴾»","url":""}]},{"id":"s6-77","number":77,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما المجاز في قوله تعالى: ﴿وهو يطعم ولا يطعم﴾؟","answer":"جعل الإطعام كناية عن الإنعام والرزق والتدبير؛ فمن يرزق الخلق ويقوم بأمرهم هو المستحق للولاية والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص326–327، تحت عنوان «بلاغة المجاز في قوله تعالى: ﴿وهو يطعم ولا يطعم﴾»","url":""}]},{"id":"s6-1055","number":1055,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما وجه التعريض في قوله تعالى: ﴿وهو يطعم ولا يطعم﴾؟","answer":"فيه تعريض بعجز آلهتهم وافتقارها؛ فالله يرزق ولا يحتاج، وما سواه محتاج لا يملك لنفسه ولا لغيره رزقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص327، تحت عنوان «وجه التعريض»","url":""}]},{"id":"s6-1056","number":1056,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما بلاغة طباق السلب في قوله تعالى: ﴿يطعم ولا يطعم﴾؟","answer":"قابل بين إثبات الإطعام لله ونفي أن يطعمه غيره، فبرز كمال غناه مع تمام إنعامه على خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص327–328، تحت عنوان «بلاغة طباق السلب»","url":""}]},{"id":"s6-1057","number":1057,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما سر بناء الفعل للمفعول في قوله تعالى: ﴿ولا يطعم﴾؟","answer":"حذف الفاعل لأن المقصود نفي الحاجة عن الله من أي جهة كانت؛ فلا يطعمه أحد ولا يفتقر إلى مطعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص328–329، تحت عنوان «سر بناء الفعل للمفعول في قوله: ﴿ولا يطعم﴾»","url":""}]},{"id":"s6-78","number":78,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة تكرار الأمر ﴿قل﴾ في الآية؟","answer":"جدد ﴿قل﴾ كل إعلان مستقل: إنكار اتخاذ ولي غير الله، ثم التصريح بأمره أن يكون أول من أسلم والتحذير من الشرك؛ فتكراره يفصل مقامات الحجة ويؤكد أن كل جواب وحي مأمور بإبلاغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص329، تحت «بلاغة إعادة الأمر ﴿قل﴾ في الآية الكريمة»","url":""}]},{"id":"s6-79","number":79,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"كيف يُفهم قوله تعالى: ﴿أمرت أن أكون أول من أسلم﴾ مع سبق الأنبياء والمؤمنين؟","answer":"أي أول من أسلم من هذه الأمة ومن المخاطبين برسالته، أو أولهم مبادرةً وامتثالًا فيما كُلّف بتبليغه؛ فلا ينفي إسلام الأنبياء وأتباعهم في الأمم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص329–330، تحت «بلاغة التعبير بالأولية في قوله تعالى: ﴿أول من أسلم﴾»","url":""}]},{"id":"s6-80","number":80,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة الانتقال من قوله تعالى: ﴿إني أمرت﴾ إلى الخطاب المباشر: ﴿ولا تكونن من المشركين﴾؟","answer":"حكى أولًا الأمر الذي تلقاه بالإسلام، ثم جاء النهي موجهًا إليه مباشرةً ليشتد وقعه ويبلغ الأمة من ورائه؛ فالانتقال من الخبر عن التكليف إلى خطاب التحذير يجعل البراءة من الشرك حاضرة مؤكدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص330–331، تحت «بلاغة الالتفات من المتكلم إلى المخاطب في الآية الكريمة»","url":""}]},{"id":"s6-81","number":81,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة قوله تعالى: ﴿من المشركين﴾ دون: مشركًا؟","answer":"النهي عن أن يكون منتميًا إلى جماعة المشركين أو مجتمعهم، لا عن مجرد اتصافه بالشرك؛ وهو أبلغ لأن طرق الشرك كثيرة، ومن عاشر أهلها خيف عليه الوقوع فيها، أما سبيل الإيمان فواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص332–333، تحت عنوان «دلالة معنى ﴿من﴾ في قوله تعالى: ﴿من المشركين﴾»","url":""}]},{"id":"s6-82","number":82,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما دلالة قول النبي ﷺ: ﴿إني أخاف إن عصيت ربي عذاب يوم عظيم﴾ مع عصمته؟","answer":"الشرط فرض للتعليم والتعريض بالمشركين؛ فإذا كان الرسول ﷺ، مع عصمته واستحالة المعصية منه، يعلن خوفه على سبيل الفرض، فغيره أولى بالخوف. وفيه أن لا محاباة لأحد مهما عظم، وأن الحكم منوط بالأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص335–336، تحت عنوان «بلاغة التعبير بـ﴿إن﴾ الشرطية دون «إذا»»","url":""}]},{"id":"s6-83","number":83,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما دلالة الماضي في قوله تعالى: ﴿إن عصيت﴾ مع أن الشرط مفترض؟","answer":"يأتي الماضي بعد أداة الشرط لتصوير الفعل المفروض كأنه تحقق واستحضر أثره، وللدلالة على جدية الملازمة بين العصيان والعذاب؛ فلا يعني أن المعصية وقعت من النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336، تحت «فائدة صيغة الماضي في قوله تعالى: ﴿عصيت﴾»","url":""}]},{"id":"s6-84","number":84,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما دلالة قوله تعالى: ﴿عصيت ربي﴾ دون: عصيت الله؟","answer":"عُدل عن اسم الجلالة إلى ﴿ربي﴾ للإيماء إلى قبح العصيان؛ فكيف يُعصى الرب؟ وفي لفظ ﴿ربي﴾ كناية عن الولاء لله والاستسلام إليه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336، تحت «وجه الكناية في العدول عن اسم الجلالة إلى ﴿ربي﴾»","url":""}]},{"id":"s6-85","number":85,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما بلاغة الإطناب والإيغال في لفظ ﴿يوم﴾ في قوله: ﴿عذاب يوم عظيم﴾؟","answer":"زاد ذكر اليوم تهويلًا؛ لأنه يستحضر ظرفًا جامعًا لأهوال البعث والحساب والجزاء، فلا يقف التصوير عند ألم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336، تحت عنوان «بلاغة الإطناب والإيغال في لفظ ﴿يوم﴾»","url":""}]},{"id":"s6-1058","number":1058,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما الوجه البلاغي في وصف العذاب بالعظمة في قوله تعالى: ﴿عذاب يوم عظيم﴾؟","answer":"عظم العذاب بعظمة اليوم الذي يقع فيه وما يضم من أهوال متعددة، فانتقل الذهن من عقوبة جزئية إلى مشهد القيامة كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336–337، تحت عنوان «الوجه البلاغي في وصف ﴿عذاب﴾ بأنه ﴿عظيم﴾»","url":""}]},{"id":"s6-86","number":86,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما دلالة البناء للمجهول في قوله تعالى: ﴿من يصرف عنه يومئذ فقد رحمه﴾؟","answer":"بُني ﴿يُصرف﴾ للمفعول لأن الصارف معلوم، وهو الله تعالى، فحُذف للعلم به والإيجاز، وقد تقدم ذكر ﴿الرب﴾ فدل عليه؛ وفي قراءة أخرى جاء الفعل مبنيًا للفاعل: ﴿يصرف﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص340، تحت «بلاغة الإيجاز في قوله تعالى: ﴿من يصرف عنه﴾»","url":""}]},{"id":"s6-87","number":87,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"لم أعيد ذكر اليوم في ﴿من يصرف عنه يومئذ﴾ بعد قوله: ﴿عذاب يوم عظيم﴾؟","answer":"أعيد ذكره لتأكيد عظم شأنه وتحقيق وقوعه؛ فهو يوم ليس كسائر الأيام، بل توزن فيه أعمال الدنيا كلها. لذلك كان صرف العذاب فيه هو الرحمة والفوز العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص340–341، تحت «وجه الإطناب في تكرير ذكر اليوم في قوله تعالى: ﴿يومئذ﴾»","url":""}]},{"id":"s6-88","number":88,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما دلالة التعبير عن النجاة من العذاب بقوله تعالى: ﴿فقد رحمه﴾ دون: فقد نجا؟","answer":"عُبر عن صرف العذاب بالرحمة لأن الرحمة هي النجاة والفلاح، ولأن دفع عذاب القيامة يعقبه دخول الجنان؛ فصرف العذاب نفسه دخول في رحمة الله الشاملة، واتحاد معنى الشرط والجزاء يعظم شأن هذه الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص341، تحت عنوان «حسن اختيار الفعل مع الضمير في ﴿رحمه﴾»","url":""}]},{"id":"s6-89","number":89,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما بلاغة اسم الإشارة في قوله تعالى: ﴿وذلك الفوز المبين﴾؟","answer":"أشير بالبعيد إلى صرف العذاب والرحمة لتعظيم منزلتهما ورفع قدر هذا الفوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص342، تحت عنوان «بلاغة التعبير باسم الإشارة ﴿وذلك﴾»","url":""}]},{"id":"s6-1059","number":1059,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما وجه التعريف في قوله تعالى: ﴿الفوز المبين﴾؟","answer":"عرّف الفوز لأنه الفوز الكامل المعهود الذي لا يدانيه غيره: النجاة من العذاب ودخول الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص342–343، تحت عنوان «وجه التعريف في ﴿الفوز المبين﴾»","url":""}]},{"id":"s6-1060","number":1060,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما سر تذييل الآية بقوله تعالى: ﴿وذلك الفوز المبين﴾؟","answer":"لخصت الجملة نتيجة صرف العذاب، وقررت أن النجاة يوم القيامة هي الفوز الواضح الكامل الذي يستلزم الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص343، تحت عنوان «سر التذييل في قوله تعالى: ﴿وذلك الفوز المبين﴾»","url":""}]},{"id":"s6-90","number":90,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة اختيار المس في قوله تعالى: ﴿وإن يمسسك الله بضر﴾؟","answer":"استُعير المس للإصابة بالضر، وفيه تصوير لقرب أثره من الإنسان ولو كان قليلًا؛ فالمس أخف من الإصابة الشديدة. والمعنى أن أدنى ما يصيب الإنسان من ضر لا يملك كشفه إلا الله، فكيف بما هو أشد؟","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص346–347، تحت عنوان «دلالة الاستعارتين التبعيتين في قوله تعالى: ﴿وإن يمسسك الله بضر﴾»","url":""}]},{"id":"s6-91","number":91,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة مقابلة ﴿بضر﴾ بقوله تعالى: ﴿بخير﴾ دون: بنفع؟","answer":"الضر ضد النفع، لكن النظم قابل ﴿الضر﴾ بـ﴿الخير﴾ لأن الخير أعم من النفع، كما أن الشر أعم من الضر؛ فشمل الخير الغنى والصحة وغيرهما، ودلت المقابلة على أن كل ما يصيب الإنسان من خير أو شر فمن عند الله","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص347–348، تحت «وجه الطباق بين الضر والخير»","url":""}]},{"id":"s6-92","number":92,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما بلاغة الحصر في قوله تعالى: ﴿فلا كاشف له إلا هو﴾؟","answer":"قصر كشف الضر على الله قصرًا حقيقيًا؛ فلا يملك أحد رفع ما أنزله، وفيه إبطال التعلق بغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص348، تحت عنوان «بلاغة الحصر في قوله تعالى: ﴿فلا كاشف له إلا هو﴾»","url":""}]},{"id":"s6-1061","number":1061,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما فائدة صيغة المبالغة ﴿قدير﴾ في قوله تعالى: ﴿فهو على كل شيء قدير﴾؟","answer":"دلت على كمال القدرة وعمومها، فشملت إيصال الخير وكشف الضر وسائر الممكنات من غير عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص349، تحت عنوان «فائدة التعبير بصيغة المبالغة في ﴿قدير﴾»","url":""}]},{"id":"s6-93","number":93,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة اختيار ﴿كاشف﴾ لإزالة الضر؟","answer":"الكشف هو رفع ما يواري الشيء ويغطيه، كرفع الغطاء عنه؛ فاستعمل مجازًا في إزالة الضر والغم، وصُوّر الضر كأنه غطاء لا يرفعه عن المصاب إلا الله","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص344، تحت «شرح المفردات: ﴿كاشف﴾»","url":""}]},{"id":"s6-94","number":94,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة الانتقال في جانب الخير إلى قوله تعالى: ﴿فهو على كل شيء قدير﴾؟","answer":"انتقل من ذكر إصابة الخير إلى عموم القدرة؛ فدل قوله ﴿فهو على كل شيء قدير﴾ على الجواب المحذوف: إن يمسسك بخير فلا مانع له، لأنه قدير على الضر والنفع جميعًا، ومهّد بذلك لقوله ﴿وهو القاهر فوق عباده﴾ إذ الأقدار كلها بيده","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص349، تحت «فائدة التعبير بصيغة المبالغة في ﴿قدير﴾»","url":""}]},{"id":"s6-95","number":95,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما دلالة تعريف ﴿القاهر﴾ في قوله تعالى: ﴿وهو القاهر فوق عباده﴾؟","answer":"يفيد تعريف طرفي الجملة القصر: لا قاهر على الحقيقة إلا الله؛ فلا يغلبه أحد ولا يعجزه شيء، وعباده داخلون تحت قدرته وتدبيره. فالوصف يقرر انفراده بالغلبة المطلقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص352–353، تحت «دلالة القصر في قوله تعالى: ﴿وهو القاهر فوق عباده﴾»","url":""}]},{"id":"s6-96","number":96,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"كيف يُفهم قوله تعالى: ﴿وهو القاهر فوق عباده﴾، وهل المراد فوقية مكان تحيط به؟","answer":"تصور ﴿فوق عباده﴾ قهر الله وغلبته تصويرًا تمثيليًا بحال من يأخذ المغلوب من أعلاه فلا يجد مهربًا؛ والفوقية هنا فوقية قدرة وغلبة، وتأتي كذلك للمنزلة والشرف، والله فوق كل شيء على الوجه اللائق به دون تشبيه بالمخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص353–354، تحت «بلاغة الاستعارة التمثيلية في قوله تعالى: ﴿وهو القاهر فوق عباده﴾».","url":""}]},{"id":"s6-97","number":97,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما دلالة قوله تعالى: ﴿فوق عباده﴾ دون: فوق خلقه؟","answer":"وصف العباد يبرز خضوعهم وافتقارهم وكونهم مملوكين له، فيناسب القهر والسيادة، كما يذكر المكلفين بأنهم عبيد لا يملكون الاستقلال عن حكم ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص354، تحت «علّة ذكر الخاص وإرادة العام في قوله تعالى: ﴿فوق عباده﴾».","url":""}]},{"id":"s6-98","number":98,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما دلالة تذييل ما سبق بقوله تعالى: ﴿وهو القاهر فوق عباده﴾؟","answer":"قرر التذييل أن تصرف الله في الضر والخير ناشئ عن قهر شامل وسلطان لا يخرج عنه أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص352، تحت عنوان «دلالة تذييل الآية ﴿وهو القاهر﴾ لما قبلها»","url":""}]},{"id":"s6-1062","number":1062,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما وجه ذكر العام بعد الخاص في الانتقال إلى قوله: ﴿وهو القاهر فوق عباده﴾؟","answer":"بعد ذكر قدرته على الضر والخير عُمم الحكم بقهره لعباده، فدخلت تلك الصور وغيرها في سلطان واحد شامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص352، تحت عنوان «وجه ذكر العام بعد الخاص»","url":""}]},{"id":"s6-99","number":99,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما مناسبة الجمع بين ﴿الحكيم﴾ و﴿الخبير﴾ بعد ذكر القهر؟","answer":"جاء ﴿الحكيم الخبير﴾ بعد القهر ليقترن كمال القدرة بكمال العلم؛ فالله يقهر عباده بقدرته وحكمته، وهو خبير بما يحتاج إليه خلقه وما يلائمهم، فيجري تدبيره على الحكمة البالغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص354–355، تحت «بلاغة اقتران الاسمين الكريمين: ﴿الحكيم الخبير﴾».","url":""}]},{"id":"s6-100","number":100,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما سرّ الاستفهام بـ﴿أي شيء أكبر شهادة﴾، دون: مَن أكبر الشهداء؟","answer":"لفظ ﴿شيء﴾ من أعم الألفاظ، فوسّع دائرة المفاضلة لتشمل كل ما يمكن أن تُتصوّر له شهادة، ثم جاء الجواب بأن الله أكبر شهادة؛ فلا تبقى شهادة تقابل شهادته أو تدانيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص362–363، تحت «دلالة إيثار لفظ ﴿شيء﴾ دون لفظ «شهيد» في قوله: ﴿قل أي شيء﴾»","url":""}]},{"id":"s6-101","number":101,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما الغرض من الاستفهام بـ﴿أي﴾ في قوله تعالى: ﴿أي شيء أكبر شهادة﴾؟","answer":"يوقظ السامع ويهيئه للنظر في أكبر شهادة، ويلزمه الإقرار بأن شهادة الله لا تعلوها شهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص360، تحت عنوان «الغرض من استعمال الاستفهام ﴿أي﴾»","url":""}]},{"id":"s6-1063","number":1063,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة المبادرة بالجواب في قوله تعالى: ﴿قل أي شيء أكبر شهادة قل الله﴾؟","answer":"حسم الوحي النتيجة التي لا تحتمل جوابًا آخر، وأعلن أن الله هو الأكبر شهادة قبل أن يجد المكذبون سبيلًا للمماراة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص365–366، تحت عنوان «دلالة المبادرة بالجواب عن السؤال في قوله: ﴿قل أي شيء أكبر شهادة﴾»","url":""}]},{"id":"s6-102","number":102,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة التعبير باسم ﴿شهيد﴾ في قوله تعالى: ﴿قل الله شهيد بيني وبينكم﴾؟","answer":"﴿شهيد﴾ صيغة تدل على ثبوت الشهادة وقوتها وإحاطتها؛ وشهادة الله منزّهة عن الكذب والخطأ والسهو، وتظهر فيما أقامه من آيات وبراهين على صدق رسوله ﷺ. فناسب الاسم مقام الاحتكام الفاصل بين الرسول والمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص366، تحت عنوان «دلالة التعبير بقوله ﴿شهيد﴾ دون شاهد»","url":""}]},{"id":"s6-103","number":103,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة تكرار ﴿بين﴾ في قوله تعالى: ﴿بيني وبينكم﴾؟","answer":"أعيدت ﴿بين﴾ مع الطرف الثاني لإظهار طرفي الخصومة مستقلين في مقام الاحتكام: الرسول ﷺ من جهة، والمكذبون من جهة أخرى. والتكرار هو الأسلوب العربي المبين للعلاقة بين جانبين، وفيه تقوية لصورة الفصل بالشهادة بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص366، تحت «دلالة تكرار ﴿بين﴾ في قوله تعالى: ﴿بيني وبينكم﴾ بدلًا من قوله: بيننا».","url":""}]},{"id":"s6-104","number":104,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة بناء الفعل للمفعول في قوله تعالى: ﴿وأوحي إلي هذا القرآن﴾؟","answer":"حُذف فاعل الوحي للعلم به؛ فالسياق قد عيّن أن الله هو الشهيد وهو موحي القرآن، وتوجه الاهتمام إلى نفس الوحي الواصل إلى الرسول ﷺ وإلى الكتاب الذي صار حجةً وإنذارًا. فالحذف لا يُجهّل المصدر، بل يبرز موضع الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص369، تحت «دلالة بناء الفعل ﴿أوحي﴾ في قوله تعالى: ﴿وأوحي إلي هذا القرآن﴾».","url":""}]},{"id":"s6-105","number":105,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة اسم الإشارة في قوله تعالى: ﴿وأوحي إلي هذا القرآن﴾؟","answer":"استحضر القرآن المعلوم المتلو عليهم وعيّن الحجة الحاضرة، فكأنهم يواجهون الشاهد على صدق الرسول مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص368، تحت عنوان «دلالة التعبير باسم الإشارة في قوله: ﴿هذا القرآن﴾»","url":""}]},{"id":"s6-1064","number":1064,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة اختيار لفظ ﴿القرآن﴾ دون ﴿الكتاب﴾؟","answer":"اختير القرآن لإبراز الوحي المتلو المسموع الذي بلغهم به الرسول، وتمييزه من الكتب السابقة التي يشملها اسم الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص368–369، تحت عنوان «دلالة اختيار لفظ القرآن دون الكتاب»","url":""}]},{"id":"s6-106","number":106,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"لم جعل قوله تعالى: ﴿لأنذركم به﴾ الإنذار غايةً لإيحاء القرآن هنا مع أنه يتضمن البشارة أيضًا؟","answer":"لأن المقام خطاب للمكابرين المعاندين، فناسبه التحذير مما يترتب على كفرهم. والاقتصار على الإنذار هنا لا ينفي البشارة؛ فالقرآن يجمعهما، والغاية المذكورة تناسب حال المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص369–370، تحت «سر التعبير بالنذارة دون البشارة في قوله: ﴿لأنذركم به﴾»","url":""}]},{"id":"s6-107","number":107,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة الإيجاز بالحذف في قوله تعالى: ﴿ومن بلغ﴾؟","answer":"حذف مفعول ﴿بلغ﴾ لاتضاحه، أي: ومن بلغه القرآن، وأوجز الحذف مع تعميم كل من وصل إليه الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص369، تحت عنوان «دلالة الإيجاز بالحذف في قوله تعالى: ﴿ومن بلغ﴾»","url":""}]},{"id":"s6-1065","number":1065,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة اختيار لفظ البلاغ في قوله تعالى: ﴿ومن بلغ﴾؟","answer":"يشمل اللفظ كل من وصل إليه القرآن أو معناه على وجه تقوم به الحجة، في أي لسان وزمان ومكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص371، تحت عنوان «دلالة اختيار لفظ البلاغ دون غيره في قوله: ﴿ومن بلغ﴾»","url":""}]},{"id":"s6-108","number":108,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة عطف ﴿ومن بلغ﴾ على المخاطبين في قوله تعالى: ﴿لأنذركم به ومن بلغ﴾؟","answer":"نقل العطف الإنذار من المخاطبين الأولين في مكة إلى كل إنسان يبلغه القرآن؛ فمن بلغه بعد الرسول ﷺ فكأنما سمعه منه ما دام قد وصل إليه بلا زيادة ولا نقصان. وبذلك دلّ التركيب على عموم الرسالة واستمرار حجتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص370، تحت «دلالة عطف ﴿ومن بلغ﴾ على ضمير المخاطبين ﴿لأنذركم﴾».","url":""}]},{"id":"s6-109","number":109,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما بلاغة التعبير بالاستفهام في قوله: ﴿أئنكم لتشهدون أن مع الله آلهة أخرى﴾ بدل الخبر؟","answer":"واجههم الاستفهام إنكارًا وتوبيخًا بعد قيام شهادة الله، وكشف أن دعواهم لا يمكن أن تقوم على شهادة معتبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص372، تحت عنوان «بلاغة التعبير بالأسلوب الإنشائي دون الخبري»","url":""}]},{"id":"s6-1066","number":1066,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما علة التوكيد في قوله تعالى: ﴿أئنكم لتشهدون﴾؟","answer":"اجتمع الاستفهام و﴿إن﴾ واللام لاستقصاء الحجة وإبراز فظاعة شهادتهم بالشرك مع وضوح بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص372–373، تحت عنوان «علة التوكيد بقوله تعالى: ﴿أئنكم لتشهدون﴾»","url":""}]},{"id":"s6-110","number":110,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما سرّ وصف جمع ﴿آلهة﴾ بالمفرد المؤنث ﴿أخرى﴾؟","answer":"﴿آلهة﴾ جمع لغير العاقل، ووصف جمع غير العاقل يجري مجرى المفردة المؤنثة؛ فقيل ﴿أخرى﴾. وفي ذلك أيضًا جمع لهذه المعبودات في وصف واحد، والتنبيه على ضعفها وهوان أمرها وبطلان تسميتها آلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص373–374، تحت «دلالة وصف الآلهة بالتأنيث في قوله: ﴿آلهة أخرى﴾»","url":""}]},{"id":"s6-111","number":111,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة تكرار الأمر ﴿قل﴾ أربع مرات في الآية؟","answer":"تكرر ﴿قل﴾ أربع مرات لأن كل مقولة بعدها رسالة مستقلة عظيمة يجب إعلانها: طرح الحجة، وتعيين الله شهيدًا، ورفض شهادة الشرك، وإعلان التوحيد والبراءة منه. وفي التكرار تلقين للنبي ﷺ وتثبيت وعناية، وتنبيه إلى أهمية كل جواب ومبادرة تبليغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص374، تحت عنوان «علة تكرار الأمر بـ﴿قل﴾ في قوله تعالى: ﴿قل لا أشهد قل إنما هو إله واحد﴾»","url":""}]},{"id":"s6-112","number":112,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة الجواب الموجز الحاسم: ﴿قل لا أشهد﴾؟","answer":"جاء النفي مباشرًا ليقطع كل احتمال لموافقتهم على شهادة الشرك؛ فلا يدخل الرسول ﷺ معهم في أصل الدعوى ولا يطيل مناقشة شهادة لا برهان لها. ثم أعقب الرفض بإثبات الحق: ﴿قل إنما هو إله واحد﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص375، تحت «دلالة الفصل بين قوله: ﴿قل لا أشهد﴾ وقوله: ﴿قل إنما هو إله واحد﴾»","url":""}]},{"id":"s6-113","number":113,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة القصر في قوله تعالى: ﴿إنما هو إله واحد﴾؟","answer":"قصر الألوهية على الله وحده، فنفى أن يكون معه إله آخر يستحق العبادة. وجاء الضمير عائدًا إلى الله المذكور قبلُ، فاستغنى به عن تكرار الاسم، وانتقل الكلام من نفي شهادة الشرك إلى تقرير حقيقة التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص375–376، تحت «دلالة القصر في قوله تعالى: ﴿قل إنما هو إله واحد﴾»","url":""}]},{"id":"s6-114","number":114,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة التعبير بالاسم ﴿بريء﴾ في قوله تعالى: ﴿وإنني بريء مما تشركون﴾؟","answer":"الاسم يدل على ثبوت البراءة واستقرارها، لا على فعل عارض يقع مرة؛ والبراءة في أصلها تخلّص ومفارقة وتباعد مما يُكره. فالصيغة إعلان دائم قاطع بمفارقة الشرك وما يُعبد من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص377، تحت عنوان «دلالة اختيار ﴿بريء﴾ دون غيرها في قوله: ﴿وإنني بريء مما تشركون﴾»","url":""}]},{"id":"s6-115","number":115,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة عموم قوله تعالى: ﴿مما تشركون﴾؟","answer":"الموصول ﴿ما﴾ يعم كل ما يجعلونه شريكًا لله، والتعبير بالفعل يستحضر فعل الإشراك المتجدد ولا يقتصر على أسماء أصنام بعينها. فالبراءة شاملة للمعبودات الباطلة وللمنهج الذي يسوّيها بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص377–378، تحت «دلالة التعبير بـ«ما» في قوله تعالى: ﴿مما تشركون﴾؛ ودلالة التعبير بالفعل المضارع في قوله: ﴿تشركون﴾»","url":""}]},{"id":"s6-116","number":116,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"إلى مَن يعود الضمير في قوله تعالى: ﴿يعرفونه كما يعرفون أبناءهم﴾؟","answer":"يعود الضمير إلى النبي محمد ﷺ؛ أي إن علماء أهل الكتاب يعرفونه بحليته ونعته الثابت في كتبهم كما يعرفون أبناءهم. وجاءت الآية حجة على المكذبين بمعرفة أهل الكتاب بصدق نبوته، مع أن بعض المفسرين وسّع مرجع الضمير إلى القرآن أو الحق المتقدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص387–388، تحت عنوان «تعدد أقوال المفسرين في عود الضمير في قوله تعالى: ﴿يعرفونه﴾»","url":""}]},{"id":"s6-117","number":117,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة التعبير بالموصول في قوله تعالى: ﴿الذين آتيناهم الكتاب﴾؟","answer":"عرّفهم بالصلة التي هي موضع الحجة: إيتاؤهم الكتاب ودراستهم له. فالمقصود خاصة علماؤهم الذين عرفوا ما في التوراة والإنجيل من صفة النبي ﷺ، لا كل منتسب إلى أهل الكتاب؛ وبذلك صار علمهم سببًا للاحتجاج بشهادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص384، تحت «دلالة التعريف بالاسم الموصول في قوله: ﴿الذين آتيناهم الكتاب﴾»","url":""}]},{"id":"s6-118","number":118,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة تعريف ﴿الكتاب﴾ في قوله تعالى: ﴿آتيناهم الكتاب﴾؟","answer":"التعريف للعهد؛ أي الكتاب المعروف الذي أوتيته كل طائفة، وهو التوراة لليهود والإنجيل للنصارى. وفي التعريف استحضار المرجع الذي قامت به معرفتهم، فلا تصدر شهادتهم عن ظن بل عما وجدوه في الوحي الذي بأيديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص386–387، تحت «دلالة دخول «أل» على لفظ ﴿الكتاب﴾ في قوله: ﴿الذين آتيناهم الكتاب﴾»","url":""}]},{"id":"s6-119","number":119,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة التعبير بـ﴿يعرفونه﴾، دون: يعلمونه؟","answer":"المعرفة تتعلق بذات الشيء وتمييزه من آثاره وصفاته، أما العلم فيتسع للحكم على أحواله ونِسَبه؛ فناسبت ﴿يعرفونه﴾ معرفتهم شخص النبي ﷺ بصفته ونعته، كما تُعرف ذات الابن معرفة لا اشتباه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص387، تحت «سر اختيار التعبير القرآني لكلمة ﴿يعرفونه﴾ دون يعلمونه»","url":""}]},{"id":"s6-120","number":120,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة التشبيه في قوله تعالى: ﴿يعرفونه كما يعرفون أبناءهم﴾؟","answer":"قرر التشبيه أن معرفتهم بالنبي ﷺ واضحة متمكنة لا يشوبها التباس، كمعرفة المرء بأقرب الناس إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص388، تحت عنوان «دلالة التشبيه في قوله تعالى: ﴿كما يعرفون أبناءهم﴾»","url":""}]},{"id":"s6-1067","number":1067,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما سر اختيار الأبناء في قوله تعالى: ﴿كما يعرفون أبناءهم﴾؟","answer":"الابن ألصق الناس بأبيه وأكثرهم حضورًا بين يديه، فتتميز صورته وصفاته لديه بلا اشتباه؛ فناسبه تمثيل المعرفة اليقينية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص388–389، تحت عنوان «سر اختيار لفظ الأبناء دون غيرهم في قوله تعالى: ﴿كما يعرفون أبناءهم﴾»","url":""}]},{"id":"s6-121","number":121,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة عدم عطف قوله تعالى: ﴿الذين خسروا أنفسهم فهم لا يؤمنون﴾ على ما قبله؟","answer":"جاءت الجملة مستأنفة لتبين مآل من عرف الحق ثم لم يؤمن به، فكأنها جواب عن سؤال يثيره إثبات معرفتهم: فما حال من كتمها؟ حاله أنه خسر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص389–390، تحت عنوان «دلالة عدم عطف جملة ﴿الذين خسروا أنفسهم﴾ على ما قبلها»","url":""}]},{"id":"s6-122","number":122,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما فائدة العدول من النفي إلى الاستفهام في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"الاستفهام إنكاري يفيد أنه لا أحد أبلغ ظلمًا ممن اختلق على الله أو كذب بآياته؛ لأن الجريمتين تفسدان أصل الهداية: إحداهما تنسب إلى الله ما لم يقل، والأخرى ترد ما أقام عليه حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص397–398، تحت عنوان «فائدة العدول من النفي إلى الاستفهام في قوله: ﴿ومن أظلم ممن افترى﴾»","url":""}]},{"id":"s6-123","number":123,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة صيغة أفعل التفضيل في قوله تعالى: ﴿أظلم﴾؟","answer":"تدل ﴿أظلم﴾ على بلوغ المفترين والمكذبين أعلى درجات الظلم؛ لعظم جرأتهم على الله بنسبة الشريك أو الولد إليه، ولتكذيبهم بآياته وإنكار رسوله. والاستفهام المصاحب ينفي أن يوجد من هو أشد منهم ظلمًا في هذا الباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص398، تحت عنوان «سر التعبير بـ«أفعل» التفضيل في قوله: ﴿ومن أظلم ممن افترى على الله﴾»","url":""}]},{"id":"s6-124","number":124,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة الجمع بين ﴿افترى﴾ و﴿كذبًا﴾ في قوله تعالى: ﴿افترى على الله كذبًا﴾؟","answer":"الافتراء هو الكذب المتعمد المختلق، وجاء ﴿كذبًا﴾ مصدرًا مؤكدًا له يصرح بقبح حقيقته ويزيل كل احتمال أن يكون خطأً أو وهمًا. وفي التقارب الاشتقاقي مع ﴿كذّب﴾ بعده إبراز لوجهي الجريمة: اختلاق الباطل وردّ الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص400، تحت «تقديم الافتراء على الكذب»","url":""}]},{"id":"s6-125","number":125,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة العطف بـ﴿أو﴾ بين الافتراء على الله والتكذيب بآياته؟","answer":"تفيد ﴿أو﴾ أن كل واحد من الفعلين مستقل في بلوغ غاية الظلم، سواء اختلق المرء على الله باطلًا أم رد آياته الثابتة؛ وقد يجتمعان في شخص واحد، فيجمع بين صناعة الكذب ومحاربة الحق. فهي تمنع توهم أن الحكم لا يثبت إلا باجتماعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص400–401، تحت «دلالة ﴿أو﴾ في قوله تعالى: ﴿أو كذب بآياته﴾»","url":""}]},{"id":"s6-126","number":126,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة دخول الباء على ﴿آياته﴾ في قوله تعالى: ﴿أو كذب بآياته﴾؟","answer":"وصلت الباء فعل التكذيب بالآيات وصورت تلبس المكذب بإنكارها وملازمته له؛ فكلما واجه آية تصدى لردها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص401–402، تحت عنوان «دلالة دخول حرف الجر على قوله تعالى: ﴿بآياته﴾»","url":""}]},{"id":"s6-1068","number":1068,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"لماذا قيل: ﴿بآياته﴾ دون «بالقرآن»؟","answer":"لأن الآيات أعم؛ فتشمل آيات الوحي ودلائل الكون وما أقامه الله من براهين، فيعم الوعيد كل تكذيب بحججه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص401–402، تحت عنوان «دلالة التعبير بـ﴿بآياته﴾ دون القرآن في قوله: ﴿أو كذب بآياته﴾»","url":""}]},{"id":"s6-127","number":127,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة وضع الظاهر موضع المضمر في قوله تعالى: ﴿لا يفلح الظالمون﴾؟","answer":"أظهر وصف الظلم بدل أن يقال «لا يفلحون» ليصرح بعلة الحرمان من الفلاح، وهي ظلمهم بالافتراء والتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص403–404، تحت عنوان «دلالة التعبير بوضع الظاهر موضع المضمر في قوله: ﴿لا يفلح الظالمون﴾»","url":""}]},{"id":"s6-1069","number":1069,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"لماذا قيل: ﴿الظالمون﴾ دون «الأظلمون»؟","answer":"لئلا يوهم وصف الأظلم أن من كان أقل ظلمًا قد يفلح بظلمه؛ فنفى الفلاح عن جنس الظالمين كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص404، تحت عنوان «سر التعبير بلفظ ﴿الظالمون﴾ دون الأظلمون»","url":""}]},{"id":"s6-128","number":128,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة التعبير بقوله ﴿جميعًا﴾ في قوله تعالى: ﴿ويوم نحشرهم جميعًا﴾؟","answer":"أكد ﴿جميعًا﴾ استيعاب الحشر للعابدين ومعبوداتهم من غير تخلف، لتقع المواجهة على رؤوس الأشهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص411–412، تحت عنوان «دلالة التعبير بقوله ﴿جميعًا﴾ في قوله تعالى: ﴿ويوم نحشرهم جميعًا﴾»","url":""}]},{"id":"s6-1070","number":1070,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"لماذا قيل: ﴿جميعًا﴾ دون «كل» في آية الحشر؟","answer":"لأن ﴿جميعًا﴾ تصور ضم الأفراد بعضهم إلى بعض في موقف واحد، أما ﴿كل﴾ فتركز على استغراق الأفراد ولو متفرقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص412، تحت عنوان «سر التعبير بلفظ ﴿جميعًا﴾ دون (كل) في الآية»","url":""}]},{"id":"s6-129","number":129,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم نقول للذين أشركوا﴾؟","answer":"تفيد ﴿ثم﴾ التراخي بين الحشر وبين سؤال التقريع؛ فيُجمعون أولًا في هول الموقف، ثم تأتي المواجهة التي تكشف سقوط شركائهم. ويصلح التراخي هنا للزمن ولرتبة ما بعده من شدة التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص412–413، تحت «سر التعبير بحرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم نقول للذين أشركوا﴾»","url":""}]},{"id":"s6-130","number":130,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة وصفهم بالصلة في قوله تعالى: ﴿للذين أشركوا﴾، دون: للمشركين؟","answer":"الصلة تستحضر الفعل الذي صار سببًا للسؤال والعقوبة: هم الذين أحدثوا الشرك وجعلوا لله أندادًا. وفي الفعل الماضي تسجيل للجريمة التي وقعت منهم، تمهيدًا لتبكيتهم على الشركاء الذين زعموهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص413، تحت «دلالة التعبير بقوله ﴿للذين أشركوا﴾ بدلًا من المشركين»","url":""}]},{"id":"s6-131","number":131,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"لماذا أوثر الاستفهام في قوله تعالى: ﴿أين شركاؤكم﴾ بدل الخبر؟","answer":"للتقريع والتعجيز؛ إذ يلزمهم أن يطلبوا شركاءهم فلا يجدوهم، فيظهر بطلان اعتقادهم في صورة مواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص413–414، تحت عنوان «إيثار الاستفهام بدلًا من الخبر في قوله تعالى: ﴿أين شركاؤكم﴾»","url":""}]},{"id":"s6-1071","number":1071,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما المجاز في قوله تعالى: ﴿أين شركاؤكم الذين كنتم تزعمون﴾؟","answer":"استعمل سؤال المكان وأريد به نفي وجود الشركاء ونفعهم؛ فعدم العثور على مكانهم كناية عن تلاشي دعواهم وعجز معبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص414، تحت عنوان «بلاغة المجاز في قوله تعالى: ﴿أين شركاؤكم الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-132","number":132,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة إضافة الشركاء إليهم في قوله تعالى: ﴿شركاؤكم﴾؟","answer":"أضيفوا إلى المشركين لأنهم شركاء في زعمهم واختراعهم وحدهم، لا شركاء لله في الحقيقة؛ فالإضافة تتبرأ من إقرار تسميتهم، وتحملهم تبعة ما صنعوه من نسبة الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص414–415، تحت «علة الإضافة في قوله تعالى: ﴿أين شركاؤكم﴾»","url":""}]},{"id":"s6-133","number":133,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة حذف معمولي ﴿تزعمون﴾ في قوله تعالى: ﴿الذين كنتم تزعمون﴾؟","answer":"حذف المفعولان لدلالة السياق عليهما، والتقدير: تزعمونهم شركاء. وفي هذا الإيجاز تحقير للدعوى وأصحابها، وإيحاء بضياع ما تعلقوا به وانقطاع الصلات التي توهموها بينهم وبين معبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص416، تحت «دلالة حذف مفعولي زعم في قوله تعالى: ﴿الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-134","number":134,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما سر التعبير بالزعم في قوله تعالى: ﴿الذين كنتم تزعمون﴾؟","answer":"الزعم قول لا يقوم على برهان ويُتهم صاحبه فيه، فسمى اعتقادهم زعمًا ليكشف أنه دعوى باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص416، تحت عنوان «سر التعبير بالزعم في قوله: ﴿الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-1072","number":1072,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة المضارع في قوله تعالى: ﴿الذين كنتم تزعمون﴾؟","answer":"استحضر تجدد زعمهم واستمرارهم عليه في الدنيا، فزاد سؤالهم عنه يوم القيامة تقريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص416–417، تحت عنوان «دلالة التعبير بالفعل المضارع في قوله: ﴿الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-135","number":135,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة تسمية جوابهم يوم القيامة ﴿فتنتهم﴾؟","answer":"الفتنة هنا ما انتهى إليه افتتانهم بالشرك من معذرة وجواب مضطرب؛ فلم يجدوا عند الامتحان إلا أن ينكروا ما كانوا عليه. وتسميته فتنتهم تصل مبدأ الضلال في الدنيا بعاقبته الفاضحة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص420–421، تحت «التعبير بلفظ الفتنة في قوله تعالى: ﴿ثم لم تكن فتنتهم﴾»","url":""}]},{"id":"s6-136","number":136,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة القصر في قوله تعالى: ﴿ثم لم تكن فتنتهم إلا أن قالوا﴾؟","answer":"حصر القصر كل ما استطاعوا تقديمه من معذرة في قول واحد هو إنكار شركهم؛ فلم تبق لهم حجة ولا دفاع سوى الكذب. وفي ذلك تصوير لإفلاسهم بعد أن كانوا يجادلون ويزعمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص422، تحت «دلالة أسلوب القصر في قوله: ﴿ثم لم تكن فتنتهم إلا أن قالوا﴾»","url":""}]},{"id":"s6-137","number":137,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة قسمهم يوم القيامة: ﴿والله ربنا ما كنا مشركين﴾؟","answer":"أكدوا إنكارهم بالقسم لشعورهم بأن دعواهم لا تصدق؛ فهم يعلمون ما كانوا عليه من الشرك، ومع ذلك يحاولون نفيه بين يدي الله. فيكشف القسم شدة مكابرتهم، ويجعل كذبهم على أنفسهم أظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص423، تحت «دلالة توكيد الخبر بالقسم في قوله تعالى: ﴿والله ربنا ما كنا مشركين﴾»","url":""}]},{"id":"s6-138","number":138,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة ذكر الربوبية بعد الألوهية في قولهم: ﴿والله ربنا﴾؟","answer":"اعترفوا بأن المقسم به ربهم المالك لأمرهم؛ فجاء إقرار الربوبية في قلب إنكار الشرك ليكشف تناقضهم ويزيد كذبهم ظهورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص423، تحت عنوان «دلالة ذكر الربوبية بعد ذكر الألوهية في قوله تعالى: ﴿والله ربنا﴾»","url":""}]},{"id":"s6-1073","number":1073,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما أثر القراءات في معنى قوله تعالى: ﴿والله ربنا ما كنا مشركين﴾؟","answer":"على نصب ﴿ربنا﴾ يكون نداءً أو مدحًا، وعلى جره يكون وصفًا لاسم الجلالة؛ وفي الوجهين إقرار بأن الله ربهم مع قسمهم الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص423، تحت عنوان «أثر القراءات في تفسير قوله تعالى: ﴿والله ربنا ما كنا مشركين﴾»","url":""}]},{"id":"s6-139","number":139,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة ﴿ثم﴾ في الانتقال من سؤالهم عن الشركاء إلى قوله: ﴿ثم لم تكن فتنتهم إلا أن قالوا﴾؟","answer":"تفيد انتقالًا إلى حال أعجب وأشد استحقاقًا للتعجيب: بعد افتتانهم بالشرك واستقرارهم عليه في الدنيا، يتبرؤون منه ويحلفون أنهم لم يكونوا مشركين. فالتراخي في رتبة الخبر يبرز انقلابهم وتناقضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص420، تحت «إيثار التعبير بـ﴿ثم﴾ في قوله تعالى: ﴿ثم لم تكن فتنتهم﴾»","url":""}]},{"id":"s6-140","number":140,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما المجاز في قوله تعالى: ﴿انظر كيف كذبوا على أنفسهم﴾؟","answer":"أطلق النظر وأريد التأمل في هيئة كذبهم وتناقضهم، وعرض مشهد القيامة المستقبل كأنه حاضر منظور لتحقق وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص426–427، تحت عنوان «دلالة المجاز المرسل في قوله: ﴿انظر كيف كذبوا على أنفسهم﴾»","url":""}]},{"id":"s6-1074","number":1074,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما القيمة الدلالية للفعل ﴿انظر﴾ في قوله تعالى: ﴿انظر كيف كذبوا﴾؟","answer":"الأمر للتعجيب والاعتبار، ويوجه إلى تأمل كيفية الكذب ونتيجته لا إلى مجرد سماع خبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص427، تحت عنوان «القيمة الدلالية للفعل ﴿انظر﴾ في قوله تعالى: ﴿انظر كيف كذبوا﴾»","url":""}]},{"id":"s6-141","number":141,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما دلالة الاستفهام بـ﴿كيف﴾ في قوله تعالى: ﴿انظر كيف كذبوا﴾؟","answer":"﴿كيف﴾ توجه النظر إلى هيئة الكذب العجيبة وشدته: أقسموا على نفي أمر عاشوه وظهرت حقيقته. فالمقصود التعجب من الكيفية المتناقضة، لا مجرد نقل مضمون ما قالوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص427، تحت «دلالة الاستفهام بالأداة ﴿كيف﴾ من قوله: ﴿انظر كيف كذبوا﴾»","url":""}]},{"id":"s6-142","number":142,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما دلالة تعدية الكذب بـ﴿على﴾ في قوله تعالى: ﴿كذبوا على أنفسهم﴾؟","answer":"صرح بـ﴿على أنفسهم﴾ ليظهر سوء قولهم وضلال تفكيرهم: فهم ينفون عن أنفسهم شركًا تعلم حقيقته، فكذبهم يناقض ما عاشوه وعرفوه. وفيه تعجيب من إنكارهم أمرًا لا يخفى عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص428، تحت «دلالة ذكر الجار والمجرور في قوله: ﴿على أنفسهم﴾»","url":""}]},{"id":"s6-143","number":143,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما الاستعارة في قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"صور معبوداتهم ودعاواهم بأشياء سلكت طريقًا ثم ضلت عنهم، فاختفت وقت حاجتهم ولم تنفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص428، تحت عنوان «بلاغة الاستعارة التصريحية التبعية في قوله: ﴿وضل عنهم ما كانوا يفترون﴾»","url":""}]},{"id":"s6-1075","number":1075,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"لماذا عُبر بالضلال دون الغيبة في قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"الضلال يصور فقدان الطريق والانفصال التام، فيجعل غياب المعبودات جزاءً ساخرًا لتعلقهم بها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص428–429، تحت عنوان «التعبير بالضلال دون الغيبة في قوله: ﴿وضل عنهم ما كانوا يفترون﴾»","url":""}]},{"id":"s6-144","number":144,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يفترون﴾؟","answer":"جاء الموصول عامًا فشمل المعبودات وما ألحقوه بها من دعاوى الشفاعة والنفع والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص429، تحت عنوان «دلالة ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يفترون﴾»","url":""}]},{"id":"s6-1076","number":1076,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"لماذا قيل: ﴿ما كانوا يفترون﴾ بدل «ما كانوا يعبدون»؟","answer":"سماها بحقيقتها: افتراءً صنعوه، فلم يقر لها باسم الشريك أو الإله إلا على جهة حكاية زعمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص430، تحت عنوان «دلالة التعبير بقوله: ﴿ما كانوا يفترون﴾ بدلًا من (ما كانوا يعبدون)»","url":""}]},{"id":"s6-145","number":145,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة الإفراد في قوله تعالى: ﴿ومنهم من يستمع إليك﴾ مع أن المستمعين جماعة؟","answer":"روعي لفظ ﴿من﴾ المفرد، فجاء ﴿يستمع﴾ بالإفراد، مع أن معناها يعم أفرادًا متعددين؛ فجمع التركيب بين إيجاز اللفظ وشمول الحكم. ثم عادت الضمائر جمعًا في ﴿قلوبهم﴾ و﴿آذانهم﴾ مراعاةً للمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص436، تحت «دلالة التعبير بصيغة الإفراد في قوله تعالى: ﴿من يستمع إليك﴾»","url":""}]},{"id":"s6-146","number":146,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة قوله تعالى: ﴿يستمع إليك﴾، دون: يستمع إلى القرآن؟","answer":"صوّرهم وهم يقصدون مجلس النبي ﷺ ويسمعون تلاوته منه مباشرة، فتقوم عليهم الحجة بقربهم من المبلّغ والبلاغ معًا. ومع ذلك لم يكن قصدهم الاهتداء، بل انتهى استماعهم إلى المجادلة والطعن في القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص437، تحت «إيثار كاف الخطاب في «إليك» من قوله: ﴿ومنهم من يستمع إليك﴾»","url":""}]},{"id":"s6-147","number":147,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما مناسبة جعل ﴿أكنة﴾ على القلوب و﴿وقرًا﴾ في الآذان؟","answer":"الأكنة أغطية تحجب القلب عن فقه المعنى، والوقر ثقل يصمّ الأذن عن الانتفاع بالمسموع؛ فناسب كل مانع آلته. واجتماعهما يمثل فرط بُعدهم عن الحق: لا السماع الظاهر أوصل، ولا القلب الباطن فقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص440–441، تحت «سر الجمع بين الوقر والأكنة في الآية الكريمة».","url":""}]},{"id":"s6-148","number":148,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما الذي تضيفه كلمة ﴿أكنة﴾ إلى صورة الحاجز على القلوب، بدل كلمة «أغطية»؟","answer":"الأكنة أبلغ في تصوير الستر؛ فهي توحي بأن القلب مستور داخل ما يحجبه، بينما لا يلزم من الغطاء هذا المعنى. وتناسب أيضًا الحاجز النفسي والمعنوي الذي يمنع فقه القرآن، فتقوى بها صورة الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص441، تحت «دلالة اختيار ﴿أكنة﴾ دون أغطية في قوله: ﴿وجعلنا على قلوبهم أكنة﴾»","url":""}]},{"id":"s6-149","number":149,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة التعبير بـ﴿أن يفقهوه﴾، دون: أن يفهموه؟","answer":"الفقه إدراك دقيق يصل إلى مراد الكلام وما وراء ظاهره، فهو أخص من مطلق الفهم؛ والآية لا تنفي وصول أصوات القرآن إلى آذانهم، بل تنفي نفاذ معانيه وحججه إلى قلوب أصرّت على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص442، تحت «دلالة اختيار لفظ الفقه دون لفظ الفهم».","url":""}]},{"id":"s6-150","number":150,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة التعبير بـ«إن» في قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾، وما دلالة الجملة الشرطية في قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾؟","answer":"علق عدم إيمانهم على رؤية كل آية ليبين أن العلة ليست نقص الدليل، بل إصرار القلب؛ فلو اجتمعت لهم الآيات كلها لم ينتفعوا بها. وفي ﴿كل﴾ بلوغ بالوصف أقصى درجات المكابرة بعد انسداد السمع والفقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص443–444، تحت «دلالة التعبير بـ«إن» في قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾؛ ودلالة الجملة الشرطية في قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾»","url":""}]},{"id":"s6-151","number":151,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"لم قيل: ﴿لا يؤمنوا بها﴾ بدل التصريح بوصفهم بالكفر؟","answer":"في نفي الإيمان مع قيام دلائله تشنيع على موقفهم، مع إبقاء باب الدعوة مفتوحًا؛ فالتعبير يدعوهم إلى ما فقدوه من التصديق والقبول، ولا يحول وصف حالهم الراهنة إلى حكم بأنهم لن يرجعوا إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص444، تحت «دلالة التعبير بنفي الإيمان بدلًا من الكفر في قوله: ﴿لا يؤمنوا بها﴾»","url":""}]},{"id":"s6-152","number":152,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاؤوك يجادلونك﴾؟","answer":"جعلت ﴿حتى﴾ مجيئهم للمجادلة غايةً لما قبلها: يستمعون، ولا يفقهون، ولا يؤمنون، ثم ينتهي أمرهم إلى الحضور لا لطلب الحق بل لمخاصمته. فهي تكشف المآل الذي بلغ إليه إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص444–445، تحت «دلالة التعبير بـ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاؤوك يجادلونك﴾»","url":""}]},{"id":"s6-153","number":153,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما سر التعبير بالماضي ﴿جاؤوك﴾ دون «أتوك»؟","answer":"المجيء يدل على قصد المجلس والحضور إليه، فصور سعيهم إلى النبي ﷺ مع ما أضمروه من مجادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص445، تحت عنوان «سر التعبير بالفعل الماضي ﴿جاؤوك﴾ دون أتوك»","url":""}]},{"id":"s6-1077","number":1077,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة قوله تعالى: ﴿يجادلونك﴾ في وصف مجيئهم؟","answer":"كشفت الحال أن غايتهم عند المجيء المنازعة والعناد لا الاسترشاد، فحوّلوا قربهم من الوحي إلى خصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص445–446، تحت عنوان «المجادلة مطلق المنازعة من خلال قوله: ﴿حتى إذا جاؤوك يجادلونك﴾»","url":""}]},{"id":"s6-154","number":154,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة إظهار الفاعل في قوله تعالى: ﴿يقول الذين كفروا﴾؟","answer":"أظهر وصف ﴿الذين كفروا﴾ بدل الضمير ليسجل عليهم الكفر ويبين أن اتهامهم القرآن ناشئ عن الجحود والمكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص447–448، تحت عنوان «دلالة إظهار الفاعل في قوله: ﴿يقول الذين كفروا﴾»","url":""}]},{"id":"s6-155","number":155,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما مناسبة فاصلة قوله تعالى: ﴿إن هذا إلا أساطير الأولين﴾ لصدر الآية؟","answer":"بدأت الآية باستماع لا يفضي إلى الفهم وختمت بالقول الذي كشف أثره؛ فقد سمعوا القرآن ثم وصفوه بالأساطير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص448، تحت عنوان «مناسبة الفاصلة لصدر الآية الكريمة»","url":""}]},{"id":"s6-1078","number":1078,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"لماذا كان اتهام القرآن بأنه ﴿أساطير الأولين﴾ كفرًا صريحًا؟","answer":"لأنه ينفي كونه وحيًا ويزعم أنه حكايات بشرية مختلقة، فيطعن في مصدره وصدقه معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص448، تحت عنوان «اتهام القرآن بأساطير الأولين كفر صراح»","url":""}]},{"id":"s6-156","number":156,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة القصر في قولهم: ﴿إن هذا إلا أساطير الأولين﴾؟","answer":"حصروا القرآن كله في أساطير السابقين، فنفوا عنه الوحي والحق والهداية نفيًا جازمًا. ويكشف هذا القصر شدة عنادهم؛ إذ لم يكتفوا بادعاء وجود قصص فيه، بل زعموا ألا حقيقة له وراء ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص447، تحت «بلاغة قصر القلب في قوله: ﴿يقول الذين كفروا إن هذا إلا أساطير الأولين﴾»","url":""}]},{"id":"s6-157","number":157,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة اختيار لفظ ﴿أساطير﴾ في طعنهم بالقرآن؟","answer":"الأساطير جمع أسطورة، وهي الأحاديث والأباطيل التي لا نظام لها في زعمهم؛ فاختاروا اللفظ لاتهام القرآن بأنه منقول مختلق لا وحي منزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص434، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s6-158","number":158,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة الجمع بين الفعلين المتقاربين جرسًا: ﴿ينهون عنه وينأون عنه﴾؟","answer":"جمعوا بين إضلال غيرهم وابتعادهم بأنفسهم: ينهون الناس عن اتباع الحق، وينأون هم عنه. والتقارب الصوتي بين الفعلين يرسخ تقابل الحركتين، ويكشف أن شرهم لم يقف عند ضلالهم بل تعداه إلى إضلال الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص454–455، تحت «بلاغة الجناس في قوله تعالى: ﴿وهم ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-159","number":159,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة حذف متعلق النهي والنأي في قوله تعالى: ﴿ينهون عنه وينأون عنه﴾؟","answer":"أطلق المتعلق اعتمادًا على السياق، فيشمل صدهم عن القرآن والرسول ﷺ وابتعادهم عنهما؛ فجمعوا إضلال غيرهم وضلال أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص454، تحت عنوان «عدم ذكر متعلق النهي والنأي في قوله تعالى: ﴿ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-160","number":160,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"لم لم يحدد قوله تعالى: ﴿وهم ينهون عنه وينأون عنه﴾ الأشخاص الذين يصدونهم عن الحق؟","answer":"حذف المفعول لإفادة العموم؛ فكانوا يريدون صد كل الناس عن سماع القرآن والإيمان بالنبي ﷺ. وجاء ذلك بإيجاز يصور اتساع سعيهم في المنع، مع ابتعادهم هم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص454، تحت «دلالة حذف مفعول الفعلين في قوله: ﴿وهم ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-161","number":161,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة تقديم نهيهم الناس على نأيهم بأنفسهم؟","answer":"قُدم النهي لأن خطره متعدٍّ إلى غيرهم، فهو إضلال بعد الضلال، ولأنه امتداد مباشر لمجادلتهم وطعنهم السابق في القرآن. ثم ذُكر نأيهم ليكتمل وصف من يمنع الآخرين مما لم ينتفع به هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص455، تحت «سر التعبير بتقديم قوله: ﴿وهم ينهون عنه﴾ على قوله: ﴿وينأون عنه﴾»","url":""}]},{"id":"s6-162","number":162,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة القصر في قوله تعالى: ﴿وإن يهلكون إلا أنفسهم﴾؟","answer":"حصر عاقبة صدهم في أنفسهم؛ فهم يظنون أنهم يطفئون نور الوحي ويضرون الرسول والمؤمنين، والحقيقة أنهم لا يسوقون إلى الهلاك إلا ذواتهم. فالقصر يقلب تقديرهم للنتيجة ويطمئن إلى أن الحق لا تضره مكائدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص456، تحت «دلالة القصر في قوله تعالى: ﴿وإن يهلكون إلا أنفسهم﴾».","url":""}]},{"id":"s6-163","number":163,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما المجاز العقلي في قوله تعالى: ﴿وإن يهلكون إلا أنفسهم﴾؟","answer":"أسند الهلاك إليهم لأنهم تسببوا فيه بكفرهم وصدهم، مع أن الله هو الذي يجازيهم به؛ فصورهم يهدمون أنفسهم بأفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص456، تحت عنوان «بلاغة المجاز العقلي في قوله: ﴿وإن يهلكون إلا أنفسهم﴾»","url":""}]},{"id":"s6-1079","number":1079,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما الفرق بين الهلاك والموت؟","answer":"الموت مفارقة الحياة، أما الهلاك فأعم في الفساد والضياع وسوء المصير؛ لذلك ناسب خسارة النفس بالكفر والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص457–458، تحت عنوان «الهلاك والموت»","url":""}]},{"id":"s6-1080","number":1080,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما سر التعبير بالجملة الفعلية في قوله: ﴿ينهون عنه وينأون عنه﴾؟","answer":"صورت الجملة تجدد فعلهم واستمرارهم في صد غيرهم وابتعادهم هم عن الوحي، فجمعوا الإضلال والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص455–456، تحت عنوان «سر التعبير بالجملة الفعلية بقوله تعالى: ﴿ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-165","number":165,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة المضارع في قوله تعالى: ﴿ولو ترى﴾ مع أن الوقوف على النار مستقبل؟","answer":"استُعمل المضارع لاستحضار المشهد المستقبل كأنه يقع الآن أمام العين؛ فتحول العقيدة بالغيب إلى صورة حية يرى السامع حركتها ويسمع حسرتها. وهذا أبلغ في الإنذار من الإخبار المجرد عما سيقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص461، تحت «دلالة التعبير بصيغة المضارع في قوله: ﴿ولو ترى إذ وقفوا على النار﴾».","url":""}]},{"id":"s6-166","number":166,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة المضارع في قوله تعالى: ﴿ولو ترى إذ وقفوا على النار﴾؟","answer":"يستحضر المضارع المشهد المستقبل حتى يبدو للسامع كأنه يراه الآن، فيقوى التخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص461، تحت عنوان «دلالة التعبير بصيغة المضارع في قوله: ﴿ولو ترى إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-1081","number":1081,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة التعبير عن المستقبل بالماضي في قوله تعالى: ﴿إذ وقفوا على النار﴾؟","answer":"صور الوقوف واقعًا مكتملًا متحققًا داخل المشهد المستحضر، فحقق المستقبل وجعله بمنزلة المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص461–462، تحت عنوان «دلالة التعبير عن المستقبل بالماضي في قوله: ﴿إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-167","number":167,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة بناء ﴿وُقفوا﴾ للمفعول؟","answer":"وجّه البناء للمفعول النظر إلى نفس الإيقاف وهوله، فهو المقصود الأعظم في المشهد، دون إشغال السياق بذكر من أوقفهم. وفي عرض حالهم بهذه الصورة توبيخ لهم وتعظيم لما يلاقونه يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص462، تحت «دلالة بناء الفعل لما لم يسم فاعله في قوله: ﴿ولو ترى إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-168","number":168,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة قوله تعالى: ﴿وُقفوا على النار﴾، دون: عند النار أو أمامها؟","answer":"من وجوه التعبير بـ﴿على﴾ أنهم أُطلعوا على النار وعاينوا حقيقتها، كما يقال: وقفت على الأمر، أي عرفته واطلعت عليه. فالمشهد يتجاوز مجرد القرب من مكانها إلى مواجهتها وانكشاف ما أنكروه، ولا يلزم من هذا الوجه تحديد موضعهم على حافتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص462–463، تحت «الدلالة على الاستعارة التبعية التصريحية في قوله: ﴿إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-169","number":169,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة حذف جواب ﴿لو﴾ في قوله تعالى: ﴿ولو ترى إذ وُقفوا على النار﴾؟","answer":"حُذف الجواب لتهويل المشهد؛ أي لرأيت أمرًا عظيمًا لا يحيط به وصف، فتذهب نفس السامع في تصوره كل مذهب. وما تلا الشرط من تمنّيهم الرجعة يفتح جانبًا من ذلك الهول دون أن يحصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص460–461، تحت «حذف جواب ﴿ولو﴾ الشرطية»","url":""}]},{"id":"s6-170","number":170,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة ﴿يا﴾ قبل التمني في قولهم: ﴿يا ليتنا نرد﴾؟","answer":"يجوز أن تكون ﴿يا﴾ للتنبيه، فتلفت إلى شدة أمنيتهم، وأن تكون للنداء مع حذف المنادى، كأنهم ينادون حسرتهم: يا حسرتنا أقبلي، فهذا أوانك. وفي الوجهين يظهر اضطرابهم وتحسرهم حين عاينوا العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص463–464، تحت «دلالة التعبير بحرف النداء (يا) في قوله تعالى: ﴿فقالوا يا ليتنا نرد﴾»","url":""}]},{"id":"s6-171","number":171,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة التعبير بـ﴿نُرد﴾، دون: نرجع؟","answer":"اختير ﴿نُرد﴾ لأن الرد إذا استعمل في الانتقال من حال إلى حال أفاد الإعادة إلى الحالة الأولى؛ فتمنوا أن يعادوا إلى دار التكليف ليستدركوا وجوه تقصيرهم بعد معاينة الأهوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص465–466، تحت «دلالة اختيار المشركين التعبير بالرد في هذا السياق»","url":""}]},{"id":"s6-172","number":172,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة ذكر الربوبية في قولهم: ﴿ولا نكذب بآيات ربنا﴾؟","answer":"اختاروا لفظ الربوبية طلبًا للتعطف والتحنن عليهم؛ لكن هذا الاسترحام جاء بعد فوات أوان الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص466–467، تحت «دلالة اختيار لفظ الربوبية في قوله: ﴿ولا نكذب بآيات ربنا﴾»","url":""}]},{"id":"s6-173","number":173,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما سر العدول من نفي الإشراك إلى قولهم: ﴿ونكون من المؤمنين﴾؟","answer":"انتقلوا من مجرد ترك الشرك إلى ادعاء الدخول في الإيمان، فصوروا أمنيتهم تحولًا كاملًا في الاعتقاد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص467، تحت عنوان «سر العدول عن نفي الإشراك إلى الإيمان»","url":""}]},{"id":"s6-1082","number":1082,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"لماذا قالوا: ﴿من المؤمنين﴾ دون «من الذين آمنوا»؟","answer":"الاسم يدل على ثبوت الصفة ورسوخها، فكأنهم يتمنون الانتماء الدائم إلى جماعة المؤمنين لا فعل إيمان عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص467، تحت عنوان «سر التعبير بـ﴿المؤمنين﴾ دون (الذين آمنوا)»","url":""}]},{"id":"s6-174","number":174,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة الإضراب بقوله تعالى: ﴿بل بدا لهم ما كانوا يخفون من قبل﴾ بعد تمنّيهم الرجعة؟","answer":"أضرب عن ظاهر أمنيتهم ليكشف باعثها الحقيقي: لم ينشأ قولهم عن إيمان راسخ، وإنما عن انكشاف ما أخفوه ومعاينة العاقبة. ولذلك بيّن بعدها أنهم لو رُدوا لعادوا إلى ما نُهوا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص472، تحت «أثر ﴿بل﴾ في البيان»","url":""}]},{"id":"s6-175","number":175,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة التعبير بقوله تعالى: ﴿بدا لهم﴾؟","answer":"البُدو ظهور الشيء بعد خفائه مع انكشافه للناظر، فناسب ما كتموه في الدنيا ثم صار يوم القيامة حاضرًا لا يمكن ستره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص472–473، تحت عنوان «بلاغة المجاز في قوله تعالى: ﴿بدا لهم﴾ ودلالة انتقاء الفعل ﴿بدا﴾»","url":""}]},{"id":"s6-176","number":176,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة اسم الموصول ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يخفون من قبل﴾؟","answer":"جاء الموصول واسعًا ليشمل ما أخفوه من القبائح ومعرفة الحق وما كتمته نفوسهم، وجامع ذلك انكشاف المستور يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص473–474، تحت عنوان «سر استعمال اسم الموصول (ما) في قوله تعالى: ﴿ما كانوا يخفون﴾»","url":""}]},{"id":"s6-177","number":177,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما المقابلة في قوله تعالى: ﴿بل بدا لهم ما كانوا يخفون من قبل﴾؟","answer":"قابل بين البدو والإخفاء، فصور انتقال ما كتموه في الدنيا إلى انكشاف لا يستطيعون دفعه في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص475، تحت عنوان «بديع المقابلة بين ﴿بدا لهم﴾ وقوله تعالى: ﴿ما كانوا يخفون من قبل﴾»","url":""}]},{"id":"s6-1083","number":1083,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة قطع الظرف ﴿قبل﴾ عن الإضافة؟","answer":"حذف المضاف إليه للعلم به، أي من قبل هذا الموقف في الدنيا، فركز اللفظ على تقابل زمن الكتمان وزمن الانكشاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص475–476، تحت عنوان «دلالة قطع الظرف ﴿قبل﴾»","url":""}]},{"id":"s6-178","number":178,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة الشرط في قوله تعالى: ﴿ولو ردوا لعادوا لما نهوا عنه﴾؟","answer":"كشف الشرط أن تمنّيهم وليد العذاب لا تحول راسخ؛ فلو عادوا إلى الدنيا عادوا إلى ما تأصل فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص476، تحت عنوان «دلالة أسلوب الشرط في تجلية المعنى، في قوله تعالى: ﴿ولو ردوا لعادوا لما نهوا عنه﴾»","url":""}]},{"id":"s6-1084","number":1084,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة نوع النهي وماهية المنهي عنه في قوله: ﴿لعادوا لما نهوا عنه﴾؟","answer":"يشمل النهي ما زجروا عنه من الشرك والتكذيب والمعاصي، ويفيد أن عودهم سيكون إلى جنس المخالفات التي منعتهم منها الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص478، تحت عنوان «دلالة نوع النهي ودرجته، وماهية المنهي عنه في السياق»","url":""}]},{"id":"s6-179","number":179,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة اللام في قوله تعالى: ﴿لعادوا لما نهوا عنه﴾؟","answer":"أفادت اللام استغراقهم في العودة إلى ما نهوا عنه من الكفر والمعاصي وفنون القبائح، ودلت على رسوخ إصرارهم عليها؛ فالآية لا تخبر بزلة مفردة بل برجوعهم إلى النهج الذي عهد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص477–478، تحت «دلالة اللام في قوله تعالى: ﴿لما نهوا عنه﴾»","url":""}]},{"id":"s6-180","number":180,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"إلى ماذا يتعلق قوله تعالى: ﴿لكاذبون﴾؟","answer":"يتعلق بوعدهم ألا يكذبوا وبزعمهم أنهم سيكونون مؤمنين، فالله يكشف أن أمنيتهم لا تطابق حقيقة نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص478، تحت عنوان «بيان متعلق قوله تعالى: ﴿لكاذبون﴾ في الآية الكريمة»","url":""}]},{"id":"s6-1085","number":1085,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما أثر تعدد المؤكدات في قوله تعالى: ﴿وإنهم لكاذبون﴾؟","answer":"أكدت ﴿إن﴾ واللام والجملة الاسمية ثبوت الكذب فيهم، وقطعت احتمال صدق وعد ولدته رهبة الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص478–479، تحت عنوان «أثر تعدد المؤكدات في جلاء المعنى في قوله تعالى: ﴿وإنهم لكاذبون﴾»","url":""}]},{"id":"s6-181","number":181,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما دلالة الضمير في قولهم: ﴿إن هي إلا حياتنا الدنيا﴾ مع عدم تقدم مرجع صريح؟","answer":"الضمير في ﴿إن هي﴾ مبهم، يفسره ما بعد الاستثناء المفرغ، وقُصد بإبهامه الإيجاز اعتمادًا على مفسره؛ فـ﴿حياتنا الدنيا﴾ بعد ﴿إلا﴾ في حكم البدل منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص485، تحت «دلالة الحصر بالنفي والاستثناء المفرغ في قوله تعالى: ﴿إن هي إلا حياتنا الدنيا﴾»","url":""}]},{"id":"s6-182","number":182,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]},{"surah":45,"verses":[24]}],"verseLabel":"الأنعام: 29؛ الجاثية: 24","question":"ما دلالة الحصر في قولهم: ﴿إن هي إلا حياتنا الدنيا﴾؟","answer":"حصروا جنس الحياة في الدنيا ونفوا حياة بعدها، فكان القصر تعبيرًا عن إنكار البعث، ثم أكدوه بقولهم: ﴿وما نحن بمبعوثين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص484–485، تحت عنوان «دلالة الحصر بالنفي والاستثناء المفرغ في قوله تعالى: ﴿إن هي إلا حياتنا الدنيا﴾»","url":""}]},{"id":"s6-183","number":183,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما دلالة وصف الحياة بـ﴿الدنيا﴾ في حكاية قول من ينكر الآخرة؟","answer":"﴿الدنيا﴾ هي الحاضرة القريبة العاجلة، ووصف الحياة بها توكيد لقصرهم الحياة عليها ونفي حياة سواها؛ ونسبوها إليهم لأنها موطن متعتهم، وفي ذلك إنكار صريح للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص485–486، تحت «دلالة وصف الحياة بـ(الدنيا) في الآية الكريمة»","url":""}]},{"id":"s6-184","number":184,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما دلالة الجملة الاسمية والباء في قولهم: ﴿وما نحن بمبعوثين﴾؟","answer":"الجملة الاسمية توحي بثبات النفي في اعتقادهم، ودخول الباء في خبرها يزيده توكيدًا؛ فلم يقولوا إن البعث مستبعد فحسب، بل رسخوا نفيه عن ذواتهم. وهذا التشديد يهيئ للمشهد الذي يضطرهم فيه الواقع إلى الإقرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص486، تحت «دلالة النفي مع تأكيده في قوله تعالى: ﴿وما نحن بمبعوثين﴾»","url":""}]},{"id":"s6-185","number":185,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما الذي ينكره قولهم: ﴿وما نحن بمبعوثين﴾ باستعمال لفظ البعث؟","answer":"البعث هنا إخراج الخلق من قبورهم وإرسالهم إلى الموقف؛ فهم لا ينكرون مجرد استمرار الحياة، بل ينكرون أن يعادوا بعد الموت ويخرجوا من القبور. لذلك يواجه هذا اللفظ أصل اعتقادهم بأن الحياة تنتهي بالدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص487، تحت «(البعث) و(النشور)»","url":""}]},{"id":"s6-186","number":186,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما سرّ تكرار مشهد ﴿ولو ترى إذ وُقفوا﴾ مع اختلاف المتعلّق: ﴿على النار﴾ و﴿على ربهم﴾؟","answer":"المشهد الأول يريهم عاقبة التكذيب ممثلة في النار فتنبعث أمنية الرجوع، والثاني ينقلهم إلى الوقوف للحساب أمام حكم ربهم فيُنتزع منهم الإقرار بالحق. فالتكرار ليس إعادة، بل تصعيد من معاينة الجزاء إلى مواجهة المالك الذي أنكرو لقاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص489–490، تحت «التناسب السياقي بين الآيتين المفتتحتين بقوله تعالى: ﴿ولو ترى إذ وقفوا﴾»","url":""}]},{"id":"s6-187","number":187,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الاستعارة التمثيلية في قوله تعالى: ﴿إذ وقفوا على ربهم﴾؟","answer":"مثلت حالهم حين عرضوا للحساب وعاينوا سلطان ربهم بحال من أوقف على أمر فبلغه وانكشف له، من غير دلالة على مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص492–493، تحت عنوان «بيان الاستعارة التمثيلية في ﴿وقفوا على ربهم﴾»","url":""}]},{"id":"s6-188","number":188,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"الاستفهام تقريري توبيخي، يُلزمهم الاعتراف بالبعث والعذاب اللذين أنكروهما بعد أن صارا معاينين؛ ولذلك لم يملكوا إلا أن يقولوا ﴿بلى﴾. فالسؤال ليس لطلب علم، بل لإقامة الحجة عليهم من إقرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص494، تحت «الاستفهام التقريري وأثره في المعنى في قوله تعالى: ﴿أليس هذا بالحق﴾».","url":""}]},{"id":"s6-189","number":189,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"إلى ماذا يشير ﴿هذا﴾ في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"يشير إلى البعث والحساب والعذاب الحاضر الذي يشاهدونه، وهو ما سبق أن أنكروه بقولهم ﴿وما نحن بمبعوثين﴾. والإشارة للقريب تجعل الحقيقة التي جحدوها كأنها موضوعة أمام أعينهم لا سبيل إلى إنكارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص494–495، تحت «بيان المشار إليه بـ(هذا) في قوله تعالى: ﴿أليس هذا بالحق﴾»","url":""}]},{"id":"s6-190","number":190,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة الباء في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"الباء زائدة في خبر ﴿ليس﴾ لتوكيد اتصاف المشار إليه بالحق؛ أي أليس هذا حقًا ثابتًا لا شك فيه؟ فجاءت تقوية الإثبات في مقابلة قوة إنكارهم السابق للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص495، تحت «دلالة الباء الزائدة في سياق الاستفهام المنفي، في قوله تعالى: ﴿أليس هذا بالحق﴾»","url":""}]},{"id":"s6-191","number":191,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة جوابهم بـ﴿بلى﴾، دون: نعم؟","answer":"﴿بلى﴾ موضوعة لإبطال النفي السابق؛ فلما قيل ﴿أليس هذا بالحق﴾ أجابوا بما يرفع النفي ويثبت أنه الحق. أما ﴿نعم﴾ في أصل الاستعمال فتصدق مضمون السؤال المنفي، وقد توهم استمرار النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص494، تحت «الاستفهام التقريري وأثره في المعنى، في قوله تعالى: ﴿أليس هذا بالحق﴾»","url":""}]},{"id":"s6-192","number":192,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة إيراد القسم في قولهم: ﴿بلى وربنا﴾؟","answer":"أكدوا بالقسم ما صار معلومًا لهم بالمشاهدة؛ فانقلبوا من إنكار البعث إلى إقرار مؤكد به حين لم يعد الإنكار ممكنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص495–496، تحت عنوان «إيراد القسم لتأكيد لازم فائدة الخبر، في قوله تعالى: ﴿بلى وربنا﴾»","url":""}]},{"id":"s6-1086","number":1086,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما سر استعمال مادة الربوبية في قسمهم: ﴿بلى وربنا﴾؟","answer":"استحضرت الربوبية سلطان من خلقهم وبعثهم وأوقفهم للحساب، فجاء إقرارهم بربه لهم شاهدًا على بطلان إنكارهم السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص495–496، تحت عنوان «سر استعمال مادة الربوبية في القسم، في قوله تعالى: ﴿قالوا بلى وربنا﴾»","url":""}]},{"id":"s6-193","number":193,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة فاء التفريع في قوله تعالى: ﴿قال فذوقوا العذاب﴾؟","answer":"فرعت الأمر بذوق العذاب على إقرارهم بالبعث والحق؛ فبعد أن شهدوا على أنفسهم لم يبق إلا الجزاء الذي كذبوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص496، تحت عنوان «دلالة فاء التفريع في ﴿قال فذوقوا﴾»","url":""}]},{"id":"s6-1087","number":1087,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الاستعارة في قوله تعالى: ﴿فذوقوا العذاب﴾؟","answer":"استعير الذوق، وهو إدراك الطعم، لمباشرة العذاب؛ فصور الألم شيئًا يجدون أثره بأنفسهم إدراكًا حسيًا لا واسطة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص496–497، تحت عنوان «مفهوم الاستعارة في قوله تعالى: ﴿فذوقوا العذاب﴾»","url":""}]},{"id":"s6-1088","number":1088,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الفرق الدلالي بين الذوق والإحساس في قوله تعالى: ﴿فذوقوا العذاب﴾؟","answer":"الذوق يدل على مباشرة الأثر واختباره، أما الإحساس فأعم؛ فاختير الذوق لتصوير شدة اتصال العذاب بهم ووجدانهم أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص499–500، تحت عنوان «الفرق بين الذوق والإحساس»","url":""}]},{"id":"s6-194","number":194,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة قوله تعالى: ﴿بما كنتم تكفرون﴾، دون: بكفركم؟","answer":"الباء سببية و﴿ما﴾ مصدرية؛ أي: بسبب كفركم، والتعبير بـ﴿كنتم تكفرون﴾ يستحضر دوامهم في الدنيا على الكفر وستر ما دلت عليه عقولهم من صدق الرسول، بدل تسمية الجريمة بالمصدر مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص497–498، تحت «الباء السببية وأثرها في المعنى، في قوله تعالى: ﴿بما كنتم تكفرون﴾»","url":""}]},{"id":"s6-195","number":195,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة التعبير بالماضي المؤكد في قوله تعالى: ﴿قد خسر﴾ مع أن الخسران الأخروي مستقبل؟","answer":"﴿قد﴾ مع الماضي تحقق وقوع الخسران حتى صُوّر المستقبل المقطوع به كأنه حدث وانتهى؛ فمن كذب بلقاء الله انعقد سبب خسارته من الآن. وفي الصيغة إنذار بأن النتيجة ليست احتمالًا ينتظر التجربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص505، تحت «دلالة حرف التحقيق ﴿قد﴾ في قوله تعالى: ﴿قد خسر﴾»","url":""}]},{"id":"s6-196","number":196,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة صلة الموصول في قوله تعالى: ﴿الذين كذبوا بلقاء الله﴾؟","answer":"عينت الصلة سبب الخسران وكشفت حقيقة أصحابه؛ فتكذيبهم بلقاء الله هو الذي ساقهم إلى الندامة حين قامت الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص506، تحت عنوان «دلالة صلة الموصول في الربط بين أجزاء السياق»","url":""}]},{"id":"s6-1089","number":1089,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما الاستعارة في قوله تعالى: ﴿بلقاء الله﴾؟","answer":"مثل الانتقال إلى موقف الحساب والجزاء بلقاء العبد ربه، فاستحضر قرب المواجهة وانكشاف العمل يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص506–507، تحت عنوان «بلاغة الاستعارة التمثيلية في قوله تعالى: ﴿بلقاء الله﴾»","url":""}]},{"id":"s6-197","number":197,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاءتهم الساعة بغتة﴾؟","answer":"جعلت مجيء الساعة غاية لإمهالهم واسترسالهم في التكذيب؛ فإذا بلغوه انقطع زمن العمل وبدأت الحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص507، تحت عنوان «دلالة ﴿حتى﴾ على الغاية في قوله تعالى: ﴿حتى إذا جاءتهم الساعة﴾»","url":""}]},{"id":"s6-1090","number":1090,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة أسلوب الشرط في قوله تعالى: ﴿إذا جاءتهم الساعة بغتة قالوا يا حسرتنا﴾؟","answer":"ربط الشرط مجيء الساعة المفاجئ بجواب لا يتخلف هو انفجار الحسرة، فصور سرعة انتقالهم من الغفلة إلى الندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص507–508، تحت عنوان «دلالة الشرط والجواب في قوله تعالى: ﴿إذا جاءتهم الساعة بغتة قالوا﴾»","url":""}]},{"id":"s6-198","number":198,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]},{"surah":7,"verses":[187]}],"verseLabel":"الأنعام: 31؛ الأعراف: 187","question":"ما نكتة تسمية يوم القيامة بالساعة؟","answer":"سميت الساعة لقربها وسرعة مجيئها أو لأنها تقع في وقت محدد بغتة، فاستحضرت التسمية مباغتة القيامة وقصر زمن الدنيا أمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص508–509، تحت عنوان «نكتة تسمية يوم القيامة بالساعة»","url":""}]},{"id":"s6-199","number":199,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة تقييد مجيء الساعة بقوله تعالى: ﴿بغتة﴾؟","answer":"﴿بغتة﴾ تعني فجأة من غير توقع ولا مهلة، فتصور الساعة وهي تواجه المكذبين وجهًا لوجه قبل أن يستدركوا تفريطهم. ولذلك أعقبها فورًا قولهم ﴿يا حسرتنا﴾؛ إذ انقضى زمن العمل وبقي انكشاف الخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص509، تحت «دلالة الوجوه الإعرابية للفظ ﴿بغتة﴾ وأثرها في توسيع المعنى»","url":""}]},{"id":"s6-200","number":200,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما المجاز في قولهم: ﴿يا حسرتنا﴾؟","answer":"نزلت الحسرة منزلة شخص حاضر ينادى؛ لاستحضارها وتعظيمها حين أحاطت بهم ولم يجدوا ما يدفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص509، تحت عنوان «دلالة المجاز في قوله تعالى: ﴿يا حسرتنا﴾»","url":""}]},{"id":"s6-1091","number":1091,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما فائدة النداء في قوله تعالى: ﴿يا حسرتنا على ما فرطنا فيها﴾؟","answer":"أبرز النداء شدة الندم حتى كأن الحسرة نفسها مطلوبة للحضور؛ فقد جاء وقتها واستولت عليهم عند فوات التدارك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص510، تحت عنوان «فائدة النداء في قوله تعالى: ﴿يا حسرتنا﴾»","url":""}]},{"id":"s6-1092","number":1092,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة إضافة الحسرة إلى ضميرهم في قولهم: ﴿يا حسرتنا﴾؟","answer":"نسبوا الحسرة إلى أنفسهم إقرارًا بأنها لازمتهم وكانت ثمرة تفريطهم، فلم تعد مصيبة عارضة يمكن فصلها عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص510، تحت عنوان «دلالة إضافة الحسرة إلى ضمير جمع المتكلم»","url":""}]},{"id":"s6-201","number":201,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة قولهم: ﴿على ما فرطنا فيها﴾، وإلى ماذا يعود ضمير ﴿فيها﴾؟","answer":"التفريط هو التقصير بتضييع ما كان ينبغي حفظه، والضمير في ﴿فيها﴾ يعود إلى الحياة الدنيا؛ أي تحسروا على ما ضيعوه فيها من الإيمان والعمل الصالح والاستعداد للساعة. وقيل يعود إلى الساعة بمعنى التفريط في شأنها، والمعنيان يلتقيان في إضاعة الاستعداد لها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص511، تحت «دلالة الضمير في ﴿فيها﴾ من قوله تعالى: ﴿على ما فرطنا فيها﴾»","url":""}]},{"id":"s6-202","number":202,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة تصوير الذنوب أوزارًا يحملونها في قوله تعالى: ﴿وهم يحملون أوزارهم﴾؟","answer":"الوزر في أصله الحمل الثقيل، فاستعير للذنوب وما يترتب عليها من وبال وعقوبة، وجُسدت المعاصي أثقالًا ملازمة لا يستطيع أصحابها طرحها. فتجعل الصورة المعنى الأخروي محسوسًا منفّرًا يرى فيه القارئ أثر العمل على حامله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص513، تحت «الاستعارة تجسد الآثام في صورة الأوزار، في قوله تعالى: ﴿يحملون أوزارهم﴾»","url":""}]},{"id":"s6-203","number":203,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما الكناية في قوله تعالى: ﴿وهم يحملون أوزارهم﴾؟","answer":"إضافة الأوزار إليهم كناية عن اختصاصهم بذنوبهم ولزوم تبعتها لهم؛ فلا يحملها عنهم أحد ولا يستطيعون طرحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص513، تحت عنوان «دلالة الكناية بإضافة الأوزار إليهم، في قوله تعالى: ﴿وهم يحملون أوزارهم﴾»","url":""}]},{"id":"s6-1093","number":1093,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما أثر اقتران التنكيت بالمبالغة في قوله تعالى: ﴿يحملون أوزارهم على ظهورهم﴾؟","answer":"خص الظهور لأنها موضع حمل الأثقال، وبالغ فجعل الذنوب أحمالًا محسوسة تثقلهم وتظهر خزيهم في موقف الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص513–514، تحت عنوان «اقتران التنكيت والمبالغة، في قوله تعالى: ﴿يحملون أوزارهم على ظهورهم﴾»","url":""}]},{"id":"s6-204","number":204,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دور ﴿ألا﴾ الاستفتاحية في قوله تعالى: ﴿ألا ساء ما يزرون﴾؟","answer":"نبهت السامع إلى الحكم الآتي وهولته، فلفتت الانتباه إلى فظاعة ما يحملونه وسوء عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص514، تحت عنوان «دور الأداة (ألا) الاستفتاحية في قوله تعالى: ﴿ألا ساء ما يزرون﴾»","url":""}]},{"id":"s6-1094","number":1094,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة الفعل ﴿ساء﴾ في قوله تعالى: ﴿ألا ساء ما يزرون﴾؟","answer":"أنشأ ذمًا بالغًا لما يحملونه من الآثام، ورد آخر الآية إلى مادة الوزر ليؤكد قبح الحمل وثقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص514–515، تحت عنوان «دلالة الفعل ﴿ساء﴾ في السياق وأثر ذلك في المعنى»","url":""}]},{"id":"s6-205","number":205,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة قصر الحياة الدنيا على اللعب واللهو؟","answer":"كشف حقيقة الدنيا حين تجعل غاية وتنقطع عن عمل الآخرة: شغل سريع الزوال لا يبقى لصاحبه، بخلاف ما يتصل بالدار الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص521، تحت عنوان «قصر الموصوف على الصفة»","url":""}]},{"id":"s6-1095","number":1095,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة ﴿أل﴾ في قوله تعالى: ﴿الحياة الدنيا﴾؟","answer":"هي للجنس، فتتناول جنس الحياة القريبة بما يزول من متاعها، ثم تقابلها الآية بالدار الآخرة الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص521–522، تحت عنوان «دلالة (أل) على تعريف الجنس في ﴿الحياة الدنيا﴾»","url":""}]},{"id":"s6-206","number":206,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة تقديم ﴿اللعب﴾ على ﴿اللهو﴾؟","answer":"قُدّم اللعب لأن سياق الآية في بيان الخسارة، وهي أكثر ما تكون من اللعب لما فيه من سرور النفس على غير وجه مشروع وسرعة انقضائه؛ ثم ذُكر اللهو إشارةً إلى الجهالة والانشغال بالأمور السافلة والشواغل الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص523، تحت «نكتة تقديم اللعب على اللهو في قوله تعالى: ﴿إلا لعب ولهو﴾»","url":""}]},{"id":"s6-207","number":207,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"لم لم يذكر المفضل عليه بعد ﴿وللدار الآخرة خير﴾؟","answer":"إذا حملت ﴿خير﴾ على التفضيل، فالتقدير: خير من الدنيا، وحذف المفضل عليه لأن المقابلة السابقة جعلته معلومًا. ويجوز أن يكون اللفظ لبيان ما في الآخرة من الخير في نفسه، دون قصد المفاضلة؛ فلا يحتاج حينئذ إلى مفضل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525، تحت «معنى لفظ ﴿خير﴾ وسر حذف المفضل عليه»","url":""}]},{"id":"s6-208","number":208,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة التعبير بـ﴿الدار الآخرة﴾ في مقابلة ﴿الحياة الدنيا﴾؟","answer":"عُبر عن الآخرة بالدار لأنها محل الإقامة ومقر الناس الأخير الذي لا تحول بعده، في مقابل الحياة الدنيا الأولى القريبة؛ فالمقابلة تكشف فناء الدنيا ودوام دار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص524–525، تحت «بيان التكنية عن القيامة في قوله تعالى: ﴿وللدار الآخرة خير﴾»","url":""}]},{"id":"s6-209","number":209,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة العدول إلى الموصول في قوله تعالى: ﴿للذين يتقون﴾؟","answer":"جعلت الصلة، وهي التقوى، علة استحقاق خير الآخرة وطريق الانتفاع به؛ فلا يناله من بلغ الآخرة بلا تقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525، تحت عنوان «العدول عن الاسم الصريح إلى الموصول وصلته»","url":""}]},{"id":"s6-1096","number":1096,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة المبالغة في قوله تعالى: ﴿وللدار الآخرة خير للذين يتقون﴾؟","answer":"نوهت بالمتقين لاختيارهم الباقي، وعرضت بالمشركين الذين آثروا متاع الدنيا مع وضوح تفاضل الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525–526، تحت عنوان «دلالة المبالغة على التعريض بالمشركين والتنويه بالمتقين»","url":""}]},{"id":"s6-1097","number":1097,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما الاحتباك في قوله تعالى: ﴿وللدار الآخرة خير للذين يتقون﴾؟","answer":"ذكر في الدنيا اللعب واللهو وحذف ما يقابله من الشر، وذكر في الآخرة الخير للمتقين وحذف ما يقابله من عذاب المكذبين؛ فدل المذكوران على المحذوفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525–526، تحت عنوان «دلالة أسلوب الاحتباك في قوله تعالى: ﴿وللدار الآخرة خير للذين يتقون﴾»","url":""}]},{"id":"s6-210","number":210,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما أثر التذييل في قوله تعالى: ﴿أفلا تعقلون﴾؟","answer":"لخص نتيجة الموازنة بين الفاني والباقي، وقرر أن اختيار الآخرة هو مقتضى العقل السليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص527، تحت عنوان «أثر أسلوب التذييل في الدلالة بقوله تعالى: ﴿أفلا تعقلون﴾»","url":""}]},{"id":"s6-1098","number":1098,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة اجتماع الالتفات والاستفهام في قوله تعالى: ﴿أفلا تعقلون﴾؟","answer":"نقل الخطاب إليهم وواجههم بالسؤال مباشرة بعد الحديث عنهم، فاشتد التنبيه وصاروا مسؤولين عن تعطيل عقولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص528، تحت عنوان «دلالة تضافر أسلوبي الالتفات والاستفهام»","url":""}]},{"id":"s6-1099","number":1099,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما غرض الاستفهام في قوله تعالى: ﴿أفلا تعقلون﴾؟","answer":"للتبكيت والتوبيخ؛ لأن تفضيل الباقي على الفاني تدركه العقول، فكان إعراضهم عنه موضع إنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص528–529، تحت عنوان «دلالة الاستفهام على التبكيت والتوبيخ في قوله تعالى: ﴿أفلا تعقلون﴾»","url":""}]},{"id":"s6-211","number":211,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما أثر ﴿قد﴾ في قوله تعالى: ﴿قد نعلم إنه ليحزنك الذي يقولون﴾؟","answer":"هي للتحقيق لا للتقليل، فأكدت إحاطة علم الله بحزن رسوله ﷺ وجاءت تسلية له بأن ألمه معلوم عند ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص532–533، تحت عنوان «أثر لفظ التحقيق ﴿قد﴾»","url":""}]},{"id":"s6-1100","number":1100,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة المضارع ﴿نعلم﴾ بعد ﴿قد﴾؟","answer":"دل على استمرار العلم وتجدده بحسب ما يتجدد من أقوالهم المؤذية، فكان في ذلك دوام العناية والتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص533–534، تحت عنوان «معنى الفعل المضارع ﴿نعلم﴾ بعد ﴿قد﴾»","url":""}]},{"id":"s6-212","number":212,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما الفرق بين قوله هنا: ﴿قد نعلم إنه ليحزنك الذي يقولون﴾، وقوله في يس: ﴿فلا يحزنك قولهم﴾؟","answer":"يعرض سياق الأنعام الحزن عرضًا مؤكدًا، ويستحضر بـ﴿الذي يقولون﴾ قبح أقوالهم وتجددها واستمرار أثرها؛ ثم يسلّي الرسول ﷺ بقوله: ﴿فإنهم لا يكذبونك﴾، والمقام يدل على: فلا تحزن. أما آية يس فصرحت بالنهي مباشرةً: ﴿فلا يحزنك قولهم﴾. فلكل صياغة موضعها في بيان الحزن ودفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص536–537، تحت «نكتة الفرق بين ﴿ليحزنك الذي يقولون﴾ و﴿فلا يحزنك قولهم﴾»","url":""}]},{"id":"s6-213","number":213,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما نكتة العدول إلى الموصول في قوله تعالى: ﴿ليحزنك الذي يقولون﴾؟","answer":"عم الموصول أقوالهم المؤذية وربط الحزن بعلته من غير إعادة ألفاظهم القبيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص535، تحت عنوان «نكتة العدول إلى الاسم الموصول في قوله تعالى: ﴿ليحزنك الذي يقولون﴾»","url":""}]},{"id":"s6-1101","number":1101,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة المضارع في قوله تعالى: ﴿الذي يقولون﴾؟","answer":"استحضر تجدد أقوالهم واستمرار صدورها، فناسب تجدد ما تحدثه من حزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص535–536، تحت عنوان «دلالة الفعل المضارع في قوله تعالى: ﴿الذي يقولون﴾»","url":""}]},{"id":"s6-1102","number":1102,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما فائدة عدم ذكر ما يقولون في قوله تعالى: ﴿الذي يقولون﴾؟","answer":"ترك المقول مطلقًا ليشمل كل صور التكذيب والسخرية والاتهام، وللإعراض عن حكاية ألفاظهم لشناعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص536، تحت عنوان «فائدة عدم ذكر ما يقولون»","url":""}]},{"id":"s6-214","number":214,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما أثر اختلاف القراءة في قوله تعالى: ﴿فإنهم لا يكذبونك﴾؟","answer":"على التشديد يكون المعنى أنهم لا يثبتون كذبك في أنفسهم، وعلى التخفيف أنهم لا يجدونك كاذبًا؛ وفي الوجهين يعرفون صدقه ويجحدون الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص539، تحت عنوان «توجيه المعنى باختلاف القراءة في قوله تعالى: ﴿فإنهم لا يكذبونك﴾»","url":""}]},{"id":"s6-1103","number":1103,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة الاستدراك في قوله تعالى: ﴿ولكن الظالمين بآيات الله يجحدون﴾؟","answer":"دفع توهم أن نفي تكذيب شخص الرسول ﷺ ينفي عنهم الجحود؛ فبين أن خصومتهم متجهة إلى آيات الله مكابرة وظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص539، تحت عنوان «الاستدراك لدفع التوهم في قوله تعالى: ﴿ولكن الظالمين بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-215","number":215,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة الانتقال من ضمير النبي ﷺ في ﴿يكذبونك﴾ إلى الاسم الظاهر في ﴿بآيات الله يجحدون﴾؟","answer":"أظهر اسم الله ليرفع القضية من أذى شخصي للرسول إلى جحود بحجج الله نفسه، فيشتد ذمهم وتتم تسلية النبي ﷺ. كما أن إضافة الآيات إلى الله تعظم ما واجهوه بالإنكار وتبين صاحب الحق الذي اعتدوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص540–541، تحت «بلاغة القصر بتقديم الجار والمجرور في قوله تعالى: ﴿بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-216","number":216,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة تقديم ﴿بآيات الله﴾ على ﴿يجحدون﴾؟","answer":"قدم الجار والمجرور للعناية بموضع جحودهم وللقصر بحسب السياق: ليس الذي ينالونه حقيقةً شخص الرسول ﷺ، وإنما تتجه مكابرتهم إلى آيات الله. وفي التقديم تعجيل بذكر الآيات المعظمة قبل تسجيل فعل الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص540–541، تحت «بلاغة القصر بتقديم الجار والمجرور في قوله تعالى: ﴿بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-217","number":217,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة الجحود في قوله تعالى: ﴿بآيات الله يجحدون﴾؟","answer":"الجحود إنكار الحق مع معرفته، فدل على أنهم تيقنوا الآيات ثم ردوها ظلمًا ومكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص541، تحت عنوان «دلالة الجحود بآيات الله في قوله تعالى: ﴿ولكن الظالمين بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-1104","number":1104,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما الفرق بين الجحد والإنكار؟","answer":"الإنكار أعم وقد يقع لعدم المعرفة، أما الجحد فهو إنكار ما عرفه صاحبه أو استيقنه؛ ولذلك كان أبلغ في ذمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص541–542، تحت عنوان «(الجحد) و(الإنكار)»","url":""}]},{"id":"s6-218","number":218,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة تنكير ﴿رسل﴾ في قوله تعالى: ﴿ولقد كذبت رسل من قبلك﴾؟","answer":"يفتح التنكير، مع وصف الرسل بأنهم من قبله، باب التسلية بسابقين كثيرين ذوي شأن عرفوا التكذيب والصبر عليه. فلا تختص هذه المحنة برسول واحد؛ وإنما هي سيرة متكررة يجد فيها النبي ﷺ القدوة والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص549–550، تحت «دلالة تعلق حرف ﴿من﴾ في قوله تعالى: ﴿ولقد كذبت رسل من قبلك﴾»","url":""}]},{"id":"s6-219","number":219,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة بناء ﴿كُذبت﴾ للمفعول؟","answer":"وجه العناية إلى ما وقع على الرسل من التكذيب لأنه موضع تسلية النبي ﷺ والقدوة في الصبر، أما المكذبون فتختلف أممهم ولا حاجة إلى تسميتهم. وفي حذف الفاعل تعميم لكل من سلك طريقهم في مقاومة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص548–549، تحت «أثر البناء للمفعول في توجيه المعنى»","url":""}]},{"id":"s6-220","number":220,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة تعدية الصبر بـ﴿على﴾ في قوله تعالى: ﴿فصبروا على ما كذبوا وأوذوا﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء والتمكن؛ فكأن التكذيب والأذى حمل ثقيل علاه الرسل وثبتوا فوقه فلم يغلبهم. والتعبير يرسم الصبر قوةً ومغالبةً لا مجرد انتظار سلبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص550–551، تحت «نكتة تعدية فعل الصبر بالحرف ﴿على﴾ في قوله تعالى: ﴿فصبروا على ما كذبوا﴾»","url":""}]},{"id":"s6-221","number":221,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة الجمع بين التكذيب والأذى مع أن التكذيب لون من الأذى؟","answer":"خُص التكذيب بالذكر لأنه أذى موجه إلى الرسالة والحق الذي جاء به الرسل، ثم عُطف عليه الأذى وهو أعم، فيشمل كل إساءة نالتهم وما كان أشد من مجرد التكذيب؛ فاجتمع الخاص والعام لإحاطة البلاء الذي صبروا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص550، تحت «دلالة عطف العام على الخاص في قوله تعالى: ﴿فصبروا على ما كذبوا وأوذوا﴾»","url":""}]},{"id":"s6-222","number":222,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة جعل مجيء النصر غايةً في قوله تعالى: ﴿حتى أتاهم نصرنا﴾؟","answer":"تفيد ﴿حتى﴾ استمرار صبرهم طوال زمن التكذيب والأذى إلى أن جاء النصر في وقته الذي قدره الله. فالنصر ثمرة موعودة للصبر، لكنه لا يعفي من احتمال الطريق حتى يبلغ أجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص552–553، تحت «ورود الحرف ﴿حتى﴾ مفيدًا الغاية»","url":""}]},{"id":"s6-223","number":223,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما سر استعمال مادة الإتيان مع النصر في قوله تعالى: ﴿حتى أتاهم نصرنا﴾؟","answer":"صور النصر كأنه قادم يبلغ الرسل في وقته المقدر، فزاد معنى تحقق الوعد ووصوله بعد الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص553، تحت عنوان «سر استعمال مادة الإتيان مع النصر»","url":""}]},{"id":"s6-1105","number":1105,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما المجاز في قوله تعالى: ﴿حتى أتاهم نصرنا﴾؟","answer":"شخص النصر بمعنى تحقق أسبابه وآثاره في صورة آتٍ يصل إليهم، فصار الوعد مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص553–554، تحت عنوان «دلالة المجاز في قوله تعالى: ﴿حتى أتاهم نصرنا﴾»","url":""}]},{"id":"s6-224","number":224,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة العطف في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾؟","answer":"عطف ضمانًا عامًا على خبر نصر الرسل؛ فنصرهم من كلمات الله التي لا يملك أحد تغييرها أو منع نفاذها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص554، تحت عنوان «دلالة العطف وأثره في المعنى»","url":""}]},{"id":"s6-1106","number":1106,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما الكناية في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾؟","answer":"كناية عن تحقق وعد الله وثبات سنته؛ فانتفاء من يبدل كلماته يقتضي نفاذها حتمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص554–555، تحت عنوان «دلالة الكناية في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾»","url":""}]},{"id":"s6-225","number":225,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة جمع ﴿كلمات الله﴾ في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾؟","answer":"الجمع يشمل ما تعدد من وعود الله وأحكامه وقضائه ووحيه، ومنها كلمته بنصر رسله؛ فلا يملك أحد تبديل شيء منها. وبهذا انتقل التثبيت من وعد واحد إلى قاعدة عامة تحمي كل ما أخبر الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص555، تحت «دلالة الكناية في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾».","url":""}]},{"id":"s6-226","number":226,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما أثر القسم و﴿قد﴾ في قوله تعالى: ﴿ولقد جاءك من نبإ المرسلين﴾؟","answer":"تضافرا في تأكيد تحقق وصول الخبر المسلي، فثبت للنبي ﷺ أن سنة الابتلاء والنصر ماضية في الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص557، تحت عنوان «تضافر القسم وحرف التحقيق في البيان والتأكيد»","url":""}]},{"id":"s6-1107","number":1107,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من نبإ المرسلين﴾؟","answer":"هي للتبعيض؛ أي جاءه من أخبار الرسل القدر الذي يحقق العبرة والتثبيت، لا استقصاء جميع أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص557–558، تحت عنوان «دلالة ﴿من﴾ على أن الإنسان لا يؤتى من العلم إلا بعضه»","url":""}]},{"id":"s6-1108","number":1108,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما الغرض من استعمال مادة النبأ في قوله تعالى: ﴿من نبإ المرسلين﴾؟","answer":"النبأ خبر عظيم له شأن وفائدة وعاقبة، فناسب أخبار الرسل بما فيها من تثبيت ووعد بالنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص558، تحت عنوان «الغرض من استعمال مادة النبأ»","url":""}]},{"id":"s6-227","number":227,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما المجاز في قوله تعالى: ﴿كبر عليك إعراضهم﴾؟","answer":"صور شدة الإعراض وألمه بأمر عظيم ثقيل على الرسول ﷺ، فدل على مبلغ حرصه على هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص564، تحت عنوان «دلالة المجاز المرسل في قوله تعالى: ﴿كبر عليك إعراضهم﴾»","url":""}]},{"id":"s6-1109","number":1109,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما نكتة تعدية ﴿كبر﴾ بـ﴿على﴾ في قوله تعالى: ﴿كبر عليك إعراضهم﴾؟","answer":"أفادت استعلاء ثقل الإعراض عليه وتمكن مشقته منه، فكأنه حمل واقع فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص564–565، تحت عنوان «نكتة تعدية الفعل (كبر) بأداة الاستعلاء (على) في الآية الكريمة»","url":""}]},{"id":"s6-228","number":228,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما بلاغة المقابلة بين ﴿في الأرض﴾ و﴿في السماء﴾؟","answer":"جمعت طرفي المكان: أقصى النزول وأقصى الصعود، لتستوعب كل سبيل متوهم في طلب آية توافق اقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص568، تحت عنوان «بلاغة المقابلة بين قوله تعالى: ﴿في الأرض﴾ وقوله: ﴿في السماء﴾»","url":""}]},{"id":"s6-1110","number":1110,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"كيف حصرت جملة الشرط مهمة النبوة في البلاغ لا الإكراه؟","answer":"علقت الإتيان بآية مقترحة على أمر متعذر، فبينت أن حرص الرسول ﷺ لا يحول الرسالة إلى إكراه للناس على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص568–569، تحت عنوان «دور جملة الشرط في حصر مهمة النبوة في البلاغ لا في الإكراه»","url":""}]},{"id":"s6-229","number":229,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"لم قيل: ﴿أن تبتغي نفقًا﴾ بدل أن تتخذ نفقًا؟","answer":"الابتغاء يصور شدة الطلب والسعي إلى الآية، أما اتخاذ النفق فيوحي بتحقق الوسيلة. فالتعبير يلائم فرض أمر لا يستطيع الرسول ﷺ تحصيله، ويبين مبلغ حرصه على إيمانهم مع أن الإتيان بما يقترحونه لا يضمن هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص569، تحت «دلالة إيثار (الابتغاء) على (الاتخاذ) في قوله تعالى: ﴿أن تبتغي نفقًا في الأرض﴾»","url":""}]},{"id":"s6-230","number":230,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة الجار والمجرور في قوله تعالى: ﴿فتأتيهم بآية﴾؟","answer":"صورت الباء مصاحبة الرسول ﷺ للآية المقترحة عند الإتيان بها، مع أن ظهورها لا يكون إلا بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص570، تحت عنوان «دلالة الجار والمجرور في قوله تعالى: ﴿فتأتيهم بآية﴾»","url":""}]},{"id":"s6-1111","number":1111,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة الفاء في قوله تعالى: ﴿فتأتيهم بآية﴾؟","answer":"رتبت الإتيان بالآية على استطاعة اتخاذ النفق أو السلم، فزاد الشرط إحكام تصوير تعذر ما طلبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص570–571، تحت عنوان «دلالة الفاء في ﴿فتأتيهم﴾»","url":""}]},{"id":"s6-1112","number":1112,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة تنوين ﴿آية﴾ في قوله تعالى: ﴿فتأتيهم بآية﴾؟","answer":"للتفخيم؛ أي آية عظيمة من جنس ما اقترحوه تعنتًا، لا نفي كون القرآن آية قائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص571، تحت عنوان «دلالة تنوين لفظ ﴿بآية﴾»","url":""}]},{"id":"s6-231","number":231,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة قوله تعالى: ﴿ولو شاء الله لجمعهم على الهدى﴾، دون: لهداهم؟","answer":"﴿لجمعهم على الهدى﴾ بمعنى: لهداهم أجمعين، وعدل إلى هذا التركيب للإيماء إلى أنه لو شاء لجمع من بقي من المشركين مع المؤمنين على ما هدى إليه المؤمنين؛ غير أن هذا الجمع، وإن لم يعجز المشيئة، مخالف لسنة الله في خلقه القائمة على الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص571–572، تحت «مخالفة تركيبية في التعبير عن الهدى بقوله تعالى: ﴿لجمعهم على الهدى﴾».","url":""}]},{"id":"s6-232","number":232,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة العدول عن الأمر بالعلم إلى قوله تعالى: ﴿فلا تكونن من الجاهلين﴾؟","answer":"جاء النهي أبلغ في التثبيت والتحذير من أن يحمل الحزن على طلب ما لا تقتضيه حكمة الله، مع تنزيه النبي ﷺ عن الجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص572–573، تحت عنوان «دلالة العدول عن الأمر بالعلم إلى قوله تعالى: ﴿فلا تكونن من الجاهلين﴾»","url":""}]},{"id":"s6-1113","number":1113,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما المراد بالجاهلين في قوله تعالى: ﴿فلا تكونن من الجاهلين﴾؟","answer":"هم الذين يجهلون سنة الله في الهداية والاختيار، فالخطاب تثبيت للنبي ﷺ وتعليم للأمة حدود مهمة الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص574–575، تحت عنوان «بيان المراد بلفظ الجاهلين في سياق الآية الكريمة»","url":""}]},{"id":"s6-1114","number":1114,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"لماذا قيل: ﴿من الجاهلين﴾ دون «جاهلًا»؟","answer":"نهاه عن أدنى ملابسة لطريق جماعة الجاهلين، فكان أبلغ من مجرد نفي وصف مفرد عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص575، تحت عنوان «سر العدول عن: فلا تكن جاهلًا، إلى: ﴿فلا تكونن من الجاهلين﴾»","url":""}]},{"id":"s6-233","number":233,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما الفرق بين ﴿فلا تكونن﴾ و«فلا تكن» و«أن تكون»؟","answer":"﴿فلا تكونن﴾ نهي مؤكد مباشر، و«فلا تكن» نهي بلا توكيد، و«أن تكون» مصدر مؤول لا يحمل قوة المواجهة والردع نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص573–574، تحت عنوان «توجيه الفرق بين قوله تعالى: ﴿فلا تكونن﴾ و﴿فلا تكن﴾ و﴿أن تكون﴾»","url":""}]},{"id":"s6-1115","number":1115,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما الغرض من توكيد النهي في قوله تعالى: ﴿فلا تكونن من الجاهلين﴾؟","answer":"شدد التثبيت ليتناسب مع شدة حرص النبي ﷺ على هدايتهم، ويقطع طريق الاسترسال مع الحزن من غير أن يدل على وقوع الجهل منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص574، تحت عنوان «بيان الغرض من توكيد النهي في قوله تعالى: ﴿فلا تكونن من الجاهلين﴾»","url":""}]},{"id":"s6-234","number":234,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة ﴿يسمعون﴾ في قوله تعالى: ﴿إنما يستجيب الذين يسمعون﴾؟","answer":"المراد سماع القبول والتدبر الذي ينفذ إلى القلب ويثمر استجابة، لا مجرد وصول الصوت إلى الأذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص584، تحت عنوان «دلالة لفظ ﴿يسمعون﴾ وأثرها في السياق»","url":""}]},{"id":"s6-1116","number":1116,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"لماذا عُبر بالسماع دون الإيمان في قوله تعالى: ﴿الذين يسمعون﴾؟","answer":"جعل السماع الواعي أول طريق الاستجابة، وعرض بالمكذبين الذين يسمعون الألفاظ ولا يفتحون لها قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص584–585، تحت عنوان «نكتة التعبير بالسماع ﴿الذين يسمعون﴾ دون الإيمان في الآية»","url":""}]},{"id":"s6-235","number":235,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"لماذا أوثر ﴿يستجيب﴾ على مرادفاته؟","answer":"الاستجابة تتضمن قبول الداعي والإقبال إلى مقتضى دعوته وامتثاله، فهي أوسع من مجرد الإجابة أو التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص583، تحت عنوان «نكتة إيثار لفظ ﴿يستجيب﴾ على مرادفاته»","url":""}]},{"id":"s6-1117","number":1117,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما معنى السين والتاء في قوله تعالى: ﴿يستجيب﴾؟","answer":"السين والتاء زائدتان لإفادة التأكيد، فالاستجابة أخص من الإجابة؛ لأنها قبول الدعوة مع الإقبال والطاعة، ولذلك ناسبت من يسمع سماع فهم ثم يمتثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص583، تحت عنوان «معنى السين والتاء في ﴿يستجيب﴾»","url":""}]},{"id":"s6-236","number":236,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة المضارع في قوله تعالى: ﴿يستجيب﴾؟","answer":"يصور الاستجابة فعلًا متجددًا كلما سمع أصحاب القلوب الحية آيةً أو دعوةً إلى الحق، فهي صفة مستمرة لا واقعة ماضية منقطعة. كما يستحضر أثر السماع أمام القارئ في الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص584، تحت «فائدة التعبير بصيغة المضارع ﴿يستجيب﴾»","url":""}]},{"id":"s6-237","number":237,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة مقابلة الذين يسمعون بـ﴿الموتى﴾ مع أن الحديث عن مكذبين أحياء؟","answer":"شبّه المكذبين بالموتى لأنهم فقدوا أثر الحياة المعنوية: يسمعون الصوت ولا يملكون استجابة القلب، كما لا يجيب الميت نداءً. وحُذفت أداة التشبيه حتى صار موت القلب كأنه حقيقتهم، فاشتدت المفارقة بينهم وبين السامعين المستجيبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص586–587، تحت «بلاغة الاستعارة التصريحية في قوله: ﴿والموتى﴾»","url":""}]},{"id":"s6-238","number":238,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة المضارع في قوله تعالى: ﴿والموتى يبعثهم الله﴾، دون: سيبعثهم؟","answer":"المضارع يقرر البعث بوصفه فعلًا داخلًا في قدرة الله وسنته المقطوع بها، ويستحضره كأنه مشاهد، فلا يحتاج إلى السين التي قد تبقيه بعيدًا في تصور السامع. وهو يشمل بعث الموتى حقيقةً، مع التلويح بأن إحياء القلوب المغلقة ليس بيد الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص588، تحت «نكتة اختيار صيغة ﴿يبعثهم﴾ دون (سيبعثهم)».","url":""}]},{"id":"s6-239","number":239,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿يبعثهم الله﴾؟","answer":"إسناد البعث إلى اسم الله يقرر أن إحياء الموتى بقدرته وحده، ويثبت حقيقة البعث التي ينكرونها، وفيه تهديد ووعيد. وعلى تفسير البعث بهداية موتى القلوب، يعيد أمر هدايتهم إليه؛ ففي ذكره تعظيم للقدرة وترغيب في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص588، تحت «بلاغة إسناد فعل ﴿يبعثهم﴾ إلى لفظ الجلالة»","url":""}]},{"id":"s6-240","number":240,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما وجه القصر في قوله تعالى: ﴿ثم إليه يرجعون﴾؟","answer":"تقديم ﴿إليه﴾ قصر المرجع والحساب على الله وحده، فلا رجوع إلى من عبدوهم ولا ملجأ سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص587، تحت عنوان «وجه القصر والحصر المستفاد في جملة ﴿ثم إليه يرجعون﴾»","url":""}]},{"id":"s6-1118","number":1118,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم إليه يرجعون﴾؟","answer":"أفادت التراخي بين بعثهم وانتهاء أمرهم إلى موقف الجزاء، مع تهويل ما يعقب البعث من رجوع وحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص587–588، تحت عنوان «معنى حرف التراخي ﴿ثم﴾ ودلالته في السياق»","url":""}]},{"id":"s6-241","number":241,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة إفراد ﴿آية﴾ مع إرادة جنس الآيات في قولهم: ﴿لولا نزل عليه آية﴾؟","answer":"أفردت لأن المراد آية واحدة من الجنس الذي يقترحونه تعنتًا، مع قيام القرآن وغيره من الدلائل بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص593، تحت عنوان «دلالة إفراد لفظ ﴿آية﴾ وإرادة الجمع»","url":""}]},{"id":"s6-1119","number":1119,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة ﴿لولا﴾ في قولهم: ﴿لولا نزل عليه آية من ربه﴾؟","answer":"للتحضيض؛ حكت إلحاحهم على إنزال آية حسية مقترحة، وفيه تعريض منهم بأن الحجة القائمة لا تكفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص593–594، تحت عنوان «دلالة ﴿لولا﴾ على التحضيض في قوله تعالى: ﴿لولا نزل عليه آية من ربه﴾»","url":""}]},{"id":"s6-242","number":242,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة صيغة ﴿نُزّل﴾ المشددة في حكاية طلبهم؟","answer":"تشديد ﴿نُزّل﴾ يشير إلى تكرر نزول آيات القرآن عليهم؛ وفيه كشف لتناقضهم، إذ يطلبون آية واحدة قاهرة كأن شيئًا لم ينزل، مع أن القرآن كان يتنزل عليهم آيةً بعد آية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص594–595، تحت «نكتة إيثار صيغة (نُزّل) على (أُنزل)».","url":""}]},{"id":"s6-243","number":243,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"لماذا آثروا عنوان الربوبية في قولهم: ﴿من ربه﴾؟","answer":"لأنهم كانوا يقرون بربوبية الله مع جحود استحقاقه للعبادة، فجاء اقتراحهم في صورة امتحان لما يدعيه الرسول ﷺ من رسالة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص596، تحت عنوان «إيثار عنوان الربوبية على الألوهية ﴿من ربه﴾»","url":""}]},{"id":"s6-1120","number":1120,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة إضافة ﴿رب﴾ إلى ضمير النبي في قولهم: ﴿من ربه﴾؟","answer":"في الإضافة تعريض وتهكم؛ أي إن كان له رب يرسله فليأت منه بآية توافق اقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص596–597، تحت عنوان «دلالة إضافة (رب) إلى ضمير النبي ﴿ربه﴾»","url":""}]},{"id":"s6-1121","number":1121,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة العدول من قولهم ﴿من ربه﴾ إلى الجواب باسم الجلالة: ﴿قل إن الله قادر﴾؟","answer":"رد تعريضهم بالاسم الجامع لصفات الألوهية، وقرر أن القادر على إنزال الآيات هو الله المعبود بحق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص598، تحت عنوان «دلالة العدول من لفظ ﴿ربي﴾ إلى اسم الجلالة ﴿الله﴾»","url":""}]},{"id":"s6-244","number":244,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما غرض توكيد قوله تعالى: ﴿إن الله قادر﴾؟","answer":"أزال توهم أن عدم إنزال الآية المقترحة ناشئ عن عجز، وأثبت أن الترك جار على الحكمة والمشيئة مع تمام القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص597–598، تحت عنوان «غرض توكيد جملة مقول القول ﴿إن الله قادر﴾»","url":""}]},{"id":"s6-245","number":245,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما سر استعمال حرف الاستعلاء ﴿على﴾ في قوله تعالى: ﴿قادر على أن ينزل آية﴾؟","answer":"أفادت تمكن القدرة من متعلقها واستعلاءها عليه، فأكدت أن عدم إنزال الآية المقترحة ليس عجزًا بل تابع للحكمة والمشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص598، تحت عنوان «سر استعمال حرف الاستعلاء ﴿على﴾»","url":""}]},{"id":"s6-246","number":246,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما غرض عطف جملة الاستدراك في قوله تعالى: ﴿ولكن أكثرهم لا يعلمون﴾؟","answer":"بين بعد إثبات القدرة أن أكثرهم يجهلون حكمة عدم إنزال الآية القاهرة وخطر التكذيب بها، فليس تركها عجزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص599، تحت عنوان «غرض عطف جملة الاستدراك على مقول القول»","url":""}]},{"id":"s6-1122","number":1122,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"لماذا نُفي عنهم العلم دون الإيمان في قوله تعالى: ﴿لا يعلمون﴾؟","answer":"لأن موطن الخلل هنا جهلهم بسنة الله وحكمته وعاقبة اقتراح الآيات؛ فنفي العلم يكشف أصل شبهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص599–600، تحت عنوان «نكتة نفي العلم دون الإيمان ﴿لا يعلمون﴾»","url":""}]},{"id":"s6-247","number":247,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة قوله تعالى: ﴿أكثرهم﴾، دون: كلهم؟","answer":"أثبت أن الجهل غالب في أصحاب الاقتراح، لكنه لم يسو بينهم جميعًا؛ ففيهم من يعلم وجه الحق ثم يكابر، أو من يمكن أن يهتدي. وهذه الدقة تمنع التعميم وتبين تفاوتهم في دوافع العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص600، تحت «دلالة التعبير بلفظ (أكثر) في السياق»","url":""}]},{"id":"s6-248","number":248,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة اجتماع النفي و﴿من﴾ في قوله تعالى: ﴿وما من دابة في الأرض﴾؟","answer":"دخول ﴿من﴾ على النكرة في سياق النفي يفيد استغراق الجنس فردًا فردًا؛ فلا تخرج دابة واحدة من الحكم الآتي. فالصيغة أبلغ من ﴿وما دابة﴾ في تأكيد شمول علم الله وتدبيره لكل حي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص607، تحت «دلالة ﴿من﴾ في قوله تعالى: ﴿وما من دابة﴾».","url":""}]},{"id":"s6-249","number":249,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة تقييد الدابة بـ﴿في الأرض﴾ ووصف الطائر بأنه ﴿يطير﴾؟","answer":"خص كل صنف بحركته وحيزه المشاهد: الدابة تدب في الأرض، والطائر يتحرك في الجو. وفي الكلام احتباك؛ كأن التقدير: دابة تدب في الأرض، وطائر يطير في السماء، فحذف من كل جملة ما دل عليه مقابلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص609–610، تحت «بلاغة الاحتباك بين جملتي ﴿دابة في الأرض﴾ و﴿طائر يطير بجناحيه﴾»","url":""}]},{"id":"s6-250","number":250,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"لماذا قيل: ﴿ولا طائر يطير﴾ بصيغة اسم الفاعل، ولم يقل: «ولا طير»؟","answer":"اسم الفاعل ﴿طائر﴾ يصور الطير حال مباشرته الطيران، فيقصر النظر على الحيوان المتصف بهذه الهيئة فعلًا، بخلاف لفظ «طير» الأعم في اسم الجنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص609، تحت عنوان «نكتة التعبير بصيغة اسم الفاعل ﴿طائر﴾ دون (طير)»","url":""}]},{"id":"s6-1123","number":1123,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما فائدة تأكيد الطيران بقوله تعالى: ﴿يطير بجناحيه﴾؟","answer":"أكد حقيقة الطيران واستحضر هيئته المشاهدة، ودفع احتمال المجاز أو إطلاق الطائر على ما لا يطير بالفعل؛ فدل على الإحاطة بكل ما يطير على اختلاف أنواعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص610، تحت عنوان «نكتة تأكيد الطيران، بقوله ﴿يطير بجناحيه﴾»","url":""}]},{"id":"s6-251","number":251,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة تقييد الطيران بقوله تعالى: ﴿بجناحيه﴾؟","answer":"في الباء وجهان: أن تكون للاستعانة، أي يطير مستعينًا بجناحيه، أو للحال المؤكدة، أي يطير حال كونه ذا جناحين؛ والقيد يرفع توهم المجاز لأن الطيران قد يستعار للسرعة، ويعين هيئة الطيران الحسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص610–611، تحت «معنى (الباء) في قوله تعالى: ﴿بجناحيه﴾»","url":""}]},{"id":"s6-252","number":252,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"لماذا نُفي وجود الدواب بـ﴿ما﴾ في قوله: ﴿وما من دابة﴾، ونُفي الطير بـ﴿لا﴾ في قوله: ﴿ولا طائر﴾؟","answer":"ناسبت ﴿ما﴾ دخول ﴿من﴾ على النكرة لتوكيد استغراق جنس الدواب، أما ﴿لا﴾ فأكدت نفي خروج طائر متصف بالطيران بجناحيه من الحكم؛ فاختار كل تركيب ما يلائم بناؤه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص609، تحت عنوان «سر الاختلاف بين النفي بـ(ما)، والنفي بـ(لا)»","url":""}]},{"id":"s6-253","number":253,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما التعريض في وصف الدواب والطير بأنهم ﴿أمم أمثالكم﴾؟","answer":"يعرض بالإنسان الذي ميز بالعقل ثم لم يعتبر؛ فهذه المخلوقات جماعات يجري عليها تدبير الله، وفي مساواتها له في الخضوع والتنظيم تذكير له بألا يخرج عن طاعة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص611–612، تحت عنوان «بلاغة التعريض، في قوله تعالى: ﴿أمم أمثالكم﴾»","url":""}]},{"id":"s6-1124","number":1124,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"في أي وجه شُبهت الدواب والطير بالناس في قوله تعالى: ﴿أمم أمثالكم﴾؟","answer":"المماثلة في كونها أجناسًا وجماعات لها نظم وآجال وأرزاق وأحوال يحيط الله بها ويدبرها، لا في جميع الصفات ولا في نوع التكليف الذي خُص به الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص612، تحت عنوان «دلالة التشبيه، في قوله تعالى: ﴿أمم أمثالكم﴾»","url":""}]},{"id":"s6-254","number":254,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"لماذا جاء الخبر جمعًا في قوله تعالى: ﴿إلا أمم أمثالكم﴾؟","answer":"لأن النكرتين ﴿دابة﴾ و﴿طائر﴾ في سياق النفي تستغرقان الأفراد والأنواع، فجاء جمع ﴿أمم﴾ مراعيًا هذا المعنى العام؛ فكل نوع أمة لها خصائصها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص611، تحت عنوان «دلالة التعبير بصيغة الجمع ﴿أمم﴾، دون الإفراد»","url":""}]},{"id":"s6-255","number":255,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة قوله تعالى: ﴿ما فرطنا في الكتاب من شيء﴾، وما المراد بالكتاب؟","answer":"المعنى أن الكتاب لم يهمل شيئًا داخلًا في الغرض المقصود. والمراد به على قولٍ اللوح المحفوظ المشتمل على أحوال المخلوقات، وعلى قولٍ القرآن، أي إنه بيّن ما يحتاج إليه المكلف في الدين وأصول الهداية، لا أنه فصل جميع العلوم؛ وعلى القولين يفيد لفظ الكتاب توثيق المكتوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص613–614، تحت «دلالة التعبير بالكتاب عن اللوح المحفوظ أو القرآن»","url":""}]},{"id":"s6-256","number":256,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة اختيار ﴿فرطنا﴾، دون: تركنا أو أغفلنا؟","answer":"التفريط تقصير يجاوز به الشيء قدر العناية الواجبة حتى يضيع ويفوت؛ فنفيه أبلغ من نفي مجرد الترك، لأنه ينزه الكتابة الإلهية عن النقص والإهمال والتضييع جميعًا. وقد فسره المصدر هنا بمعنى: ما أغفلنا ولا ضيعنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص613، تحت «دلالة استعمال لفظ (فرط) دون ما يقاربها في الدلالة»","url":""}]},{"id":"s6-257","number":257,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة قوله تعالى: ﴿من شيء﴾ بعد نفي التفريط؟","answer":"﴿من﴾ زائدة لتوكيد الاستغراق، و﴿شيء﴾ أعم النكرات؛ فاجتمعا بعد النفي لنفي أدنى فرد يمكن أن يتوهم خروجه من الكتاب. وبذلك يبلغ النص غاية الشمول من غير أن تكون العبارة حشوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص612–613، تحت «سر النفي بـ(ما) ودخول ﴿من﴾ على ﴿شيء﴾»","url":""}]},{"id":"s6-258","number":258,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما مناسبة ختم ذكر الحيوان بقوله تعالى: ﴿ثم إلى ربهم يحشرون﴾؟","answer":"أكمل به المماثلة في الخضوع للتدبير: كما كُتبت أحوالها في الدنيا فإنها تجمع إلى ربها، ويقتص لبعضها من بعض، ثم يصير أمرها إلى ما يشاء الله. والخاتمة دليل آخر على عموم القدرة، ورد على من أنكر حشر البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص616، تحت «سر استعمال لفظ (الحشر) دون (الرجوع)»","url":""}]},{"id":"s6-259","number":259,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة إضافة الرب إلى الحيوان في قوله تعالى: ﴿إلى ربهم﴾؟","answer":"أثبت أن الله رب هذه الأمم أيضًا: خلقها ورزقها ودبر أنواعها وأحوالها، فلا يخرج الحيوان عن رعايته وحكمه. والإضافة تمهد لحشرها إليه؛ فالذي رباها في الدنيا هو الذي يتولى أمرها في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص615، تحت «دلالة إيثار عنوان الربوبية على الألوهية في قوله تعالى: ﴿إلى ربهم﴾»","url":""}]},{"id":"s6-260","number":260,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة تصوير المكذبين بأنهم ﴿صم وبكم﴾ مع سلامة أسماعهم وألسنتهم؟","answer":"لما عطلوا السمع عن قبول الآيات واللسان عن النطق بالحق نُزلوا منزلة من فقد الحاستين حقيقةً. فالصمم والبكم استعارتان لموت الاستجابة، لا وصفان لخلقة أجسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص627–628، تحت «وجه حمل الوصفين ﴿صم وبكم﴾ على الاستعارة»","url":""}]},{"id":"s6-261","number":261,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة حذف أداة التشبيه في وصفهم بـ﴿صم وبكم﴾؟","answer":"حذف الأداة والوجه فجاء التشبيه بليغًا، حتى كأنهم هم الصم والبكم لا مجرد مشابهين لهم؛ وذلك لشدة تعطيلهم أدوات الاهتداء. فالصيغة أثبتت الوصف فيهم وأقوت التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص627، تحت «بلاغة التشبيه في قوله تعالى: ﴿صم وبكم﴾»","url":""}]},{"id":"s6-262","number":262,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما سرّ جمع ﴿الظلمات﴾ في قوله تعالى: ﴿في الظلمات﴾؟","answer":"جُمعت ﴿الظلمات﴾ للمبالغة في وصفهم بالعمى، ولمناسبة جمع الآيات التي كذبوا بها، وللدلالة على تعدد الظلمات التي غرقوا فيها: ظلمات الكفر والجهل والعناد، والظلمات النفسية والروحية والفكرية؛ فهي ظلمات ظاهرة وباطنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص626–627، تحت «نكتة جمع الظلمات في قوله تعالى: ﴿في الظلمات﴾»","url":""}]},{"id":"s6-263","number":263,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"لماذا عُدل عن وصف المكذبين بالعمى إلى قوله تعالى: ﴿في الظلمات﴾؟","answer":"لأن الظلمات تصور البيئة التي تحيط بهم وتحجب عنهم طريق الهدى، وهي أبلغ من مجرد وصف العين بالعمى؛ إذ تجمع ظلمات الكفر والجهل والعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص625–626، تحت عنوان «نكتة العدول عن وصف العمى إلى: ﴿الظلمات﴾»","url":""}]},{"id":"s6-1125","number":1125,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة حرف الظرفية في قوله تعالى: ﴿في الظلمات﴾؟","answer":"صورهم منغمسين داخل الظلمات محاطين بها من كل جانب، حتى لا يجدوا منفذًا يبصرون منه الحق أو طريقًا يخرجون به من الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص626، تحت عنوان «دلالة حرف الظرفية في قوله تعالى: ﴿في الظلمات﴾»","url":""}]},{"id":"s6-264","number":264,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة اختلاف التعبير بين ﴿يضلله﴾ و﴿يجعله على صراط مستقيم﴾؟","answer":"عُدل عن أن يقال في المقابل: يهده، إلى ﴿يجعله على صراط مستقيم﴾؛ لأن هذا التركيب أرسخ في بيان الهداية، وفيه مزيد مدح للمهتدين وتصوير لتمكينهم واستقرارهم على الطريق، بخلاف التعبير الموجز عن أهل الضلال بـ﴿يضلله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص629–630، تحت «براعة اختلاف التعبير في التقابل اللفظي»","url":""}]},{"id":"s6-265","number":265,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"لماذا قيل: ﴿يجعله على صراط مستقيم﴾ ولم يقل: «يهده»؟","answer":"الجعل يصور نقل الضال إلى حال جديدة مستقرة، كأنه وُضع على الطريق الواضح بعد التخبط في الظلمات؛ فيبرز أثر الهداية وتمكنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص629، تحت عنوان «دلالة اختيار لفظ ﴿يجعله﴾، دون (يهده)»","url":""}]},{"id":"s6-1126","number":1126,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿على صراط مستقيم﴾؟","answer":"يفيد تمكن المهتدي من طريق الهدى وثباته عليه، ويصور الصراط سبيلًا بينًا يستعلي عليه السائر ويمضي فيه على بصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص630، تحت عنوان «بلاغة استعمال حرف الاستعلاء»","url":""}]},{"id":"s6-266","number":266,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ماذا يضيف وصف ﴿مستقيم﴾ إلى الصراط في قوله: ﴿يجعله على صراط مستقيم﴾؟","answer":"ينفي عنه العوج والانحراف، فيطمئن السائر إلى وضوح وجهته وسلامة مسلكه. واستقامة الطريق تقرب الوصول إلى المقصود؛ فالوصف يصور الهداية طريقًا واضحًا لا يضل سالكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص631، تحت «دلالة وصف ﴿صراط﴾ بلفظ ﴿مستقيم﴾»","url":""}]},{"id":"s6-267","number":267,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"لم حذف مفعول المشيئة في قوله تعالى: ﴿من يشأ الله يضلله﴾؟","answer":"دل جواب الشرط على المحذوف، والتقدير: من يشأ الله إضلاله يضلله. وفي الحذف إيجاز، ومعه إبهام يعقبه بيان في الجواب، فيبعث السامع على التفكر ويشد انتباهه إلى ما تعلقت به المشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص629، تحت «نكتة حذف مفعول المشيئة في ﴿من يشأ الله يضلله﴾»","url":""}]},{"id":"s6-268","number":268,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"كيف يجعل تركيب ﴿قل أرأيتكم﴾ السؤال عن العذاب مواجهة حاضرة في نفوس المخاطبين؟","answer":"هو أسلوب يلفت المخاطب إلى أمر جدير بالتحقيق والتأمل، ويستحضر الحالة كأنها مرئية أمامه. فالسؤال يحملهم على تصور أنفسهم وقد نزل بهم العذاب، ثم يطلب منهم جوابًا تعرفه فطرتهم: من يدعون عندئذ؟","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص635–636، تحت «بلاغة تركيب ﴿أرأيتكم﴾»","url":""}]},{"id":"s6-269","number":269,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"لماذا عُرّف العذاب في قوله تعالى: ﴿عذاب الله﴾ بالإضافة؟","answer":"إضافته إلى اسم الجلالة تعظم شأنه وتهول أثره؛ فهو عذاب صادر عمن لا تعجزه قوة ولا يستطيع أحد دفع ما يرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص637، تحت عنوان «فائدة تعريف ﴿عذاب الله﴾، بالإضافة دون (أل)»","url":""}]},{"id":"s6-1127","number":1127,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما المجاز في قوله تعالى: ﴿إن أتاكم عذاب الله﴾؟","answer":"استعير الإتيان لحصول العذاب ووصوله إليهم، فصُور كقادم يقصدهم حتى يواجهوه ولا يجدوا مهربًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص637، تحت عنوان «بلاغة المجاز في لفظ ﴿أتاكم﴾»","url":""}]},{"id":"s6-270","number":270,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما دلالة اختلاف الفعل بين ﴿أتاكم عذاب الله﴾ و﴿أتتكم الساعة﴾؟","answer":"أُعيد فعل الإتيان مع الساعة، مع إمكان عطفها على العامل الأول، لإظهار كل واحد من العذاب والساعة مستقلاً والاهتمام باستحضاره في النفس؛ وجاء كل فعل مطابقًا لفاعله، من غير فرق بينهما في تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص638–639، تحت «نكتة تكرير ﴿أتتكم﴾ دون الاكتفاء بإتيان العذاب»","url":""}]},{"id":"s6-271","number":271,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما دلالة العطف بـ﴿أو﴾ بين عذاب الله والساعة؟","answer":"جعلت كل حالة مستقلة كافية لاختبار فطرتهم: سواء نزل بهم عذاب عاجل أم فاجأتهم الساعة، فلن يجدوا من يدعونه حقًا إلا الله. فلا يلزم اجتماع الأمرين لتقوم الحجة على بطلان الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص638، تحت «معنى حرف ﴿أو﴾ في الآية الكريمة»","url":""}]},{"id":"s6-272","number":272,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما دلالة تقديم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله تدعون﴾؟","answer":"قدم المفعول للإنكار والقصر: أإلهًا غير الله تخصون بالدعاء عند انكشاف الضر؟ وتجربتهم نفسها تجيب بالنفي، لأن الشدة تسقط المعبودات المصطنعة وترد القلب إلى الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص639–640، تحت «سر تقديم ﴿أغير الله﴾ على فعل ﴿تدعون﴾»","url":""}]},{"id":"s6-273","number":273,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما موقع قوله تعالى: ﴿إن كنتم صادقين﴾ مما قبله؟","answer":"جاء قيدًا يتحدى دعواهم أن آلهتهم شركاء ينفعون؛ فإن صدقوا فليدعُوها عند نزول العذاب أو قيام الساعة، والتجربة الفطرية تكشف أنهم لا يفعلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص640، تحت عنوان «موقع جملة ﴿إن كنتم صادقين﴾ مما قبلها»","url":""}]},{"id":"s6-1128","number":1128,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"لماذا حُذف جواب الشرط في قوله تعالى: ﴿إن كنتم صادقين﴾؟","answer":"دل عليه الاستفهام السابق، أي فادعوا غير الله أو أخبروا أغير الله تدعون؛ وحذفه يوجز الكلام ويتركهم أمام الجواب الذي تلزمهم به فطرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص641، تحت عنوان «حذف جواب جملة ﴿إن كنتم صادقين﴾»","url":""}]},{"id":"s6-274","number":274,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة تولي الجواب في قوله تعالى: ﴿بل إياه تدعون﴾؟","answer":"أجاب عنهم لأن واقع الفطرة لا يسعهم إنكاره: عند الشدة يتركون الشركاء ويدعون الله. و﴿بل﴾ تبطل احتمال دعاء غيره الذي طرحه السؤال، ثم تثبت الحقيقة التي لا يملكون جوابًا سواها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص644، تحت «سر الإضراب بالحرف ﴿بل﴾ عن السؤال بالجواب عنه»","url":""}]},{"id":"s6-275","number":275,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة تقديم ﴿إياه﴾ في قوله تعالى: ﴿بل إياه تدعون﴾؟","answer":"تقديم المفعول يفيد القصر الحقيقي: لا تدعون عند نزول الشدة إلا الله؛ فتتجه القلوب إلى القوة الخالقة المنجية وتغيب المعبودات المزعومة. فالتقديم يواجه الشرك بشهادة فطرتهم العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص644، تحت «فائدة تقديم المفعول ﴿إياه﴾ على الفعل ﴿تدعون﴾»","url":""}]},{"id":"s6-276","number":276,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة الفاء في قوله تعالى: ﴿فيكشف ما تدعون إليه﴾؟","answer":"رتبت كشف الضر على دعاء الله وحده، فصورت سرعة الإجابة حين تتعلق بها المشيئة، وأظهرت أن رجوعهم إليه هو السبب الظاهر في الانفراج.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص645، تحت عنوان «دلالة العطف بحرف الفاء في ﴿فيكشف﴾»","url":""}]},{"id":"s6-1129","number":1129,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"لماذا عُبر عن إزالة الضر بالكشف في قوله تعالى: ﴿فيكشف ما تدعون إليه﴾؟","answer":"الكشف إزالة غطاء ساتر، فصور الضر شيئًا أحاط بهم وغطاهم ثم يرفعه الله؛ فتظهر شدة الإحاطة أولًا وتمام الانفراج بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص645، تحت عنوان «بلاغة استعمال فعل (يكشف)، دون ما يقاربه في المعنى»","url":""}]},{"id":"s6-277","number":277,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة تعدية الدعاء بـ﴿إلى﴾ في قوله تعالى: ﴿ما تدعون إليه﴾؟","answer":"ضُمّن ﴿تدعون﴾ معنى تتضرعون؛ أي يكشف ما تدعون الله متضرعين إليه من أجله. فحرف الانتهاء يصور توجه الدعاء والافتقار إلى الله، وجمع التضمين في لفظ واحد معنى الدعاء ومعنى التضرع الخالص.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص646، تحت «بلاغة استعمال حرف (إلى) في قوله: ﴿تدعون إليه﴾»","url":""}]},{"id":"s6-278","number":278,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما غرض تقييد كشف الضر بقوله تعالى: ﴿إن شاء﴾؟","answer":"ليبين أن الدعاء لا يوجب على الله شيئًا، وأن الكشف تابع لحكمته ومشيئته؛ فقد يكشف الضر وقد يبقيه لحكمة يعلمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص646–647، تحت عنوان «غرض قيد ﴿إن شاء﴾»","url":""}]},{"id":"s6-1130","number":1130,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"لماذا حُذف جواب الشرط في قوله تعالى: ﴿إن شاء﴾؟","answer":"دل عليه ما تقدم من فعل الكشف، أي إن شاء كشفه؛ فالحذف يجنب تكرار اللفظ ويركز على تعلق الفرج بالمشيئة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص647، تحت عنوان «دلالة حذف جواب الشرط ﴿إن شاء﴾»","url":""}]},{"id":"s6-279","number":279,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة قوله تعالى: ﴿وتنسون ما تشركون﴾، وهل المراد النسيان الحقيقي؟","answer":"يحتمل النسيان الحقيقي؛ إذ تذهلهم الشدة عن أصنامهم وينشغلون بمن يملك كشفها، ويحتمل النسيان المجازي بمعنى الترك والإعراض. وكلا الوجهين يكشف أن المعبودات تغيب عن القلوب في الموضع الذي يُختبر فيه صدق الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص647–648، تحت «دقة التعبير بفعل النسيان ﴿تنسون﴾»","url":""}]},{"id":"s6-280","number":280,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة التعبير بـ﴿ما تشركون﴾، دون: مَن تشركون؟","answer":"﴿ما﴾ تعم كل ما أشركوه، وتنزل معبوداتهم منزلة غير العاقل تحقيرًا لها وإظهارًا لعجزها عن فهم الدعاء أو كشف الضر. فهي أوسع من ﴿من﴾ التي يغلب استعمالها في العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص646، تحت «نكتة التعبير بـ﴿ما﴾ بدلًا من الاسم الموصول الظاهر»","url":""}]},{"id":"s6-281","number":281,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة حذف المرسلين في قوله تعالى: ﴿ولقد أرسلنا إلى أمم من قبلك﴾؟","answer":"التقدير: أرسلنا رسلًا، وحذف المفعول لأن فعل الإرسال والسياق يدلان عليه. فاتجهت العناية إلى الأمم وموقفها من التكذيب والأخذ، وهو المقصود في مقام التهديد والوعيد، دون حاجة إلى تعيين الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص651، تحت «نكتة حذف مفعول ﴿أرسلنا﴾».","url":""}]},{"id":"s6-282","number":282,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة جمع ﴿أمم﴾ وتنكيرها؟","answer":"الجمع والتنكير يدلان على أمم كثيرة متنوعة تعاقبت قبل بعثة النبي ﷺ، فالسنة التي تذكرها الآية ليست حادثة منفردة. وفي عدم تسميتها توجيه النظر إلى القانون الجامع: إرسال، ثم ابتلاء، ثم موقف من التضرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص652، تحت «دلالة الجمع والتنكير في لفظ ﴿أمم﴾»","url":""}]},{"id":"s6-283","number":283,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة تقديم ﴿إلى أمم﴾ على ﴿من قبلك﴾؟","answer":"جاء ﴿من قبلك﴾ وصفًا للأمم، فترتيبه بعد الموصوف مناسب لأصل التركيب. وفي البدء بـ﴿إلى أمم﴾ عناية بما سيخبر عنه من تاريخها وعاقبتها، ثم يصل القيد الزمني ذلك التاريخ برسالة النبي ﷺ، تسليةً له وإنذارًا لمعاصريه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص652–653، تحت «وجه تقديم ﴿إلى أمم﴾ على ﴿من قبلك﴾»","url":""}]},{"id":"s6-284","number":284,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة توجيه الخطاب إلى النبي ﷺ في قوله تعالى: ﴿من قبلك﴾، دون: من قبلهم؟","answer":"بعد حذف مفعول ﴿أرسلنا﴾، أشارت إضافة ﴿قبل﴾ إلى ضمير النبي ﷺ إلى الرسل السابقين؛ فهو رسول جاء بعدهم وخاتم النبيين. وبذلك اتصل خبر الأمم السابقة برسالته، وفيه تسلية له وتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص653، تحت «بلاغة الإشارة إلى المرسلين في قوله: ﴿قبلك﴾»","url":""}]},{"id":"s6-285","number":285,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما نوع الفاء في قوله تعالى: ﴿فأخذناهم بالبأساء والضراء﴾؟","answer":"هي فاء فصيحة تكشف كلامًا مطويًا، أي أرسلنا إليهم الرسل فكذبوهم فأخذناهم؛ فربطت الأخذ بسبب التكذيب بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص653–654، تحت عنوان «نوع الفاء في قوله: ﴿فأخذناهم﴾»","url":""}]},{"id":"s6-1131","number":1131,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"لماذا قيل: ﴿فأخذناهم﴾ دون «فعاقبناهم»؟","answer":"الأخذ يصور التمكن والإحاطة بهم تحت سلطان الشدة، وهو أنسب بابتلاء يراد منه الإيقاظ والتضرع؛ أما العقاب فيوحي ابتداءً بجزاء نهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص654، تحت عنوان «سر استعمال لفظ ﴿فأخذناهم﴾، دون (فعاقبناهم)»","url":""}]},{"id":"s6-286","number":286,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما نكتة ذكر البأساء والضراء متعلقًا للأخذ في قوله تعالى: ﴿فأخذناهم بالبأساء والضراء﴾؟","answer":"بين نوع الأخذ وأنه ابتلاء يمس أحوالهم وأبدانهم ليكسر الغفلة ويحملهم على التضرع، كما استوعب جهات الشدة التي توقظ الإنسان عادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص655، تحت عنوان «نكتة ذكر متعلق الأخذ، وهو البأساء والضراء»","url":""}]},{"id":"s6-1132","number":1132,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما الفرق بين البأساء والبأس؟","answer":"البأساء تستعمل في شدة الحال والفقر وما يمس المال والمعاش، أما البأس فيكثر في القوة وشدة الحرب والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص659–660، تحت عنوان «البأساء والبأس»","url":""}]},{"id":"s6-1133","number":1133,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما الفرق بين الضراء والضر؟","answer":"الضراء شدة تمس البدن كالمرض والوجع، أما الضر فأعم في كل أذى ونقص؛ فاختيرت الضراء هنا لمقابلة البأساء واستيعاب جهة البدن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص660، تحت عنوان «الضراء والضر»","url":""}]},{"id":"s6-287","number":287,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة ﴿لعلهم يتضرعون﴾ مع علم الله بما سيكون؟","answer":"ليست ﴿لعل﴾ للشك في علم الله، بل تبين الغاية التي من أجلها وقع الابتلاء، وتعرض التضرع نتيجةً مرجوة بحسب ما تقتضيه الأسباب ويعرفه المخاطبون. وفيها إبقاء باب الرجوع مفتوحًا لهم قبل حلول العقوبة القاطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص656–657، تحت «دلالة حرف الترجي (لعل) في سياق الآية»","url":""}]},{"id":"s6-288","number":288,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة ﴿لولا﴾ في قوله تعالى: ﴿فلولا إذ جاءهم بأسنا تضرعوا﴾؟","answer":"خرجت من أصل امتناع الشيء إلى التوبيخ والتحضيض: هلا تضرعوا حين جاءهم البأس؟ فهي تنكر عليهم ترك ما كان جديرًا أن يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص662–663، تحت عنوان «دلالة حرف (لولا) بين النفي والتحضيض»","url":""}]},{"id":"s6-1134","number":1134,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"لماذا قُدم قوله تعالى: ﴿إذ جاءهم بأسنا﴾ على ﴿تضرعوا﴾؟","answer":"لإبراز الظرف الذي كان يقتضي التضرع؛ فقد حضر سبب الانكسار ثم لم تقع نتيجته، فكان تقديمه أشد في التوبيخ والتعجيب من قسوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص663–664، تحت عنوان «دلالة تقديم ﴿إذ جاءهم بأسنا﴾ على ﴿تضرعوا﴾»","url":""}]},{"id":"s6-289","number":289,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما المجاز في قوله تعالى: ﴿جاءهم بأسنا﴾؟","answer":"استعير المجيء لوصول البأس وحلوله بهم، فصُور العذاب كقادم قصدهم حتى أحاط بهم، مما يشخص الشدة ويقرب مشهدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص664، تحت عنوان «بلاغة المجاز في قوله: ﴿جاءهم بأسنا﴾»","url":""}]},{"id":"s6-1135","number":1135,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة إضافة البأس إلى ضمير العظمة في قوله تعالى: ﴿بأسنا﴾؟","answer":"تعظم البأس ببيان مصدره؛ فهو صادر عن قدرة الله التي لا تقاوم، وفي الإضافة تهويل لما نزل بهم وتنبيه إلى أنه لم يكن حادثًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص664، تحت عنوان «دلالة إضافة (البأس) إلى ضمير العظمة في ﴿بأسنا﴾»","url":""}]},{"id":"s6-290","number":290,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة تكرار مادة التضرع بعد قوله تعالى: ﴿لعلهم يتضرعون﴾؟","answer":"تكرر لفظ التضرع للتأكيد على أن ما عولجوا بالبأساء والضراء لأجله هو رجوعهم إلى الله، وأن امتناعهم عنه عند مجيء البأس كان سبب النقمة ودليل كبرهم وكفرهم واستحقاقهم العذاب الشديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص664–665، تحت «دلالة تكرار لفظ ﴿تضرعوا﴾».","url":""}]},{"id":"s6-291","number":291,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة الاستدراك بـ﴿ولكن﴾ في قوله تعالى: ﴿ولكن قست قلوبهم﴾؟","answer":"استدرك بها على النتيجة المنتظرة من البأس؛ فبدل أن تلين قلوبهم ويتضرعوا حالت القسوة بينهم وبين الانتفاع بالشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص665–666، تحت عنوان «بلاغة استعمال حرف الاستدراك ﴿ولكن﴾ معطوفًا»","url":""}]},{"id":"s6-1136","number":1136,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما الاستعارة في قوله تعالى: ﴿قست قلوبهم﴾؟","answer":"استعيرت صلابة الأجسام للقلوب التي لا تنفذ إليها الموعظة ولا تلين عند البلاء؛ فصورت غلظها المعنوي بصورة حجر لا يتأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص666–667، تحت عنوان «بلاغة الاستعارة في لفظ ﴿قست﴾»","url":""}]},{"id":"s6-292","number":292,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة الماضي في قوله تعالى: ﴿قست قلوبهم﴾؟","answer":"دل الماضي على تحقق القسوة وثبوتها قبل مجيء البأس، ولذلك بقيت القلوب على صلابتها حين طرأ الابتلاء فلم تنتفع به. فهو يسجل علةً راسخة لا انفعالًا عابرًا وقع بعد الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص667، تحت «دلالة المضي في ﴿قست﴾»","url":""}]},{"id":"s6-293","number":293,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة عطف قوله تعالى: ﴿وزين لهم الشيطان﴾ على قسوة قلوبهم؟","answer":"جمع سببين لترك التضرع: قلوبًا لا تلين، وشيطانًا يجمل لها الباطل؛ فكان التزيين متممًا لبيان إصرارهم بعد نزول البأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص667–668، تحت عنوان «بلاغة عطف ﴿وزين لهم الشيطان﴾ على الجملة السابقة»","url":""}]},{"id":"s6-1137","number":1137,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"لماذا اختير فعل ﴿زين﴾ في قوله تعالى: ﴿وزين لهم الشيطان﴾؟","answer":"لأنه يدل على إلباس القبيح صورة الحسن حتى تميل إليه النفس، فيكشف أن أعمالهم لم تتغير حقيقتها وإنما تغيرت صورتها في أعينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص668، تحت عنوان «نكتة استعمال ﴿زين﴾ دون مرادفاتها»","url":""}]},{"id":"s6-1138","number":1138,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما نكتة تقديم ﴿لهم﴾ في قوله تعالى: ﴿وزين لهم الشيطان﴾؟","answer":"قدم الجار والمجرور للعناية بحالهم والتنبيه إلى اختصاصهم بقبول هذا التزيين؛ إذ لم يستجب له من عصمه الإيمان والبصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص668، تحت عنوان «نكتة تقديم الجار والمجرور على المسند إليه»","url":""}]},{"id":"s6-1139","number":1139,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة تعريف ﴿الشيطان﴾ في قوله تعالى: ﴿وزين لهم الشيطان﴾؟","answer":"يفيد الجنس، فيشمل كل متمرد يزين الباطل من شياطين الجن والإنس، مع استحضار رأس الشر المعروف بهذه الصفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص669، تحت عنوان «معنى التعريف في لفظ ﴿الشيطان﴾»","url":""}]},{"id":"s6-294","number":294,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يعملون﴾؟","answer":"تحتمل المصدرية، فيكون المعنى تزيين عملهم على العموم، وتحتمل الموصولية، فيراد الشيء الذي اعتادوا عمله؛ وفي الوجهين يعم التزيين مسلكهم الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص669، تحت عنوان «دلالة ﴿ما﴾ في قوله: ﴿ما كانوا يعملون﴾»","url":""}]},{"id":"s6-1140","number":1140,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"لماذا قيل: ﴿يعملون﴾ دون «يفعلون» أو «يصنعون»؟","answer":"العمل أعم في السلوك المكتسب المتكرر، بخلاف الصنع الذي يغلب فيه الإتقان والحرفة، والفعل الذي يصدق على مجرد وقوع الحدث؛ فناسب أعمال عامة المكلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص669–670، تحت عنوان «دلالة استعمال فعل ﴿يعملون﴾ دون (يفعلون) أو (يصنعون)»","url":""}]},{"id":"s6-295","number":295,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما أثر الفاء الفصيحة في قوله تعالى: ﴿فلما نسوا ما ذكروا به﴾؟","answer":"أفصحت عن كلام محذوف دل عليه السياق، أي ذُكروا وحُذروا فلم ينتفعوا، ثم ربطت إعراضهم بما تلاه من فتح أبواب النعم استدراجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص673، تحت عنوان «أثر الفاء الفصيحة في تقدير المحذوف في قوله: ﴿فلما نسوا﴾»","url":""}]},{"id":"s6-1141","number":1141,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما المجاز في استعمال النسيان في قوله تعالى: ﴿نسوا ما ذكروا به﴾؟","answer":"أطلق النسيان وأريد الترك والإعراض المتعمد؛ لأنهم عاملوا التذكير معاملة الشيء المنسي الذي لا يلتفت إليه، مع قيام الحجة في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص674، تحت عنوان «بلاغة المجاز المرسل في استعمال مادة النسيان»","url":""}]},{"id":"s6-296","number":296,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة بناء ﴿ذُكّروا به﴾ للمفعول؟","answer":"بُني الفعل للمفعول للاهتمام بما ذُكِّروا به، لا بتعيين من ذكّرهم؛ فالمقصود أنهم أغفلوا مضمون الدعوة، وفي ذلك تأكيد استقلال الرسالة ورفعة مكانتها وأن قيمتها لذاتها لا لشخص المبلّغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص675، تحت «دلالة بناء فعل ﴿ذُكّروا﴾ للمفعول، وتعديته بحرف الباء».","url":""}]},{"id":"s6-297","number":297,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا قيل: ﴿فتحنا عليهم أبواب كل شيء﴾ دون «بسطنا عليهم» أو «رزقناهم»؟","answer":"الفتح يصور النعم كأبواب مغلقة أزيلت حواجزها فتدفقت عليهم من جهات كثيرة، وهو أبلغ في السعة والتتابع من مجرد البسط أو الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص675–676، تحت عنوان «براعة استعمال ﴿فتحنا﴾ دون (بسطنا عليهم) أو (رزقناهم)»","url":""}]},{"id":"s6-298","number":298,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة تعدية الفتح بـ﴿على﴾ في قوله تعالى: ﴿فتحنا عليهم﴾، دون: فتحنا لهم؟","answer":"اختيرت ﴿على﴾ لتصوير إقبال الدنيا عليهم من جميع أقطارها بألوان النعم، وللإشعار باستعلاء الفاتح وتمكنه؛ وكان ظاهر الفتح امتنانًا يدعو إلى الشكر، لكنهم حولوه بإعراضهم إلى استدراج.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص676، تحت «بلاغة تعدية ﴿فتحنا﴾ بحرف الاستعلاء ﴿عليهم﴾ دون اللام».","url":""}]},{"id":"s6-299","number":299,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة جمع ﴿أبواب﴾ في قوله تعالى: ﴿فتحنا عليهم أبواب كل شيء﴾؟","answer":"يدل الجمع على تعدد جهات النعم والخيرات وتتابعها عليهم، فكأن لكل نوع منها بابًا فتح حتى اتسعت عليهم الدنيا من وجوه كثيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص677، تحت عنوان «دلالة جمع أبواب المضافة لمضاف»","url":""}]},{"id":"s6-1142","number":1142,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"كيف يُفهم عموم ﴿كل شيء﴾ في قوله تعالى: ﴿أبواب كل شيء﴾؟","answer":"العموم مقيد بالسياق، أي كل شيء من النعم التي يرغبون فيها وتصلح لاستدراجهم، لا كل موجود على الإطلاق؛ فالسياق يحدد دائرة اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص677، تحت عنوان «بلاغة التخصيص السياقي في ﴿أبواب كل شيء﴾»","url":""}]},{"id":"s6-300","number":300,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة اجتماع ﴿حتى﴾ مع ﴿إذا﴾ في قوله تعالى: ﴿حتى إذا فرحوا﴾؟","answer":"جعلت ﴿حتى﴾ فرحهم غاية للإمهال وفتح النعم، ثم صورت ﴿إذا﴾ لحظة بلوغ تلك الغاية وانتقالهم المفاجئ إلى الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص678، تحت عنوان «دلالة اجتماع (حتى) مع (إذا)، في ﴿حتى إذا﴾»","url":""}]},{"id":"s6-1143","number":1143,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"كيف دل لفظ ﴿فرحوا﴾ على تحقق مقصود فتح الأبواب؟","answer":"كشف فرح البطر أنهم اطمأنوا إلى النعم وغفلوا عن المنعم والتحذير، فبلغ الاستدراج غايته وصار الأخذ عند شدة أمنهم أوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص678، تحت عنوان «دلالة لفظ ﴿فرحوا﴾ على تحقق مقصود فتح الأبواب»","url":""}]},{"id":"s6-1144","number":1144,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما سر التعبير بالماضي في قوله تعالى: ﴿فرحوا بما أوتوا﴾؟","answer":"صور بلوغ الفرح وتحققه منهم كمرحلة مكتملة قبل الأخذ، فثبتت عليهم حال البطر التي استحقوا عندها المباغتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص678–679، تحت عنوان «سر التعبير بصيغة الماضي ﴿فرحوا﴾»","url":""}]},{"id":"s6-301","number":301,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا بُني ﴿أوتوا﴾ للمجهول مع أن المعطي هو الله؟","answer":"بُني ﴿أوتوا﴾ للمجهول تصويرًا لنظرتهم إلى النعم مقطوعة عن واهبها؛ كأنهم تلقوها باستحقاقهم أو علمهم، فدل التعبير على كمال إعراضهم ونسيانهم أن الله هو الذي ابتلاهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص679، تحت «بلاغة التعبير عن فتح الأبواب ﴿بما أوتوا﴾»","url":""}]},{"id":"s6-302","number":302,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة إسناد الأخذ إلى ضمير العظمة في قوله تعالى: ﴿أخذناهم﴾؟","answer":"يعظم الأخذ ببيان أنه صادر عن قدرة الله القاهرة، فيصور تمام التمكن منهم واستحالة إفلاتهم بعد طول الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص679، تحت عنوان «دلالة فعل الأخذ المسند إلى ضمير العظمة»","url":""}]},{"id":"s6-1145","number":1145,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا حُذف متعلق فعل الأخذ في قوله تعالى: ﴿أخذناهم بغتة﴾؟","answer":"أطلق الأخذ من غير تقييده بنوع عذاب ليشمل كل ما يتصور من العقوبة والاستئصال، وليذهب ذهن السامع في تهويله كل مذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص679–680، تحت عنوان «دلالة حذف متعلق فعل (أخذنا)»","url":""}]},{"id":"s6-1146","number":1146,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا قيل: ﴿بغتة﴾ دون «فجأة»؟","answer":"البغتة تجمع سرعة الوقوع وخفاء مقدماته مع عدم الاستعداد له، أما المفاجأة فقد تقع بعد أمارات؛ فكانت أبلغ في تصوير أخذهم وهم آمنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص680، تحت عنوان «نكتة استعمال ﴿بغتة﴾ دون فجأة»","url":""}]},{"id":"s6-303","number":303,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا هم مبلسون﴾ بالجملة الاسمية؟","answer":"الجملة الاسمية في ﴿فإذا هم مبلسون﴾ تثبت عليهم حال الإبلاس وتصور استقرارها عقب الأخذ؛ انتقلوا في لحظة من فرح البطر إلى حيرة ويأس لا يجدون منه مخرجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص681، تحت «دلالة التعبير بالجملة الاسمية ﴿هم مبلسون﴾»","url":""}]},{"id":"s6-304","number":304,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا اختير لفظ ﴿مبلسون﴾، لا: يائسون؟","answer":"الإبلاس أخص من مجرد اليأس؛ فهو يأس يصحبه تحير وانقطاع حجة وسكوت من شدة الصدمة. لذلك صورت ﴿مبلسون﴾ ما أحدثته الأخذة المفاجئة في ظاهرهم وباطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص680–681، تحت «سر استعمال ﴿مبلسون﴾ دون ما يقاربها في المعنى»","url":""}]},{"id":"s6-305","number":305,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عبّر عن استئصالهم بقوله: ﴿فقطع دابر القوم﴾؟","answer":"الدابر آخر القوم ومن يأتي في أثرهم، وقطعه كناية عن الاستئصال الكامل؛ فلم يُهلك بعضهم ويُبق بعضًا، بل انقطع امتدادهم وآثار ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص687، تحت «بلاغة الكناية عن الاستئصال بقطع الدابر»","url":""}]},{"id":"s6-306","number":306,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"ما دلالة إيثار الاسم الموصول في قوله تعالى: ﴿القوم الذين ظلموا﴾؟","answer":"جعلت الصلة علة قطع دابرهم، فليس الاستئصال لمجرد ذواتهم وإنما لما تحقق فيهم من الظلم واستمروا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص688، تحت عنوان «دلالة إيثار التعبير بالموصول»","url":""}]},{"id":"s6-1147","number":1147,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عُبر عنهم بلفظ ﴿القوم﴾ في قوله تعالى: ﴿القوم الذين ظلموا﴾؟","answer":"استوعب اللفظ جماعتهم الذين تمالؤوا على الظلم، وأظهر أنهم صاروا فريقًا متصفًا به فاستحقوا عاقبة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص690، تحت عنوان «علة التعبير بلفظ القوم»","url":""}]},{"id":"s6-307","number":307,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عُدل عن وصفهم بالكفر إلى ﴿الذين ظلموا﴾؟","answer":"الظلم أعم من الكفر؛ فهو يشمل الشرك وتكذيب الآيات والمعاصي ووضع الأشياء في غير مواضعها. فالوصف يجمع وجوه جرمهم ويبين أن الهلاك جزاء ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص690–691، تحت «دلالة اختيار الوصف بالظلم دون الكفر»","url":""}]},{"id":"s6-308","number":308,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عُطف الحمد على هلاك الظالمين: ﴿والحمد لله رب العالمين﴾؟","answer":"عُقِّب هلاك الظالمين بالحمد لأن قطع دابرهم نعمة تستوجب الشكر؛ ففيه نجاة الرسل والمؤمنين، وكفاية شر الظالمين، وتخليص الأرض من فسادهم، وإنجاز وعد الله بالنصر وإعلاء كلمة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص691–692، تحت «فائدة التعقيب بالحمد على إهلاك الظالمين»","url":""}]},{"id":"s6-309","number":309,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"ما سر وصف الله بـ﴿رب العالمين﴾ بعد ذكر استئصال الظالمين؟","answer":"لأن قطع دابرهم بعد تنوع الابتلاء من مقتضى تدبير الربوبية وحكمتها، وفي زوالهم رحمة بالعالمين تستوجب الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص693، تحت عنوان «سر الوصف بـ﴿رب العالمين﴾ بعد ذكر العذاب»","url":""}]},{"id":"s6-1148","number":1148,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا قيل: ﴿رب العالمين﴾ دون «رب الناس»؟","answer":"لأن الحمد على عدله ورحمته لا يختص بالناس، بل يشمل جميع الأجناس والعوالم التي تنتفع بزوال الفساد والظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص693، تحت عنوان «علة التعبير بـ﴿رب العالمين﴾ دون (رب الناس)»","url":""}]},{"id":"s6-310","number":310,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿إن أخذ الله سمعكم وأبصاركم﴾، فعبّر عن سلب الحواس بالأخذ؟","answer":"الأخذ يصور السمع والأبصار نعمًا في ملك الله، متى شاء قبضها وسلب الانتفاع بها؛ فيوقظ الإنسان إلى أنه لا يملك حواسه استقلالًا ولا يستطيع ردها إذا أخذها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص697، تحت «دلالة التعبير بالأخذ دون السلب».","url":""}]},{"id":"s6-311","number":311,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا أُفرد ﴿سمعكم﴾ وجُمعت ﴿أبصاركم﴾؟","answer":"أُفرد السمع لأنه مصدر يدل على الجنس، ولأن المسموع الواحد يصل إلى جماعة من جهة واحدة؛ وجُمعت الأبصار لتعدد العيون وجهات النظر والمدركات المرئية باختلاف الأشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص698، تحت «السر في إفراد السمع وجمع الأبصار».","url":""}]},{"id":"s6-312","number":312,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا أُسند الأخذ إلى السمع والبصر دون القلب؟","answer":"لأن سلب السمع والبصر يبقي أصل التكليف قائمًا، أما القلب فهو مناط العقل؛ فناسب أن يفرض أخذ الحاستين مع إبقاء القلب موجودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص697، تحت عنوان «نكتة إسناد الأخذ للسمع والبصر دون القلب»","url":""}]},{"id":"s6-1149","number":1149,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما دلالة إسناد الختم إلى القلوب في قوله تعالى: ﴿وختم على قلوبكم﴾؟","answer":"الختم يصور منع الحق من النفاذ إليها مع بقائها، فلا تعقل الدليل ولا تنتفع به؛ وبذلك يستمر التكليف وتظهر شدة الحرمان من الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص697–698، تحت عنوان «دلالة إسناد الختم على القلوب»","url":""}]},{"id":"s6-313","number":313,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لم استعمل ﴿وختم على قلوبكم﴾ هنا بدل الطبع على القلوب؟","answer":"جاء الختم ملائمًا للتهديد والتخويف؛ فهو يصور المنع من نفاذ الحق، من غير أن يقتضي وحده ثبات ذلك المنع ولزومه كما يفيده الطبع في هذا الفرق. فالسياق يحذرهم مما قد يحل بهم ليبقى باب الرجوع حاضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص699–700، تحت «نكتة إيثار الختم على الطبع»","url":""}]},{"id":"s6-314","number":314,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿من إله غير الله يأتيكم به﴾؛ وإلى ماذا يعود ضمير ﴿به﴾ مع تعدد المذكورات؟","answer":"يجوز أن يعود ﴿به﴾ إلى المأخوذ المفهوم من الكلام، فيجمع السمع والبصر وإدراك القلب في معنى واحد، أو أن يجري مجرى الإشارة إلى المذكور كله. وقيل يعود إلى السمع وحده، فتوافقه الباء في الإفراد؛ وكل وجه يرد القدرة على إعادة النعمة إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص700–701، تحت «علة إفراد الضمير ومرجعه جمع»","url":""}]},{"id":"s6-315","number":315,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا قيل: ﴿من إله غير الله يأتيكم به﴾ بطريق الاستفهام بدل النفي الصريح؟","answer":"الاستفهام الإنكاري يلزمهم أن يجيبوا بأن لا إله غير الله يرد السمع والبصر ويفتح القلوب؛ فيصبح إقرارهم نفسه حجة على بطلان شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص701، تحت عنوان «سر إيثار النفي والإنكار بالاستفهام دون النفي الصريح»","url":""}]},{"id":"s6-316","number":316,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما دلالة الأمر بالنظر في قوله تعالى: ﴿انظر كيف نصرف الآيات﴾؟","answer":"يوجه إلى تأمل كيفية تنويع الحجج، لا إلى مجرد رؤيتها؛ وفيه تعجيب من وضوحها ومن استمرار الإعراض عنها مع ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص703، تحت عنوان «دلالة الأمر بالنظر إلى كيفية التصريف»","url":""}]},{"id":"s6-1150","number":1150,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما فائدة تصريف الآيات في قوله تعالى: ﴿نصرف الآيات﴾؟","answer":"التصريف تنويع الدلائل والأساليب وتكرارها بين ترغيب وترهيب ونعمة ونقمة، لتقوم الحجة وتناسب تفاوت مدارك المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص704، تحت عنوان «فائدة تصريف الآيات في قوله: ﴿نصرف الآيات﴾»","url":""}]},{"id":"s6-317","number":317,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما دلالة عطف قوله تعالى: ﴿ثم هم يصدفون﴾ على تصريف الآيات؟","answer":"كشف العطف النتيجة المستغربة: تتنوع لهم الآيات وتوضح، ثم يقابلون هذا البيان بالإعراض؛ فاشتد التفاوت بين المقدم والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص704، تحت عنوان «دلالة عطف قوله: ﴿ثم هم يصدفون﴾»","url":""}]},{"id":"s6-1151","number":1151,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا عُطف قوله تعالى: ﴿ثم هم يصدفون﴾ بـ﴿ثم﴾؟","answer":"أفادت الاستبعاد والتعجيب من صدوفهم بعد وضوح الآيات، فالبعد معنوي بين ما يقتضيه البيان من قبول وما وقع منهم من إعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص704–705، تحت عنوان «إيثار التعبير بحرف العطف ﴿ثم﴾»","url":""}]},{"id":"s6-318","number":318,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا أظهر الضمير ﴿هم﴾ في ﴿ثم هم يصدفون﴾؟","answer":"إظهار ﴿هم﴾ يقوي إسناد الصدوف إليهم ويخصهم به؛ فالآيات صُرفت ووضحت، وهم أنفسهم الذين اختاروا الانصراف عنها، وفيه تقريع وتعجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص705، تحت «بلاغة التعبير عن إعراضهم بالجملة الاسمية»","url":""}]},{"id":"s6-319","number":319,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا اختير ﴿يصدفون﴾، لا: يعرضون؟","answer":"الصدوف إعراض مع ميل وانصراف عن الشيء، فهو يصور حركة المتولي بجانبه بعد أن تبين له وجه الحق؛ لذلك كان أبلغ من مطلق الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص705–706، تحت «(يعرضون) و(يصدفون)»","url":""}]},{"id":"s6-320","number":320,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"لم قيل في الوعيد بالعذاب: ﴿قل أرأيتكم﴾، بعد قوله في سلب الحواس: ﴿قل أرأيتم﴾؟","answer":"زادت كاف الخطاب توكيد المواجهة والتنبيه؛ فالوعيد هنا بعذاب أشد من سلب السمع والبصر، فناسبه مزيد تأكيد. أما في فرض سلب الحواس فاكتفي بالخطاب في ﴿أرأيتم﴾، فجاء اختلاف الصياغة موافقًا لدرجة التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص709، تحت «دلالة كاف الخطاب»","url":""}]},{"id":"s6-321","number":321,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما دلالة الجمع بين ﴿بغتة﴾ و﴿جهرة﴾ في وصف مجيء العذاب؟","answer":"استوعب حالتي مجيئه: أن يفجأهم خفي المقدمات، أو يأتيهم ظاهرًا يعاينون أماراته؛ فلا نجاة لهم في أي صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص710، تحت عنوان «دلالة الجمع بين البغتة والجهرة»","url":""}]},{"id":"s6-1152","number":1152,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما سر المقابلة بين البغتة والجهرة؟","answer":"قابل خفاء المجيء بظهوره ليحيط بطرفي الاحتمال ويقرر أن اختلاف طريقة نزول العذاب لا يغير مصير الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص711، تحت عنوان «سر المقابلة بين البغتة والجهرة»","url":""}]},{"id":"s6-322","number":322,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما الغرض البلاغي من الاستفهام في قوله تعالى: ﴿هل يهلك إلا القوم الظالمون﴾؟","answer":"هو استفهام تقريري إنكاري يلزمهم بالإقرار بأن الهلاك عقوبة للظالمين، ويحمل في الوقت نفسه تحذيرًا لهم من البقاء على ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص711–712، تحت عنوان «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s6-1153","number":1153,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"لماذا عُبر بالاستفهام عن النفي في قوله تعالى: ﴿هل يهلك إلا القوم الظالمون﴾؟","answer":"لأن الاستفهام يجعل المخاطب يشارك في تقرير الجواب، فيكون إقراره بأن غير الظالم لا يهلك أوقع عليه من مجرد إخباره بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص712، تحت عنوان «فائدة التعبير بالاستفهام عن النفي»","url":""}]},{"id":"s6-1154","number":1154,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"كيف خُص الهلاك بالظالمين مع أن البلاء قد يصيب غيرهم؟","answer":"المراد هلاك العقوبة والخسران؛ فما يصيب المؤمن من بلاء يكون رفعة أو اختبارًا، أما الظالم فيصيبه وبالًا جزاءً على ظلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص713–714، تحت عنوان «وجه تخصيص العذاب بالظالمين»","url":""}]},{"id":"s6-323","number":323,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما بلاغة العدول من الضمير إلى الاسم الظاهر في قوله تعالى: ﴿القوم الظالمون﴾؟","answer":"عدل عن «أنتم» أو «هم» إلى الاسم الظاهر ليعمم الحكم ويجعله قاعدة تشمل كل قوم تحقق فيهم الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص713، تحت عنوان «بلاغة العدول من الإضمار إلى الإظهار»","url":""}]},{"id":"s6-1155","number":1155,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"لماذا وُصف القوم بالظلم بدل الاكتفاء بضميرهم؟","answer":"ليصرح بعلة الهلاك؛ فوصف الظلم يسجل سبب العقوبة عليهم وينبه المخاطبين إلى طريق النجاة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص713، تحت عنوان «سر التعبير بالوصف دون الضمير»","url":""}]},{"id":"s6-324","number":324,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما دلالة القصر في قوله تعالى: ﴿وما نرسل المرسلين إلا مبشرين ومنذرين﴾؟","answer":"قصر وظيفتهم في البلاغ الذي يجمع البشارة والإنذار، فرد مطالبة المعاندين لهم بما ليس من شأن الرسالة كإنزال العذاب المقترح.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص717، تحت عنوان «دلالة القصر في الآية»","url":""}]},{"id":"s6-1156","number":1156,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا وُصف الرسل بالمبشرين والمنذرين؟","answer":"لأن الدعوة تستجمع ترغيب المطيع في الوعد وتحذير العاصي من الوعيد، فتقيم الحجة وتفتح للإنسان طريق الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص718، تحت عنوان «علة وصف الرسل بالبشارة والإنذار»","url":""}]},{"id":"s6-325","number":325,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما سرّ تقديم التبشير على الإنذار؟","answer":"قُدمت البشارة لإظهار حرص الرسل على إيمان من يدعونهم، وتقديم الأدلة لهم، وتعريفهم بما أعده الله من الثواب؛ وفي ذلك تعليم للدعاة أن يبدؤوا بالبشارة قبل النذارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص719، تحت «القصد إلى البشارة قبل النذارة دعوة لتوقيتها شرعة»","url":""}]},{"id":"s6-326","number":326,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن آمن وأصلح﴾، ولم يكتف بالإيمان؟","answer":"الإيمان يصحح الاعتقاد، والإصلاح يظهر أثره في العمل ويزيل الفساد من النفس والسلوك؛ فلا يكفي ادعاء الإيمان مع الإصرار على ما يناقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص719، تحت «دلالة الجمع بين ﴿آمن﴾ و﴿وأصلح﴾»","url":""}]},{"id":"s6-327","number":327,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا اختير ﴿أصلح﴾، لا: عمل صالحًا؟","answer":"يلائم ﴿أصلح﴾ حال قوم أفسدوا فطرتهم بالشرك وعدم الانتفاع بالآيات؛ فالمطلوب إزالة هذا الفساد وإصلاح النفس والعمل. لذلك أبرز الفعل التحول عما كانوا عليه، تمهيدًا للعمل الصالح، فالتخلية مقدمة على التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص719، تحت «دلالة اختيار ﴿وأصلح﴾ دون (وعمل صالحًا)»","url":""}]},{"id":"s6-328","number":328,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا عُبر عن الخوف بالاسم وعن الحزن بالفعل في قوله تعالى: ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"نفي اسم الخوف ينفي جنسه وثبوته عليهم، ونفي الفعل المضارع يصور استمرار عدم تجدد الحزن؛ فاجتمع عموم الأمن ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «سر التعبير عن الخوف بالاسم والحزن بالفعل»","url":""}]},{"id":"s6-1157","number":1157,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا قُدم نفي الخوف على نفي الحزن؟","answer":"لأن الخوف يتعلق بما يستقبل، والمقام مقام إنذار بما ينتظر الناس، فكان تأمين المؤمنين من المستقبل أولى بالتقديم ثم نفي حزنهم على ما مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «دلالة تقديم الخوف على الحزن في الآية»","url":""}]},{"id":"s6-329","number":329,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما دلالة الجملة الاسمية في قوله تعالى: ﴿فلا خوف عليهم﴾؟","answer":"تفيد ثبات الأمن لهم واستقراره، وتنفي جنس الخوف عنهم نفيًا شاملًا لا يقتصر على لحظة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «إيثار التعبير بالجملة الاسمية»","url":""}]},{"id":"s6-1158","number":1158,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما دلالة المضارع المنفي في قوله تعالى: ﴿ولا هم يحزنون﴾؟","answer":"يصور استمرار انتفاء الحزن وعدم تجدده في مستقبل أحوالهم، فتكتمل لهم الطمأنينة مع نفي الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «دلالة التعبير بالفعل المضارع المنفي»","url":""}]},{"id":"s6-330","number":330,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا عُبر عن إصابة العذاب بالمس في قوله تعالى: ﴿يمسهم العذاب﴾؟","answer":"المس يدل على مباشرة الأثر واتصاله بالبدن، فاختير لتقريب إحساس الألم وشدة ملازمة العذاب لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «إيثار التعبير عن العذاب بالمس دون غيره»","url":""}]},{"id":"s6-1159","number":1159,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما فائدة المضارع في قوله تعالى: ﴿يمسهم العذاب﴾؟","answer":"يستحضر مشهد العذاب ويفيد تجدد وقوعه واستمراره، فكأنه يقع أمام السامع مرة بعد مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «فائدة التعبير عن المس بالفعل المضارع»","url":""}]},{"id":"s6-1160","number":1160,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما الاستعارة في إسناد المس إلى العذاب؟","answer":"صُور العذاب بكائن يباشرهم ويمد أثره إليهم، فأسند إليه المس لتشخيصه وجعل ملاحقته لهم محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «بلاغة الاستعارة في إسناد المس إلى العذاب»","url":""}]},{"id":"s6-331","number":331,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا أضيفت الآيات إلى ضمير العظمة: ﴿بآياتنا﴾؟","answer":"إضافة الآيات إلى ضمير العظمة تشرفها وتبين عظم جناية المكذبين؛ فهم لم يكذبوا كلامًا بشريًا، بل دلائل الله المنسوبة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص723، تحت «نكتة إضافة الآيات إلى ضمير الجمع»","url":""}]},{"id":"s6-332","number":332,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما دلالة الباء في قوله تعالى: ﴿بما كانوا يفسقون﴾؟","answer":"هي للسببية، فربطت مس العذاب بفسقهم وكشفت أن ما أصابهم ثمرة لاختيارهم وخروجهم عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «دلالة الباء في قوله جل شأنه: ﴿بما كانوا يفسقون﴾»","url":""}]},{"id":"s6-1161","number":1161,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا قيل: ﴿يفسقون﴾ دون «يكذبون»؟","answer":"الفسق أعم؛ فهو خروج عن طاعة الله يشمل التكذيب وما يتولد عنه من المعاصي، فبين اتساع جرمهم واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725، تحت عنوان «نكتة التعبير بالفسق دون التكذيب»","url":""}]},{"id":"s6-1162","number":1162,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما فائدة قوله تعالى: ﴿كانوا﴾ في ﴿بما كانوا يفسقون﴾؟","answer":"دل على رسوخ الفسق في ماضيهم واعتيادهم له، فلم يكن زلة عارضة بل سيرة لازمتهم واستحقوا بها العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725، تحت عنوان «فائدة التعبير بالفعل (كانوا)»","url":""}]},{"id":"s6-1163","number":1163,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا جاء خبر ﴿كان﴾ جملة مضارعية في قوله تعالى: ﴿كانوا يفسقون﴾؟","answer":"ليجمع بين ثبوت عادتهم في الماضي وتجدد أفراد الفسق منهم، فتُصور المعصية سلوكًا مستمرًا متكررًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725–726، تحت عنوان «توجيه مجيء خبر (كان) جملة مضارعية»","url":""}]},{"id":"s6-333","number":333,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا اختير ﴿يفسقون﴾، لا: يكفرون؟","answer":"اختير ﴿يفسقون﴾ لأنه أعم من الكفر والتكذيب؛ فالفسق خروج يشمل الكفر والشرك والتكذيب، وكل كافر فاسق وليس كل فاسق كافرًا، فعمم التعبير سبب العذاب ليجمع أنواع خروجهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725، تحت «نكتة التعبير بالفسق دون التكذيب»","url":""}]},{"id":"s6-334","number":334,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا عُبر عن مقدورات الله وأرزاقه بلفظ ﴿خزائن الله﴾؟","answer":"الخزائن مواضع النفائس المدخرة، فصور اللفظ سعة ما عند الله وحفظه ونفاد ما سواه دونه؛ ونفي كونها عند الرسول يرد اقتراحاتهم التي تطالبه بالتصرف فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت عنوان «وجه اصطفاء لفظ ﴿خزائن الله﴾»","url":""}]},{"id":"s6-335","number":335,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"كيف يصور لفظ ﴿خزائن الله﴾ سعة ما عند الله من الخير؟","answer":"شبهت مقدورات الله وتعلقها بالإنعام وإعطاء الخيرات بخزائن أهل اليسار التي تجمع الأموال والأطعمة ونحوها. فالصورة تقرب المعنى إلى الحس، مع بيان أن تلك الخيرات بيد الله، ولا يملك الرسول ﷺ التصرف فيها من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت «وجه اصطفاء لفظ ﴿خزائن الله﴾»","url":""}]},{"id":"s6-336","number":336,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما سرّ تقديم ﴿عندي﴾ على ﴿خزائن الله﴾؟","answer":"قُدمت ﴿عندي﴾ للعناية بدفع ما يطلبه المشركون مما ليس في قدرة الرسول ﷺ؛ فالإنكار موجه إلى أن تكون خزائن الله تحت تصرفه. وبذلك يبرز التقديم موضع تصحيح دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735–736، تحت «نكتة تقديم لفظة ﴿عندي﴾»","url":""}]},{"id":"s6-337","number":337,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا نفى النبي ﷺ علم الغيب مباشرة فقال: ﴿ولا أعلم الغيب﴾؟","answer":"لأن نفي العلم أصرح في رد توهم استقلاله بالغيب من مجرد نفي ادعائه، مع بقاء ما يعلمه بإعلام الله ووحيه خارج هذا الاستقلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص731، تحت عنوان «علة نفي النبي ﷺ معرفة الغيب، دون نفي القول بمعرفته»","url":""}]},{"id":"s6-1164","number":1164,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا أُفرد لفظ ﴿الغيب﴾ في قوله تعالى: ﴿ولا أعلم الغيب﴾؟","answer":"أريد به اسم الجنس الشامل لكل ما غاب، فإفراده أوجز وأدل على استغراق جنس الغيب من غير حاجة إلى جمعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص736، تحت عنوان «سر إفراد الغيب دون جمعه»","url":""}]},{"id":"s6-338","number":338,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا نُفي القول بالملكية في قوله تعالى: ﴿ولا أقول لكم إني ملك﴾ بدل نفي الملكية فقط؟","answer":"لأن المقام رد على دعاواهم ومطالبهم، فنفى النبي ﷺ أن يكون قد ادعى هذه المنزلة أصلًا؛ ويلزم من صدقه في النفي أنه ليس ملكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص731، تحت عنوان «توجيه نفي القول دون نفي النسبة»","url":""}]},{"id":"s6-339","number":339,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما بلاغة تكرار النفي في قوله تعالى: ﴿لا أقول لكم... ولا أعلم... ولا أقول لكم﴾؟","answer":"استقل كل ادعاء بنفيه حتى لا يحمل الكلام على نفي مجموع الصفات مع احتمال بعضها، فأحكم الرد على مقترحاتهم واحدًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص730، تحت عنوان «بلاغة تكرار النفي»","url":""}]},{"id":"s6-1165","number":1165,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا خُصت الخزائن وعلم الغيب والملكية بالنفي؟","answer":"لأن اعتراضاتهم على الرسول كانت تدور حول طلب التصرف في الأرزاق والخوارق ومعرفة المغيبات وأن يكون ملكًا، فنفى ما تعلق بشبهاتهم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص731، تحت عنوان «السر في تخصيص المذكورات بالنفي دون غيرها»","url":""}]},{"id":"s6-1166","number":1166,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما القصر في قوله تعالى: ﴿إن أتبع إلا ما يوحى إلي﴾؟","answer":"قصر شأن الرسول ﷺ على اتباع الوحي، فبين مصدر قوله ووظيفته ورد كل توهم بأنه يتصرف في خصائص الربوبية أو يتبع أهواء المقترحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص732–733، تحت عنوان «بلاغة الحصر والقصر في الآية»","url":""}]},{"id":"s6-340","number":340,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا حصر منهجه في قوله: ﴿إن أتبع إلا ما يوحى إلي﴾؟","answer":"القصر بـ﴿إن... إلا﴾ يحدد منهج الرسول في اتباع الوحي وحده؛ فلا يدعي من خصائص الربوبية شيئًا، ولا يجيب اقتراحاتهم من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص732–733، تحت «بلاغة الحصر والقصر»","url":""}]},{"id":"s6-341","number":341,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ماذا يبرز فعل ﴿أتبع﴾ في قوله: ﴿إن أتبع إلا ما يوحى إلي﴾؟","answer":"يصور الوحي طريقًا يقتفي الرسول ﷺ أثره في قوله وعمله وحكمه؛ فلا ينشئ الرسالة من عند نفسه، ولا يتصرف فيها استجابة لأهواء المقترحين. فالاتباع يبين جهة قيادته ومرجع تصرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص736، تحت «سر التعبير بلفظ ﴿أتبع﴾»","url":""}]},{"id":"s6-342","number":342,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا مثّل المؤمن والكافر بـ﴿الأعمى والبصير﴾؟","answer":"الأعمى مثل لمن حُجب عن دلائل الوحي فلم يهتد بها، والبصير مثل لمن أبصر الحق واتبعه؛ فالصورة تجعل الفرق بين الكافر والمؤمن كفرق محسوس لا يشتبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص733–734، تحت «بلاغة الاستعارة في ﴿الأعمى والبصير﴾»","url":""}]},{"id":"s6-343","number":343,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما سرّ تقديم ﴿الأعمى﴾ على ﴿البصير﴾؟","answer":"قُدِّم الأعمى لأن المشركين، مع ضلالهم وجهلهم، كانوا يزعمون أنهم أعلى من المؤمنين لكثرة أموالهم؛ فجاء الاستفهام لينفي مساواة الأعمى بالبصير، فضلًا عن علوه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت «نكتة تقديم العمى في الذكر على البصر»","url":""}]},{"id":"s6-344","number":344,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لم جاء نفي المساواة في صورة سؤال: ﴿هل يستوي الأعمى والبصير﴾؟","answer":"يحمل الاستفهام السامع على تقرير نفي المساواة بنفسه، إذ الفرق بين العمى والبصر بديهي محسوس. وبهذا يقرب الفرق بين الضال والمهتدي ويجعل إنكار التسوية بينهما أوقع في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص733، تحت «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s6-345","number":345,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما دلالة الحض على التفكر في قوله تعالى: ﴿أفلا تتفكرون﴾؟","answer":"جاء الاستفهام توبيخًا وتحريضًا على إعمال العقل في الفرق الظاهر بين الأعمى والبصير وبين الضلال والهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص734، تحت عنوان «بيان الحض على التفكر في الفاصلة»","url":""}]},{"id":"s6-1167","number":1167,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا خُتمت الآية بالتفكر بدل الدعوة المباشرة إلى الإيمان؟","answer":"لأن التفكر هو الطريق الذي يكشف صدق الوحي والفرق بين البصيرة والعمى، فإذا صح النظر قاد صاحبه إلى الإيمان عن بينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت عنوان «إيثار لفظ التفكير على لفظ الإيمان»","url":""}]},{"id":"s6-346","number":346,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لم رُتبت المنفيات: خزائن الله، ثم علم الغيب، ثم كون الرسول ملكًا؟","answer":"بدأ بما يتصل بالأرزاق التي يتشوفون إليها، ثم بمعرفة الغيب الذي يجهلونه، ثم بدعوى الملكية التي تخرجه عن حقيقة البشر. فتدرج الرد في نقض ما توهموه من لوازم الرسالة، تمهيدًا لإثبات حقيقتها: اتباع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص732، تحت «براعة الترتيب في الجمل المنفية»","url":""}]},{"id":"s6-347","number":347,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنذر به﴾، وإلى ماذا يعود الضمير في ﴿به﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى القرآن المفهوم من قوله قبلها ﴿ما يوحى إلي﴾؛ أي أنذر بالوحي الذين يخافون الحشر. والإضمار يصل الكلام بما قبله ويبين أن أداة الإنذار هي الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص738–739، تحت «بيان مرجع الضمير في قوله ﴿به﴾»","url":""}]},{"id":"s6-348","number":348,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا خُصّ بالإنذار ﴿الذين يخافون أن يحشروا إلى ربهم﴾؟","answer":"خُصوا بالإنذار لأن خوف الحشر يجعلهم أقرب إلى الانتفاع بالموعظة والاستعداد للقاء الله؛ فالمراد من يتوقع الحشر ويهابه، لا من يجحده فلا يصغي إلى الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص739، تحت «السر بذكر الذين يخافون الحشر دون غيرهم».","url":""}]},{"id":"s6-349","number":349,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يحشروا إلى ربهم﴾ بالبناء للمجهول؟","answer":"بُني ﴿يُحشروا﴾ للمفعول للدلالة على أن نفس الحشر هو المرْهوب، فهو جدير بأن يُخشى لذاته من غير تقييد بمن يقع منه الحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص740، تحت «إيثار صيغة الفعل المبني للمفعول»","url":""}]},{"id":"s6-350","number":350,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سر العدول عن ذكر المحشر في قوله تعالى: ﴿أن يحشروا إلى ربهم﴾؟","answer":"صرف النظر من مكان الحشر إلى من يقفون بين يديه؛ فموطن الخوف الحقيقي هو عرضهم على ربهم للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت عنوان «سر العدول عن ذكر المحشر»","url":""}]},{"id":"s6-1168","number":1168,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا قيل: ﴿إلى ربهم﴾ دون «إلى الله»؟","answer":"استحضر وصف الربوبية الذي يجمع الملك والتربية والرعاية؛ فإذا خاف العباد مقام ربهم مع ما فيه من الرحمة كان ذلك أبلغ في المهابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت عنوان «إيثار التعبير بلفظ الربوبية»","url":""}]},{"id":"s6-351","number":351,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا قُدم الولي على الشفيع في قوله تعالى: ﴿ليس لهم من دونه ولي ولا شفيع﴾؟","answer":"لأن الولي أقرب إلى المنصور وأقوى اتصالًا به، فنفي النصير القريب أولًا ثم نفي من يتوسط له من خارج.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت عنوان «نكتة تقديم الولي على الشفيع»","url":""}]},{"id":"s6-1169","number":1169,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما فائدة الجمع بين نفي الولي والشفيع؟","answer":"قطع جميع جهات النجاة المتوهمة: نصرة من يتولى أمرهم، ووساطة من يشفع لهم؛ فلا يملكون من دون الله حماية مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص742، تحت عنوان «فائدة نفي الولي والشفيع عنهم»","url":""}]},{"id":"s6-352","number":352,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿من دونه﴾ بين نفي الولي والشفيع؟","answer":"في ﴿من دونه﴾ تحقير لما سوى الله وبيان لسفوله؛ فكل ما عُبد من دونه لا يستحق العبادة، لأنه تحت قهر عظمته ومتضائل عن رتبته، فلا يصلح وليًا ولا شفيعًا يُتعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت «فائدة التعبير بـ﴿من دونه﴾»","url":""}]},{"id":"s6-353","number":353,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا خُتمت الآية بـ﴿لعلهم يتقون﴾ لا: لعلهم يؤمنون؟","answer":"خُتم بالتقوى لأنها الغاية الأعلى التي يُراد بلوغها بالإنذار، ولا تتأتى إلا بعد الإيمان؛ فالإيمان الصحيح يثمر الخوف، والتقوى أعم لأنها تشمل الإسلام والإيمان، ولذلك كانت أبلغ هنا من الاقتصار على ﴿يؤمنون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص742، تحت «التعبير بالفعل ﴿يتقون﴾ دون (يؤمنون)»","url":""}]},{"id":"s6-354","number":354,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا نُهي عن طرد المؤمنين ولم يقل: «لا تبعدهم»؟","answer":"الطرد إبعاد يصحبه زجر وإهانة، فاختير اللفظ الذي يصور ما طلبه المستكبرون من احتقار الضعفاء ليأتي النهي في غاية الحسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص746، تحت عنوان «دلالة التعبير بالنهي عن الطرد دون الإبعاد»","url":""}]},{"id":"s6-1170","number":1170,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما فائدة النهي في قوله تعالى: ﴿ولا تطرد الذين يدعون ربهم﴾؟","answer":"صان المؤمنين المخلصين وأبطل ميزان الجاه والمال في مجلس النبوة، وفيه رد على المستكبرين الذين أرادوا إقصاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص746–747، تحت عنوان «فائدة النهي في قوله: ﴿ولا تطرد﴾»","url":""}]},{"id":"s6-355","number":355,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا وصفهم بقوله: ﴿الذين يدعون ربهم﴾، لا: المؤمنين أو الفقراء؟","answer":"وُصفوا بعبادتهم لا بفقرهم لأن قيمتهم في إخلاصهم واتصالهم بربهم، لا في منزلتهم الاجتماعية. والصلة نفسها تقيم الحجة على بطلان طردهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص745، تحت «دلالة التعبير بالموصول»","url":""}]},{"id":"s6-356","number":356,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا اختير ﴿يدعون﴾، لا: يعبدون؟","answer":"الدعاء يجمع دعاء العبادة ودعاء المسألة، فيصور توجههم الدائم إلى ربهم افتقارًا وعبادة؛ فهو في هذا المقام أوسع تصويرًا لحالهم من مجرد تسمية العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص745، تحت «نكتة إيثار ﴿يدعون﴾ على (يعبدون)».","url":""}]},{"id":"s6-357","number":357,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿ربهم﴾، دون أن يقال: الله؟","answer":"عُبّر بالربوبية لأن المقام مقام إنعام وتفضل من الله عليهم؛ فقد نهى رسوله ﷺ عن طردهم، وفي إضافته إليهم إشعار بعلو قدرهم ورفعة مكانتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص746، تحت «سر إيثار الربوبية على الألوهية»","url":""}]},{"id":"s6-358","number":358,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا خُصّ الدعاء بـ﴿الغداة والعشي﴾ مع أنهم يعبدونه في سائر الأوقات؟","answer":"الغداة والعشي طرفا النهار، وذكرهما كناية عن المواظبة واستغراق الأوقات، كما أنه يشير إلى أوقات العبادة الظاهرة التي لزموا عليها؛ فلا يراد حصر دعائهم فيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص747، تحت «السر في ذكر وقتي الغداة والعشي».","url":""}]},{"id":"s6-359","number":359,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿يريدون وجهه﴾، وهل المراد الوجه حقيقة في هذا السياق؟","answer":"المراد أنهم يريدون ما عند الله؛ أي يعبدونه مخلصين له، صحيحة نياتهم، متوجهين إليه وحده، لا يريدون بعبادتهم عرضًا من الدنيا ولا رياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص748، تحت «سر التعبير بقوله ﴿يريدون وجهه﴾»","url":""}]},{"id":"s6-360","number":360,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة الإخبار بنفي حسابهم عنه في قوله تعالى: ﴿ما عليك من حسابهم من شيء﴾؟","answer":"نفى أن يتحمل النبي ﷺ شيئًا من حساب المؤمنين أو أن يفتش عن سرائرهم؛ فحسابهم على الله ولا مسوغ لطردهم بظن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص748، تحت عنوان «دلالة الإخبار بنفي حسابهم عنه»","url":""}]},{"id":"s6-1171","number":1171,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما موقع جملة الحساب بين النهي عن الطرد وجوابه؟","answer":"جاءت اعتراضًا يعلل النهي ويزيل سببه المتوهم، ثم عاد السياق إلى نتيجة الطرد في قوله: ﴿فتطردهم فتكون من الظالمين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص748، تحت عنوان «توجيه جملة الحساب بين النهي وجوابه»","url":""}]},{"id":"s6-361","number":361,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة تقديم ما يعود إلى المخاطب في جملتي الحساب؟","answer":"قدم ﴿عليك﴾ في الأولى و﴿من حسابك﴾ في الثانية اعتناءً بمقام النبي ﷺ وتشريفًا للمخاطب مع إحكام المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص750، تحت عنوان «دلالة تقديم كاف الخطاب في الجملتين»","url":""}]},{"id":"s6-1172","number":1172,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما فائدة تقديم المسند على المسند إليه في جملتي الحساب؟","answer":"قدم الجار والمجرور محل العناية ليقوى نفي التبعة عن الجانبين، ويظهر أن الحساب لا يتعلق بأحدهما على الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص750، تحت عنوان «فائدة تقديم المسند على المسند إليه»","url":""}]},{"id":"s6-362","number":362,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة الإتيان بـ﴿من﴾ في جملتي الحساب؟","answer":"دخلت على الحساب وشيء لتفيد استغراق النفي، فلا يتحمل النبي ﷺ أدنى جزء من حسابهم ولا يتحملون أدنى جزء من حسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص749، تحت عنوان «دلالة الإتيان بـ(من)»","url":""}]},{"id":"s6-1173","number":1173,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"كيف تأكد النفي في قوله تعالى: ﴿ما عليك من حسابهم من شيء﴾؟","answer":"تكرر حرف ﴿من﴾ مع النكرة ﴿شيء﴾ في سياق النفي، فنص التركيب على انتفاء كل مقدار من التبعة ولو كان يسيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص749، تحت عنوان «وجه تأكيد النفي»","url":""}]},{"id":"s6-363","number":363,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما معنى الفاء في قوله تعالى: ﴿فتطردهم﴾؟","answer":"هي فاء السببية في جواب النفي؛ أي لا شيء من حسابهم عليك يكون سببًا يبيح طردهم، فانتفى المسوغ الذي توهمه المعترضون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص751، تحت عنوان «معنى الفاء في الآية»","url":""}]},{"id":"s6-1174","number":1174,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة الفاء في قوله تعالى: ﴿فتكون من الظالمين﴾؟","answer":"رتبت الوقوع في الظلم على طردهم، فبينت العاقبة المباشرة لهذا الفعل وحذرت من ميزان يفضل الناس بالجاه والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص752، تحت عنوان «دلالة الفاء في قوله: ﴿فتكون﴾»","url":""}]},{"id":"s6-364","number":364,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لم وصف طرد هؤلاء المؤمنين بأنه ظلم في ﴿فتكون من الظالمين﴾؟","answer":"لأنه وضع للأمر في غير موضعه: يُبعد المخلصون إرضاءً لمن استكبر عنهم، مع أن حسابهم على الله. فالآية تصون حقهم في مجلس الرسالة، وتبطل جعل المال والجاه سببًا لتقديم غيرهم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص752، تحت «علة جعل الطرد ظلمًا»","url":""}]},{"id":"s6-365","number":365,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما الغرض من استئناف قوله تعالى: ﴿وكذلك فتنا بعضهم ببعض﴾؟","answer":"جاء بيانًا لسر مطالبة المتكبرين بطرد المؤمنين؛ فتفاوتهم في الغنى والسبق إلى الإيمان كان ابتلاء كشف حسدهم واستكبارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص754–755، تحت عنوان «الغرض من الاستئناف»","url":""}]},{"id":"s6-1175","number":1175,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما التشبيه في قوله تعالى: ﴿وكذلك فتنا بعضهم ببعض﴾؟","answer":"شبه فتنة هؤلاء بعضهم ببعض بما عرف من سنن الله في ابتلاء الناس بتفاوت الأحوال؛ فكل فريق ممتحن بموقفه من الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص755–756، تحت عنوان «بلاغة التشبيه في الآية»","url":""}]},{"id":"s6-366","number":366,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا كرر ﴿بعض﴾ فقال: ﴿بعضهم ببعض﴾؟","answer":"تكرار ﴿بعض﴾ يبرز تبادل الفتنة بين فريقين؛ فكل بعض ممتحن بالبعض الآخر من جهة مختلفة، لا أن فريقًا واحدًا هو موضع الامتحان وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص755–756، تحت «بلاغة التشبيه في الآية»","url":""}]},{"id":"s6-367","number":367,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا كانت نتيجة الفتنة قولهم: ﴿أهؤلاء من الله عليهم من بيننا﴾؟","answer":"كشفت الفتنة ما في نفوس المستكبرين؛ فقد قاسوا فضل الله بموازين المال والجاه، فاستبعدوا أن يختص بالإيمان من رأوهم دونهم منزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص756–757، تحت «دلالة اللام على العاقبة والصيرورة»","url":""}]},{"id":"s6-368","number":368,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا أشاروا إلى المؤمنين بـ﴿هؤلاء﴾؟","answer":"أشاروا إليهم بـ﴿هؤلاء﴾ احتقارًا لهم؛ إذ استنكفوا أن يخاطبوهم بالضمير لأنهم لا يرونهم أكفاء للمخاطبة، فجاء اسم الإشارة مرسخًا للاستخفاف والتحقير الظاهرين في استفهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص757–758، تحت «نكتة التعريف باسم الإشارة»","url":""}]},{"id":"s6-369","number":369,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا عبّر عن الهداية بقوله: ﴿من الله عليهم﴾؟","answer":"جاء ذكر المنّ عقب الاستفهام الإنكاري ليكشف أنهم استبعدوا وقوع منة الله على هؤلاء، بل أنكروا وقوعها أصلًا بغضًا واستكبارًا؛ فزاد التعبير كشف نظرتهم الطبقية المستعلية لفقراء المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص758، تحت «دلالة إرداف الاستفهام بالفعل ﴿من﴾»","url":""}]},{"id":"s6-370","number":370,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما دلالة التعبير بالظرف في قوله تعالى: ﴿من بيننا﴾؟","answer":"قولهم ﴿من بيننا﴾ يكشف اعتدادهم بأنفسهم؛ استبعدوا أن يتجاوزهم الفضل إلى من عدوهم أقل شأنًا، فجعلوا منزلتهم الدنيوية مقياسًا للاختيار الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص758–759، تحت «دلالة التعبير بالظرف»","url":""}]},{"id":"s6-371","number":371,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أليس الله بأعلم بالشاكرين﴾؟","answer":"هو للتقرير والإنكار على المعترضين، فيلزمهم بالإقرار بأن الله أعلم بمن يستحق مزيد الهداية والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص759، تحت عنوان «الغرض من الاستفهام في: ﴿أليس الله بأعلم بالشاكرين﴾»","url":""}]},{"id":"s6-1176","number":1176,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا قيل: ﴿أليس الله بأعلم بالشاكرين﴾ بطريق الاستفهام بدل الخبر؟","answer":"لأن الاستفهام ينتزع منهم الاعتراف بعلم الله وحكمته، فيكون إقرارهم نفسه جوابًا عن اعتراضهم وأوقع من مجرد الإخبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص759، تحت عنوان «سر إيثار الاستفهام المجازي على الإخبار»","url":""}]},{"id":"s6-372","number":372,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿بأعلم﴾ بصيغة التفضيل؟","answer":"جاء ﴿أعلم﴾ لتقرير علم الله البالغ بمن يستحق الهداية ومن لا يستحقها، وتشير صيغة التفضيل إلى أنه خير من يجزي الشاكرين ويكافئهم بأفضل العطاء والخير والإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص760، تحت «علة إيثار الوصف بالشاكرين»","url":""}]},{"id":"s6-373","number":373,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا وُصف المؤمنون بالشاكرين بدل «المؤمنين»؟","answer":"لأنهم عرفوا نعمة الهداية وقابلوها بالقبول والطاعة، فناسب وصف الشكر مقام الامتنان عليهم بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص760، تحت عنوان «علة إيثار الوصف بالشاكرين»","url":""}]},{"id":"s6-1177","number":1177,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما دلالة ذكر الشكر بعد إنكار المشركين تفضيل المؤمنين؟","answer":"كشف أن مناط الفضل حسن تلقي نعمة الله لا المال والجاه، وعرّض بالمستكبرين الذين جحدوا النعمة واعترضوا على قسمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص760، تحت عنوان «دلالة ذكر الشكر بعد إنكار المشركين»","url":""}]},{"id":"s6-374","number":374,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا جاءك الذين يؤمنون بآياتنا﴾، فعرّفهم بصلة الإيمان؟","answer":"عُرّفوا بصلة الإيمان زيادة في إكرامهم، وتنبيهًا إلى أن الإيمان بآيات الله هو الصفة التي نالوا بها التكريم والتشريف، وجيء بالموصول ليعم الحكم غير أولئك الذين نُهي عن طردهم ممن تحققت فيه الصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص764–765، تحت «فائدة التعريف بالاسم الموصول»","url":""}]},{"id":"s6-375","number":375,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا أُمر النبي أن يبدأهم بقوله: ﴿سلام عليكم﴾؟","answer":"السلام تكريم وأمان يقابلان ما طلبه المشركون من طردهم؛ فأُمر النبي أن يستقبلهم بالتحية والطمأنينة، تمهيدًا لبشارة الرحمة والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص766، تحت «فائدة الأمر بالبدء بالسلام»","url":""}]},{"id":"s6-376","number":376,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا جاء ﴿سلام﴾ نكرة، لا: السلام عليكم؟","answer":"التنكير في ﴿سلام﴾ للتعظيم والعموم؛ أي سلام عظيم شامل ثابت لكم، لا مجرد تحية معهودة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص766، تحت «فائدة التنكير في لفظ (سلام)»","url":""}]},{"id":"s6-377","number":377,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما دلالة إسناد كتابة الرحمة إلى الرب في قوله تعالى: ﴿كتب ربكم على نفسه الرحمة﴾؟","answer":"أبرز وصف الربوبية عنايته بعباده وتربيته لهم، وجعل وعد الرحمة صادرًا منه سبحانه تفضلًا والتزامًا كريمًا لا بإيجاب أحد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص768، تحت عنوان «علة إسناد الكتابة للرب سبحانه»","url":""}]},{"id":"s6-378","number":378,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا جاء قوله تعالى: ﴿بجهالة﴾ حالًا شبه جملة بدل وصف العامل بالجهل؟","answer":"ألصق الجهالة بظرف ارتكاب السوء، فدل على أن الذنب وقع في حال غلبة السفه والهوى، من غير أن يجعل الجهل صفة ثابتة لصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769، تحت عنوان «العدول عن الحال الصفة إلى الحال شبه الجملة»","url":""}]},{"id":"s6-1178","number":1178,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما دلالة تنكير ﴿جهالة﴾ وتقييد السوء بها؟","answer":"عمم التنكير كل حال يغلب فيها الهوى الرشد، وقيد بها السوء لأن المؤمن لا يقدم عليه إلا في حالة تناقض مقتضى العلم والحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769، تحت عنوان «إيثار التنكير في (جهالة)، وفائدة التقييد بها»","url":""}]},{"id":"s6-379","number":379,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا نُكّرت ﴿جهالة﴾؟","answer":"نُكرت ﴿جهالة﴾ لتبقى مطلقة غير مقيدة؛ فسواء أكانت الجهالة ضئيلة أم كبيرة فهي معتبرة في مغفرة الذنوب، وفي ذلك مبالغة في سعة الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769، تحت «إيثار التنكير في جهالة وفائدة التقييد بها»","url":""}]},{"id":"s6-380","number":380,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم تاب من بعده وأصلح﴾، وما دلالة ﴿ثم﴾؟","answer":"تفيد ﴿ثم﴾ التراخي وطول الفاصل بين السوء والتوبة، للدلالة على قبول الرجوع بالندم والإقلاع وإن طال الزمان؛ وهذا أدل على سعة رحمة الله في قبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769–770، تحت «إيثار عطف التوبة بـ﴿ثم﴾»","url":""}]},{"id":"s6-381","number":381,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا عطف ﴿وأصلح﴾ على التوبة؟","answer":"عُطف الإصلاح على التوبة للدلالة على أن استدامة الإصلاح في الشيء الذي تاب منه شرط لقبول التوبة، وأن العمل الصالح يؤكد صدق رجوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص770، تحت «علة عطف الإصلاح على التوبة»","url":""}]},{"id":"s6-382","number":382,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا خُتمت الآية بـ﴿فأنه غفور رحيم﴾ بصيغتي المبالغة؟","answer":"جاء ﴿غفور﴾ بصيغة المبالغة للدلالة على أن الله بالغ الستر والمحو لذنوب عباده؛ فالذنوب وإن عظمت فمغفرته أعظم ورحمته أوسع، عند تحقق شروط التوبة والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص770، تحت «سر التعبير بصيغة المبالغة ﴿غفور رحيم﴾»","url":""}]},{"id":"s6-383","number":383,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"ما دلالة المضارع في قوله تعالى: ﴿وكذلك نفصل الآيات﴾؟","answer":"يدل على تجدد تفصيل الآيات واستمراره، فيشمل ما تقدم بيانه وما يتنزل بعده. فإيضاح الحق وتمييزه متتابع، وليس مقصورًا على البيان المذكور في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص774–775، تحت «سر التعبير بالفعل المضارع»","url":""}]},{"id":"s6-384","number":384,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"ما دلالة اللام في قوله تعالى: ﴿ولتستبين سبيل المجرمين﴾؟","answer":"هي لام الغاية؛ فإبانة طريق المجرمين مقصد من تفصيل الآيات، ليعرف المؤمن الباطل ويتجنبه كما يعرف الحق ويسلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص775، تحت عنوان «دلالة اللام في فعل الإبانة»","url":""}]},{"id":"s6-1179","number":1179,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"ما بلاغة عطف قوله تعالى: ﴿ولتستبين سبيل المجرمين﴾؟","answer":"عطف غاية خاصة ظاهرة الأثر على الغاية العامة المفهومة من تفصيل الآيات، فخص كشف طريق الإجرام بالعناية والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص775، تحت عنوان «بلاغة العطف في جملة ﴿ولتستبين﴾»","url":""}]},{"id":"s6-385","number":385,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"لم ذكر ﴿سبيل المجرمين﴾ دون أن يذكر معها سبيل المؤمنين؟","answer":"بيان أحد الطريقين يكشف ضده، والأشياء تتبين بأضدادها. وخص سبيل المجرمين بالتصريح للتحذير منها وكشف فسادها وقطع حجتهم، بعد أن أوضحت الآيات طريق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص776–777، تحت «علة ذكر التصريح بسبيل المجرمين»","url":""}]},{"id":"s6-386","number":386,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"لم صُرح بـ﴿المجرمين﴾ بدل أن يقال: ولتستبين سبيلهم؟","answer":"التصريح يسجل عليهم وصف الإجرام ويبين سبب ذم طريقهم، كما يجعل الحكم شاملًا لكل من اتصف بهذا الوصف. أما الضمير فيكتفي بالإحالة إلى المذكورين دون إبراز هذه العلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص775، تحت «بلاغة الإظهار موضع الإضمار»","url":""}]},{"id":"s6-387","number":387,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إني نهيت أن أعبد﴾، دون أن يقال: لا أعبد؟","answer":"﴿إني نهيت﴾ يبين أن ترك عبادتهم امتثال لوحي الله وحكم ملزم، لا موقف شخصي قابل للمساومة؛ وفيه إعلان براءة حاسمة من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص780، تحت «علة التعبير بالنهي دون النفي»","url":""}]},{"id":"s6-388","number":388,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا عُبر عن الأصنام بالاسم الموصول في قوله تعالى: ﴿الذين تدعون﴾؟","answer":"جاء على وفق زعم عابديها حين أنزلوها منزلة العقلاء، فحاجهم القرآن بلغتهم وكشف عجز من منحوه تلك المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781، تحت عنوان «إيثار التعبير عن الأصنام بالاسم الموصول»","url":""}]},{"id":"s6-1180","number":1180,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما دلالة إيثار التعبير بلفظ ﴿من دون﴾؟","answer":"يبين أنهم تركوا الأعلى المستحق للعبادة إلى ما هو أدنى منه منزلة وعاجز، فيستجهل اختيارهم ويكشف فساد عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781، تحت عنوان «إيثار التعبير بلفظ ﴿من دون﴾»","url":""}]},{"id":"s6-389","number":389,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما نكتة فصل الأمر الثاني ﴿قل لا أتبع أهواءكم﴾ عن الأول؟","answer":"جاء استئنافًا يبين علة النهي عن عبادة معبوداتهم؛ فباطن الشرك اتباع الهوى من غير برهان، واستقل هذا المعنى بالعناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781، تحت عنوان «نكتة فصل الأمر الثاني ﴿قل لا أتبع﴾ عن الأول»","url":""}]},{"id":"s6-1181","number":1181,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا تكرر الأمر بـ﴿قل﴾ مع قرب ذكره؟","answer":"ليدل على استقلال المقول الثاني وأهميته واختلافه عن الأول، وليشعر بأن كل جواب وحي مأمور بتبليغه صراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781–782، تحت عنوان «علة تكرار الأمر بالقول مع قرب ذكره»","url":""}]},{"id":"s6-390","number":390,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما المجاز في قوله تعالى: ﴿ولا أتبع أهواءكم﴾ بعد النهي عن عبادة آلهتهم؟","answer":"أطلق اتباع الأهواء وأريد عبادة ما اختاروه بلا حجة؛ لأن الشرك ناشئ عن ميل النفس وتقليد الموروث، فكشف التعبير باطن عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص782، تحت عنوان «بلاغة المجاز المرسل ومزيته»","url":""}]},{"id":"s6-391","number":391,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا جُمعت ﴿أهواءكم﴾؟","answer":"جُمعت ﴿أهواءكم﴾ لتعدد ميول المشركين وتناقض معبوداتهم ودوافعهم؛ فالحق واحد، أما الهوى فطرق متفرقة بتفرق أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص782، تحت «إيثار الجمع على الإفراد في لفظ الأهواء»","url":""}]},{"id":"s6-392","number":392,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿قد ضللت إذًا﴾ بالماضي مع أن الضلال مفترض؟","answer":"الماضي مع ﴿قد﴾ يصور الضلال المفروض متحققًا لا شك فيه إن وقع اتباع أهوائهم؛ فجواب الشرط مقدر المعنى كأنه حدث لتيقن نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص783، تحت «نكتة تصدير الجملة بقد»","url":""}]},{"id":"s6-393","number":393,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما فائدة نفي الاهتداء بعد قوله تعالى: ﴿قد ضللت إذًا﴾؟","answer":"جمع بين إثبات الوقوع في الضلال ونفي الدخول في زمرة المهتدين لو اتبع أهواءهم، فسد طريق التأويل وأكد تباعد الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص783، تحت عنوان «فائدة نفي الاهتداء بعد ذكر الضلال»","url":""}]},{"id":"s6-1182","number":1182,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا قيل: ﴿وما أنا من المهتدين﴾ بالجملة الاسمية؟","answer":"لأنها أبلغ في نفي ثبوت صفة الاهتداء واستقرارها من نفي فعل عابر، فتبين أن اتباع الهوى يناقض الانتماء إلى أهل الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص784، تحت عنوان «بيان العدول عن الجملة الفعلية إلى الجملة الاسمية»","url":""}]},{"id":"s6-394","number":394,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿إني على بينة من ربي﴾ بحرف الاستعلاء ﴿على﴾؟","answer":"﴿على﴾ للاستعلاء والتمكن؛ تصور النبي ثابتًا مستمسكًا ببينة تحمل حجته، وفيها ثقته بنصر الله ووضوح ما جاءه من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص788، تحت «فائدة التعبير بحرف الاستعلاء».","url":""}]},{"id":"s6-395","number":395,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"لماذا نُكرت ﴿بينة﴾ في قوله تعالى: ﴿إني على بينة من ربي﴾؟","answer":"للتفخيم، أي على حجة عظيمة واضحة يميز بها الحق من الباطل، لا على دعوى مجردة كما يزعم المكذبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص788، تحت عنوان «بيان التنكير في ﴿على بينة﴾»","url":""}]},{"id":"s6-1183","number":1183,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما دلالة نسبة البينة إلى الرب في قوله تعالى: ﴿من ربي﴾؟","answer":"بينت مصدر الحجة وسلطانها، فهي وحي من الرب المربي الهادي، لا فكرة ابتدعها الرسول من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص788، تحت عنوان «توجيه نسبة البينة إلى الرب»","url":""}]},{"id":"s6-396","number":396,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذبتم به﴾، وإلى ماذا يعود الضمير؟","answer":"اختلف في مرجع الضمير: فالظاهر عوده إلى ﴿ربي﴾ لقربه، أي كذبتم بالله، وقيل يعود إلى ﴿بينة﴾ لأنها بمعنى البيان والقرآن. والأولى عوده إلى الرب لقرب المرجع وعدم احتياجه إلى تأويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص789، تحت «مرجع الضمير في بيان المكذب به»","url":""}]},{"id":"s6-397","number":397,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿ما عندي ما تستعجلون به﴾ بتكرار ﴿ما﴾؟","answer":"﴿ما﴾ الأولى نافية: ليس عندي، والثانية موصولة بمعنى: الذي تستعجلون به. وعُبر بالموصول بدل «العذاب» لإبراز صلة استعجالهم به، والإشارة إلى أنه مؤخر مدخر لهم وواقع بهم لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص790، تحت «إيثار التعبير بالاسم الموصول»","url":""}]},{"id":"s6-398","number":398,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"لماذا وصف طلبهم للعذاب بـ﴿تستعجلون﴾؟","answer":"وُصف طلبهم بالاستعجال لأن الاستعجال طلب الشيء قبل وقته، وقد طلبوا العذاب قبل حينه وجعلوا تأخره ذريعة إلى التكذيب؛ لذلك كان لفظ الاستعجال أدق من الإسراع وأناسب للمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص792–793، تحت «الاستعجال والإسراع»","url":""}]},{"id":"s6-399","number":399,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما دلالة الحصر في قوله تعالى: ﴿إن الحكم إلا لله﴾؟","answer":"قصر الحكم كله على الله، فرد طلبهم إلى مالك الأمر الذي يقدر وقت العذاب ويفصل بين الرسول والمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص790–791، تحت عنوان «دلالة الحصر في قوله تعالى: ﴿إن الحكم إلا لله﴾»","url":""}]},{"id":"s6-1184","number":1184,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"كيف يجتمع عموم الحكم وخصوص المقام في قوله تعالى: ﴿إن الحكم إلا لله﴾؟","answer":"اللفظ يعم كل حكم كوني وشرعي، والسياق يخص منه ما استعجلوه من الفصل وإنزال العذاب؛ فالخاص داخل تحت الأصل العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص791، تحت عنوان «توجيه عموم المحصور وخصوصه»","url":""}]},{"id":"s6-400","number":400,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما دلالة المضارع في قوله تعالى: ﴿يقص الحق﴾؟","answer":"يفيد تجدد بيان الله للحق واستمرار قضائه به، فيطمئن السامع إلى صدق خبره وعدله في الفصل بين المحق والمبطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص791، تحت عنوان «إيثار التعبير بالفعل المضارع ﴿يقص﴾»","url":""}]},{"id":"s6-401","number":401,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"لماذا خُتمت الآية بـ﴿وهو خير الفاصلين﴾ بعد ﴿إن الحكم إلا لله﴾؟","answer":"ختمت الآية بـ﴿وهو خير الفاصلين﴾ تذييلًا يقرر ما قبلها؛ لأن قص الحق يفضي إلى الفصل بين الحق والباطل، والله خير من يبين المحق من المبطل ويفصل بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص791–792، تحت «فائدة التذييل»","url":""}]},{"id":"s6-402","number":402,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"ما بلاغة الفصل في قوله تعالى: ﴿لو أن عندي ما تستعجلون به لقضي الأمر بيني وبينكم﴾؟","answer":"جاءت الجملة جوابًا مستقلًا يبين أثر الفرض السابق: لو كان العذاب في قدرة الرسول لحُسمت الخصومة، لكنها قدرة لله يجريها بحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص795، تحت عنوان «بلاغة الفصل في الآية»","url":""}]},{"id":"s6-403","number":403,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"كيف تعبر ﴿عندي﴾ عن القدرة في قوله: ﴿لو أن عندي ما تستعجلون به﴾؟","answer":"استعملت العندية مجازًا عن القدرة والتمكن من إنزال ما طلبوه؛ فما يكون عند الإنسان يتمكن عادة من التصرف فيه. والمعنى أن إنزال العذاب ليس في قدرة الرسول ﷺ، وإنما أمره إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص795–796، تحت «بلاغة المجاز في لفظ (عندي)»","url":""}]},{"id":"s6-404","number":404,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"لماذا بُني الفعل للمفعول في قوله تعالى: ﴿لقضي الأمر بيني وبينكم﴾؟","answer":"لتركيز النظر على حسم الأمر ووقوع الهلاك الذي يستعجلونه، مع العلم بأن القاضي الحقيقي هو الله؛ وفيه أدب برد القدرة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796، تحت عنوان «إيثار التعبير بالفعل المبني للمفعول»","url":""}]},{"id":"s6-405","number":405,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"لماذا عبّر بـ﴿قضي الأمر﴾ بالبناء للمجهول؟","answer":"بُني ﴿قضي الأمر﴾ للمجهول للعناية بوقوع الإهلاك نفسه، ولأن قاضيه معلوم وهو الله؛ وفي ترك التصريح أدب مع الله وتهويل للمخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796، تحت «إيثار التعبير بالفعل المبني للمفعول»","url":""}]},{"id":"s6-406","number":406,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"كيف يفيد ﴿والله أعلم بالظالمين﴾ التهديد مع أنه خبر عن العلم؟","answer":"العلم هنا كناية عن المجازاة مع دليلها؛ فمن أحاط بظلمهم لا يفوته ما يستحقونه من عقاب. فالجملة تنبه إلى أن تأخير العذاب لا يعني خفاء حالهم، بل أمر جزائهم إلى الله العالم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796، تحت «فائدة التعبير بالعلم في معرض التهديد»","url":""}]},{"id":"s6-407","number":407,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"لماذا أظهر اسم ﴿الظالمين﴾ ولم يقل: والله أعلم بكم؟","answer":"وُضع الظاهر موضع الضمير لكشف صفتهم وسبب الوعيد؛ فهم ظالمون بالشرك وباستعجال العذاب، والحكم يعم كل من اتصف بظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796–797، تحت «علة وضع الظاهر موضع المضمر»","url":""}]},{"id":"s6-408","number":408,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿وعنده مفاتح الغيب﴾ بتقديم ﴿عنده﴾؟","answer":"تقديم ﴿عنده﴾ يفيد التخصيص والحصر: مفاتح الغيب عند الله وحده لا عند غيره، ثم أكد هذا الاختصاص قوله تعالى: ﴿لا يعلمها إلا هو﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص12، تحت «سر تقديم الظرف»","url":""}]},{"id":"s6-409","number":409,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما بلاغة الاستعارة التمثيلية في قوله تعالى: ﴿وعنده مفاتح الغيب﴾؟","answer":"صُوّر الغيب بأبواب أو خزائن مغلقة لا يملك مفاتيحها إلا الله؛ فقرّبت الصورة اختصاصه بعلم الغيب وتمكنه منه إلى الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص12–13، تحت عنوان «بلاغة الاستعارة التمثيلية في المفاتح»","url":""}]},{"id":"s6-1185","number":1185,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"كيف تعددت طرائق الدلالة على اختصاص الله بعلم الغيب في قوله تعالى: ﴿وعنده مفاتح الغيب لا يعلمها إلا هو﴾؟","answer":"اجتمع تقديم الظرف ﴿عنده﴾ مع إضافة المفاتح إلى الغيب والقصر بالنفي والاستثناء؛ فتآزرت هذه الأساليب على توكيد انفراد الله بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص13، تحت عنوان «نكتة تعدد الكيفيات الدالة على اختصاص علم الغيب بالله تعالى»","url":""}]},{"id":"s6-410","number":410,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"هل ﴿مفاتح﴾ جمع مفتاح أم جمع مَفْتَح بمعنى الخزائن، وما أثر المعنيين؟","answer":"تحتمل ﴿مفاتح﴾ أن تكون جمع مفتاح، أي وسائل فتح المغلق والوصول إلى الغيب، وأن تكون جمع مَفْتَح بمعنى الخزائن. وعلى الوجهين لا يملك طرق الغيب ولا خزائنه إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10، تحت «شرح المفردات: ﴿مفاتح الغيب﴾»","url":""}]},{"id":"s6-411","number":411,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما براعة كمال الاتصال بين قوله تعالى: ﴿وعنده مفاتح الغيب﴾ وقوله: ﴿لا يعلمها إلا هو﴾؟","answer":"جاءت الجملة الثانية توكيدًا وبيانًا للأولى؛ فاختصاص المفاتح عنده يقتضي انفراده بعلمها، لذلك اتصلتا من غير عطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص13، تحت عنوان «براعة كمال الاتصال بين الجملتين»","url":""}]},{"id":"s6-412","number":412,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا عُطف قوله تعالى: ﴿ويعلم ما في البر والبحر﴾ على علم مفاتح الغيب؟","answer":"انتقل السياق من الغيب المستور إلى العالم المشاهد، فجمع علم الله بما غاب وبما ظهر، ومهّد للانتقال إلى أدق الجزئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص14، تحت عنوان «توجيه عطف علم ما في الأرض على علم الغيب»","url":""}]},{"id":"s6-1186","number":1186,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما فائدة تخصيص البر والبحر بالذكر بعد عموم مفاتح الغيب؟","answer":"خصهما لأنهما يستوعبان جهات العالم المشاهد عند المخاطبين؛ فدل ذكرهما بعد العموم على إحاطة العلم بالكليات وتفاصيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص14، تحت عنوان «فائدة التخصيص بعد التعميم»","url":""}]},{"id":"s6-1187","number":1187,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما بلاغة القصر في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾؟","answer":"قصر كل سقوط لورقة على أن يكون معلومًا لله، فنفى خروج أدق الحوادث وأكثرها تكررًا عن علمه، وأكد إحاطته بالجزئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص15–16، تحت عنوان «بلاغة القصر في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾»","url":""}]},{"id":"s6-413","number":413,"surah":6,"verses":[59,63],"references":[{"surah":6,"verses":[59,63]}],"verseLabel":"الأنعام: 59؛ الأنعام: 63","question":"ما مزية الطباق بين ﴿البر﴾ و﴿البحر﴾ في قوله تعالى: ﴿ويعلم ما في البر والبحر﴾؟","answer":"جمع الطرفين المتقابلين لاستيعاب جهات العالم المشاهد، فدل بطريق موجز على أن علم الله محيط بما فيهما ظاهرًا وخفيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص14، تحت عنوان «مزية الطباق في البر والبحر»","url":""}]},{"id":"s6-1188","number":1188,"surah":6,"verses":[59,63],"references":[{"surah":6,"verses":[59,63]}],"verseLabel":"الأنعام: 59؛ الأنعام: 63","question":"ما دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾؟","answer":"تشمل الظلمات ظلمة الحس في البر والبحر، وتستعمل مجازًا في الشدائد والحيرة التي تنقطع فيها الأسباب؛ وفي الحالين لا يلجأ المضطر إلا إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص60، تحت عنوان «دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾»","url":""}]},{"id":"s6-414","number":414,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا أوثر لفظ ﴿تسقط﴾ في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾؟","answer":"اختير السقوط لأنه حادث دقيق متجدد لا يلتفت إليه الناس، فإذا كان كل وقوع لورقة معلومًا لله فما هو أعظم أولى بالإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص16، تحت عنوان «علة إيثار لفظ السقوط»","url":""}]},{"id":"s6-415","number":415,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾ بالمضارع؟","answer":"المضارع يستحضر سقوط الأوراق حادثًا متجددًا في كل لحظة ومكان، ويقرر أن علم الله يصاحبه على الدوام، لا أنه علم بجنسه مرة وانقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص15، تحت «نكتة التعبير عن السقوط بالمضارع»","url":""}]}]);
